-- The BlockOS logo: an ASCII grass block with a bite taken out of its side.

local Logo = {}

-- Each letter maps to { Char, Fg, Bg }; spaces are transparent.
local Legend = {
	G = { " ", colors.lime, colors.green },
	g = { "\"", colors.lime, colors.green },
	v = { "'", colors.lime, colors.green },
	D = { " ", colors.orange, colors.brown },
	d = { ".", colors.orange, colors.brown },
	o = { ":", colors.lightGray, colors.brown },
	x = { "'", colors.orange, colors.brown }
}

Logo.Legend = Legend

Logo.Big = {
	"GgGGGvGGGGgGGGvG",
	"GGDGGGGDGGGvG   ",
	"DdDDGDDDDdDD    ",
	"DDDoDDDxDDDD    ",
	"DdDDDDoDDDDdD   ",
	"DDDdDDDDDoDDDDdD",
	"DoDDDxDDDDDDdDDD"
}

Logo.Small = {
	"GvGGgG  ",
	"DDdDD   ",
	"DoDDxD  ",
	"DDDdDDo "
}

Logo.Text = {
	" ____  _            _     ___  ____  ",
	"| __ )| | ___   ___| | __/ _ \\/ ___| ",
	"|  _ \\| |/ _ \\ / __| |/ / | | \\___ \\ ",
	"| |_) | | (_) | (__|   <| |_| |___) |",
	"|____/|_|\\___/ \\___|_|\\_\\\\___/|____/ "
}

local Hex = {}
for Index = 0, 15 do
	Hex[2 ^ Index] = string.format("%x", Index)
end

function Logo.Size(Art)
	Art = Art or Logo.Big
	return #Art[1], #Art
end

function Logo.Draw(T, X, Y, Art)
	Art = Art or Logo.Big
	for Row, Line in ipairs(Art) do
		for Column = 1, #Line do
			local Entry = Legend[Line:sub(Column, Column)]
			if (Entry) then
				T.setCursorPos(X + Column - 1, Y + Row - 1)
				T.blit(Entry[1], Hex[Entry[2]], Hex[Entry[3]])
			end
		end
	end
end

-- Draws the logo with rows revealed up to Progress (0..1), used for intro animations.
function Logo.DrawPartial(T, X, Y, Progress, Art)
	Art = Art or Logo.Big
	local Visible = math.floor(#Art * Progress + .5)
	local Partial = {}
	for Row = #Art - Visible + 1, #Art do
		Partial[#Partial + 1] = Art[Row]
	end
	Logo.Draw(T, X, Y + #Art - Visible, Partial)
end

function Logo.DrawText(T, X, Y, Fg)
	if (Fg) then T.setTextColor(Fg) end
	for Row, Line in ipairs(Logo.Text) do
		T.setCursorPos(X, Y + Row - 1)
		T.write(Line)
	end
end

return Logo
]=]
Files["blockos/lib/sha256.lua"] = [[
-- Pure Lua SHA-256 using the bit32 library available in CC: Tweaked.

local Band, Bor, Bxor, Bnot = bit32.band, bit32.bor, bit32.bxor, bit32.bnot
local Rrotate, Rshift = bit32.rrotate, bit32.rshift

local Sha256 = {}

local K = {
	0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
	0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
	0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
	0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
	0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
	0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
	0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
	0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
}

local function Preprocess(Message)
	local Length = #Message
	local Extra = 64 - ((Length + 9) % 64)
	if (Extra == 64) then Extra = 0 end
	local Bits = Length * 8
	local Suffix = {}
	for Index = 7, 0, -1 do
		Suffix[#Suffix + 1] = string.char(math.floor(Bits / 2 ^ (Index * 8)) % 256)
	end
	return Message .. "\128" .. string.rep("\0", Extra) .. table.concat(Suffix)
end

local function DigestBlock(Message, Start, Hash)
	local W = {}
	for Index = 0, 15 do
		local A, B, C, D = Message:byte(Start + Index * 4, Start + Index * 4 + 3)
		W[Index] = ((A * 256 + B) * 256 + C) * 256 + D
	end
	for Index = 16, 63 do
		local V0 = W[Index - 15]
		local S0 = Bxor(Rrotate(V0, 7), Rrotate(V0, 18), Rshift(V0, 3))
		local V1 = W[Index - 2]
		local S1 = Bxor(Rrotate(V1, 17), Rrotate(V1, 19), Rshift(V1, 10))
		W[Index] = Band(W[Index - 16] + S0 + W[Index - 7] + S1, 0xffffffff)
	end
	local A, B, C, D, E, F, G, H = Hash[1], Hash[2], Hash[3], Hash[4], Hash[5], Hash[6], Hash[7], Hash[8]
	for Index = 0, 63 do
		local S1 = Bxor(Rrotate(E, 6), Rrotate(E, 11), Rrotate(E, 25))
		local Ch = Bxor(Band(E, F), Band(Bnot(E), G))
		local Temp1 = H + S1 + Ch + K[Index + 1] + W[Index]
		local S0 = Bxor(Rrotate(A, 2), Rrotate(A, 13), Rrotate(A, 22))
		local Maj = Bxor(Band(A, B), Band(A, C), Band(B, C))
		local Temp2 = S0 + Maj
		H = G
		G = F
		F = E
		E = Band(D + Temp1, 0xffffffff)
		D = C
		C = B
		B = A
		A = Band(Temp1 + Temp2, 0xffffffff)
	end
	Hash[1] = Band(Hash[1] + A, 0xffffffff)
	Hash[2] = Band(Hash[2] + B, 0xffffffff)
	Hash[3] = Band(Hash[3] + C, 0xffffffff)
	Hash[4] = Band(Hash[4] + D, 0xffffffff)
	Hash[5] = Band(Hash[5] + E, 0xffffffff)
	Hash[6] = Band(Hash[6] + F, 0xffffffff)
	Hash[7] = Band(Hash[7] + G, 0xffffffff)
	Hash[8] = Band(Hash[8] + H, 0xffffffff)
end

-- Returns the raw 32-byte digest.
function Sha256.Digest(Message)
	Message = Preprocess(tostring(Message))
	local Hash = {
		0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
		0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
	}
	for Start = 1, #Message, 64 do
		DigestBlock(Message, Start, Hash)
	end
	local Bytes = {}
	for Index = 1, 8 do
		local Value = Hash[Index]
		Bytes[#Bytes + 1] = string.char(
			math.floor(Value / 16777216) % 256,
			math.floor(Value / 65536) % 256,
			math.floor(Value / 256) % 256,
			Value % 256
		)
	end
	return table.concat(Bytes)
end

function Sha256.Hex(Message)
	return (Sha256.Digest(Message):gsub(".", function(Char)
		return string.format("%02x", Char:byte())
	end))
end

function Sha256.Hmac(Key, Message)
	if (#Key > 64) then Key = Sha256.Digest(Key) end
	Key = Key .. string.rep("\0", 64 - #Key)
	local Inner = Key:gsub(".", function(Char) return string.char(Bxor(Char:byte(), 0x36)) end)
	local Outer = Key:gsub(".", function(Char) return string.char(Bxor(Char:byte(), 0x5c)) end)
	return Sha256.Digest(Outer .. Sha256.Digest(Inner .. Message))
end

return Sha256
]]
Files["blockos/lib/theme.lua"] = [[
-- Colour roles for light and dark appearance, resolved from settings on each call.

local Config = BlockOS.Require("config")

local Theme = {}

local Palettes = {
	light = {
		TopbarBg = colors.white,
		TopbarFg = colors.black,
		TopbarDim = colors.gray,
		DockBg = colors.lightGray,
		DockFg = colors.gray,
		WindowBg = colors.white,
		Panel = colors.lightGray,
		PanelFg = colors.black,
		Text = colors.black,
		SubText = colors.gray,
		Border = colors.lightGray,
		TitleBg = colors.lightGray,
		TitleFg = colors.black,
		TitleIdleBg = colors.lightGray,
		TitleIdleFg = colors.gray,
		InputBg = colors.lightGray,
		InputFg = colors.black,
		ButtonBg = colors.lightGray,
		ButtonFg = colors.black,
		MenuBg = colors.white,
		MenuFg = colors.black,
		MenuDim = colors.lightGray,
		Shadow = colors.gray,
		Dark = false
	},
	dark = {
		TopbarBg = colors.gray,
		TopbarFg = colors.white,
		TopbarDim = colors.lightGray,
		DockBg = colors.gray,
		DockFg = colors.lightGray,
		WindowBg = colors.black,
		Panel = colors.gray,
		PanelFg = colors.white,
		Text = colors.white,
		SubText = colors.lightGray,
		Border = colors.gray,
		TitleBg = colors.gray,
		TitleFg = colors.white,
		TitleIdleBg = colors.gray,
		TitleIdleFg = colors.lightGray,
		InputBg = colors.gray,
		InputFg = colors.white,
		ButtonBg = colors.gray,
		ButtonFg = colors.white,
		MenuBg = colors.gray,
		MenuFg = colors.white,
		MenuDim = colors.lightGray,
		Shadow = colors.black,
		Dark = true
	}
}

Theme.Accents = {
	colors.blue, colors.purple, colors.magenta, colors.red,
	colors.orange, colors.yellow, colors.green, colors.cyan
}

function Theme.Get()
	local Settings = Config.Settings()
	local Base = Palettes[Settings.Theme] or Palettes.light
	local Result = {}
	for Key, Value in pairs(Base) do
		Result[Key] = Value
	end
	Result.Accent = Settings.Accent or colors.blue
	Result.AccentFg = colors.white
	if (Result.Accent == colors.yellow or Result.Accent == colors.cyan) then
		Result.AccentFg = colors.black
	end
	Result.Close = colors.red
	Result.Minimize = colors.yellow
	Result.Zoom = colors.lime
	return Result
end

return Theme
]]
Files["blockos/lib/ui.lua"] = [=[
-- Retained-mode widget toolkit used by BlockOS apps.
-- A Page owns a buffered window; widgets are positioned in page-local coordinates.

local Gfx = BlockOS.Require("gfx")
local Theme = BlockOS.Require("theme")

local Ui = {}

Ui.Current = nil

local InputEvents = {
	mouse_click = true, mouse_drag = true, mouse_up = true, mouse_scroll = true,
	key = true, key_up = true, char = true, paste = true
}

local MouseEvents = { mouse_click = true, mouse_drag = true, mouse_up = true, mouse_scroll = true }

Ui.InputEvents = InputEvents

-- Modifier state shared by pages and dialogs, so a key released inside a dialog is not missed.
Ui.Modifiers = {}

local ModifierKeys = {
	[keys.leftCtrl] = "Ctrl", [keys.rightCtrl] = "Ctrl",
	[keys.leftShift] = "Shift", [keys.rightShift] = "Shift",
	[keys.leftAlt] = "Alt", [keys.rightAlt] = "Alt"
}

local function TrackModifiers(Name, Key)
	if ((Name == "key" or Name == "key_up") and ModifierKeys[Key]) then
		Ui.Modifiers[ModifierKeys[Key]] = Name == "key"
	end
end

local function Resolve(Value, Th, Fallback)
	if (type(Value) == "string") then
		return Th[Value] or Fallback
	end
	if (Value == nil) then return Fallback end
	return Value
end

Ui.Resolve = Resolve

local function Inside(Item, X, Y)
	return X >= Item.X and X < Item.X + Item.W and Y >= Item.Y and Y < Item.Y + Item.H
end

Ui.Inside = Inside

local function TextOf(Value)
	if (type(Value) == "function") then
		return tostring(Value())
	end
	return tostring(Value or "")
end

local function Class(Defaults)
	local NewClass = { Defaults = Defaults }
	NewClass.__index = NewClass
	function NewClass.new(Props)
		local Object = setmetatable(Props or {}, NewClass)
		for Key, Value in pairs(Defaults) do
			if (Object[Key] == nil) then
				Object[Key] = Value
			end
		end
		Object.Visible = Object.Visible ~= false
		if (Object.Init) then
			Object:Init()
		end
		return Object
	end
	return NewClass
end

--
-- Page
--

Ui.Page = {}
Ui.Page.__index = Ui.Page

function Ui.Page.new(Props)
	local Self = setmetatable(Props or {}, Ui.Page)
	Self.Parent = Self.Parent or term.current()
	Self.Widgets = {}
	Self.Intervals = {}
	Self.Dirty = true
	if (Self.X) then
		Self.Fixed = true
	else
		Self.X = 1
		Self.Y = 1
		Self.W, Self.H = Self.Parent.getSize()
	end
	Self.Buffer = window.create(Self.Parent, Self.X, Self.Y, Self.W, Self.H, false)
	return Self
end

function Ui.Page:Add(Item)
	table.insert(self.Widgets, Item)
	Item.Page = self
	self.Dirty = true
	return Item
end

function Ui.Page:Remove(Item)
	for Index, Other in ipairs(self.Widgets) do
		if (Other == Item) then
			table.remove(self.Widgets, Index)
			break
		end
	end
	if (self.Focus == Item) then self.Focus = nil end
	self.Dirty = true
end

function Ui.Page:Clear()
	self.Widgets = {}
	self.Focus = nil
	self.Captured = nil
	self.Dirty = true
end

function Ui.Page:SetFocus(Item)
	if (self.Focus == Item) then return end
	if (self.Focus and self.Focus.OnBlur) then self.Focus:OnBlur() end
	self.Focus = Item
	if (Item and Item.OnFocus) then Item:OnFocus() end
	self.Dirty = true
end

function Ui.Page:GetBg(Th)
	return Resolve(self.Bg, Th, Th.WindowBg)
end

function Ui.Page:Invalidate()
	self.Dirty = true
end

function Ui.Page:Resize()
	if (not self.Fixed) then
		self.W, self.H = self.Parent.getSize()
	end
	self.Buffer.reposition(self.X, self.Y, self.W, self.H)
	if (self.OnLayout) then
		self:OnLayout(self.W, self.H)
	end
	self.Dirty = true
end

function Ui.Page:Draw()
	local T = self.Buffer
	local Th = Theme.Get()
	T.setVisible(false)
	T.setCursorBlink(false)
	T.setBackgroundColor(self:GetBg(Th))
	T.clear()
	if (self.OnDraw) then
		self:OnDraw(T, Th)
	end
	for _, Item in ipairs(self.Widgets) do
		if (Item.Visible) then
			Item:Draw(T, Th, self)
		end
	end
	if (self.OnDrawOver) then
		self:OnDrawOver(T, Th)
	end
	local CursorX, CursorY, CursorColor
	if (self.Focus and self.Focus.Visible and self.Focus.CursorPos) then
		CursorX, CursorY, CursorColor = self.Focus:CursorPos(Th)
	end
	if (self.CursorOverride) then
		CursorX, CursorY, CursorColor = self:CursorOverride(Th)
	end
	T.setVisible(true)
	if (CursorX) then
		T.setCursorPos(CursorX, CursorY)
		T.setTextColor(CursorColor or Th.Text)
		T.setCursorBlink(true)
	end
	self.Dirty = false
end

function Ui.Page:WidgetAt(X, Y)
	for Index = #self.Widgets, 1, -1 do
		local Item = self.Widgets[Index]
		if (Item.Visible and Item.Event and Inside(Item, X, Y)) then
			return Item
		end
	end
	return nil
end

-- Routes an input event to widgets. Returns true when a widget consumed it.
function Ui.Page:Dispatch(Name, A, B, C)
	if (MouseEvents[Name]) then
		local X, Y = B - self.X + 1, C - self.Y + 1
		if (Name == "mouse_click") then
			local Item = self:WidgetAt(X, Y)
			self.Captured = Item
			if (Item and Item.Focusable) then
				self:SetFocus(Item)
			elseif (not Item or not Item.KeepFocus) then
				self:SetFocus(nil)
			end
			if (Item) then
				return Item:Event(self, Name, A, X, Y) ~= false
			end
			return false
		elseif (Name == "mouse_scroll") then
			local Item = self:WidgetAt(X, Y)
			if (Item) then
				return Item:Event(self, Name, A, X, Y) == true
			end
			return false
		end
		local Item = self.Captured
		if (Name == "mouse_up") then
			self.Captured = nil
		end
		if (Item) then
			return Item:Event(self, Name, A, X, Y) == true
		end
		return false
	end
	if (self.Focus and self.Focus.Visible and self.Focus.Event) then
		if (self.Focus:Event(self, Name, A, B, C)) then
			return true
		end
	end
	if (Name == "key" and A == keys.tab) then
		self:FocusNext()
		return true
	end
	return false
end

function Ui.Page:FocusNext()
	local Focusable = {}
	local Current = 0
	for _, Item in ipairs(self.Widgets) do
		if (Item.Visible and Item.Focusable) then
			table.insert(Focusable, Item)
			if (Item == self.Focus) then
				Current = #Focusable
			end
		end
	end
	if (#Focusable == 0) then return end
	self:SetFocus(Focusable[Current % #Focusable + 1])
end

function Ui.Page:SetInterval(Seconds, Callback)
	local Interval = { Seconds = Seconds, Callback = Callback }
	Interval.Timer = os.startTimer(Seconds)
	self.Intervals[Interval.Timer] = Interval
	return Interval
end

function Ui.Page:ClearInterval(Interval)
	if (not Interval) then return end
	self.Intervals[Interval.Timer] = nil
	os.cancelTimer(Interval.Timer)
end

-- Handles events that are not routed to widgets (timers, settings, custom events).
function Ui.Page:Background(Name, ...)
	if (Name == "timer") then
		local Id = ...
		local Interval = self.Intervals[Id]
		if (Interval) then
			self.Intervals[Id] = nil
			Interval.Timer = os.startTimer(Interval.Seconds)
			self.Intervals[Interval.Timer] = Interval
			if (Interval.Callback() ~= false) then
				self.Dirty = true
			end
			return
		end
	elseif (Name == "blockos_settings") then
		self.Dirty = true
	elseif (Name == "term_resize") then
		self:Resize()
	end
	if (self.OnEvent and self:OnEvent(Name, ...)) then
		self.Dirty = true
	end
end

function Ui.Page:Handle(Name, ...)
	TrackModifiers(Name, ...)
	if (Name == "terminate") then
		if (self.OnTerminate) then
			self:OnTerminate()
		else
			self.Running = false
		end
		return
	end
	if (InputEvents[Name]) then
		if (self:Dispatch(Name, ...)) then
			self.Dirty = true
		elseif (self.OnEvent and self:OnEvent(Name, ...)) then
			self.Dirty = true
		end
		return
	end
	self:Background(Name, ...)
end

function Ui.Page:Run()
	self.Running = true
	local Previous = Ui.Current
	Ui.Current = self
	self:Resize()
	self:Draw()
	while (self.Running) do
		local Event = table.pack(os.pullEventRaw())
		self:Handle(table.unpack(Event, 1, Event.n))
		if (self.Running and self.Dirty) then
			self:Draw()
		end
	end
	Ui.Current = Previous
end

function Ui.Page:Stop()
	self.Running = false
end

--
-- Widgets
--

Ui.Panel = Class({ X = 1, Y = 1, W = 1, H = 1, Bg = "Panel" })

function Ui.Panel:Draw(T, Th)
	Gfx.Fill(T, self.X, self.Y, self.W, self.H, Resolve(self.Bg, Th, Th.Panel))
end

Ui.Label = Class({ X = 1, Y = 1, H = 1, Text = "", Align = "left" })

function Ui.Label:Draw(T, Th, Page)
	local Text = TextOf(self.Text)
	local W = self.W or #Text
	local Bg = Resolve(self.Bg, Th, Page:GetBg(Th))
	local Fg = Resolve(self.Fg, Th, Th.Text)
	if (self.H > 1) then
		local Lines = Gfx.Wrap(Text, W)
		for Row = 1, self.H do
			Gfx.Write(T, self.X, self.Y + Row - 1, Gfx.Pad(Lines[Row] or "", W, self.Align), Fg, Bg)
		end
		return
	end
	Gfx.Write(T, self.X, self.Y, Gfx.Pad(Text, W, self.Align), Fg, Bg)
end

Ui.Button = Class({ X = 1, Y = 1, H = 1, Text = "Button", Style = "default", Enabled = true })

function Ui.Button:Init()
	self.W = self.W or #TextOf(self.Text) + 2
end

function Ui.Button:Colors(Th, Page)
	if (not self.Enabled) then
		return Th.ButtonBg, Th.SubText
	end
	if (self.Style == "primary") then
		return Resolve(self.Bg, Th, Th.Accent), Resolve(self.Fg, Th, Th.AccentFg)
	elseif (self.Style == "danger") then
		return colors.red, colors.white
	elseif (self.Style == "plain") then
		return Resolve(self.Bg, Th, Page:GetBg(Th)), Resolve(self.Fg, Th, Th.Accent)
	end
	return Resolve(self.Bg, Th, Th.ButtonBg), Resolve(self.Fg, Th, Th.ButtonFg)
end

function Ui.Button:Draw(T, Th, Page)
	local Bg, Fg = self:Colors(Th, Page)
	Gfx.Fill(T, self.X, self.Y, self.W, self.H, Bg)
	Gfx.Write(T, self.X, self.Y + math.floor((self.H - 1) / 2), Gfx.Pad(TextOf(self.Text), self.W, "center"), Fg, Bg)
end

function Ui.Button:Event(Page, Name, Button)
	if (Name == "mouse_click" and self.Enabled and self.OnClick) then
		self:OnClick(Button)
		return true
	end
	return Name == "mouse_click"
end

Ui.Input = Class({ X = 1, Y = 1, W = 10, H = 1, Value = "", Placeholder = "", Cursor = 1, Scroll = 0, Focusable = true })

function Ui.Input:Init()
	self.Value = tostring(self.Value)
	self.Cursor = #self.Value + 1
end

function Ui.Input:SetValue(Value)
	self.Value = tostring(Value or "")
	self.Cursor = #self.Value + 1
	self.Scroll = 0
	self.AllSelected = false
end

-- Highlights the whole value so the next typed text replaces it.
function Ui.Input:SelectAll()
	self.AllSelected = #self.Value > 0
end

function Ui.Input:ReplaceSelection()
	if (not self.AllSelected) then return end
	self.AllSelected = false
	self.Value = ""
	self.Cursor = 1
	self.Scroll = 0
end

function Ui.Input:Clamp()
	if (self.Cursor < 1) then self.Cursor = 1 end
	if (self.Cursor > #self.Value + 1) then self.Cursor = #self.Value + 1 end
	if (self.Cursor - 1 - self.Scroll >= self.W) then
		self.Scroll = self.Cursor - self.W
	end
	if (self.Cursor - 1 < self.Scroll) then
		self.Scroll = self.Cursor - 1
	end
end

function Ui.Input:Draw(T, Th, Page)
	self:Clamp()
	local Bg = Resolve(self.Bg, Th, Th.InputBg)
	local Fg = Resolve(self.Fg, Th, Th.InputFg)
	local Display = self.Value
	if (self.Mask) then
		Display = string.rep(self.Mask, #self.Value)
	end
	if (#Display == 0 and Page.Focus ~= self) then
		Gfx.Write(T, self.X, self.Y, Gfx.Pad(self.Placeholder, self.W), Th.SubText, Bg)
		return
	end
	local Visible = Display:sub(self.Scroll + 1, self.Scroll + self.W)
	Gfx.Write(T, self.X, self.Y, Gfx.Pad(Visible, self.W), Fg, Bg)
	if (self.AllSelected and Page.Focus == self) then
		Gfx.Write(T, self.X, self.Y, Visible, Th.AccentFg, Th.Accent)
	end
end

function Ui.Input:CursorPos(Th)
	self:Clamp()
	return self.X + self.Cursor - 1 - self.Scroll, self.Y, Resolve(self.Fg, Th, Th.InputFg)
end

function Ui.Input:Insert(Text)
	if (self.MaxLength and #self.Value + #Text > self.MaxLength) then
		Text = Text:sub(1, math.max(self.MaxLength - #self.Value, 0))
	end
	if (#Text == 0) then return end
	self.Value = self.Value:sub(1, self.Cursor - 1) .. Text .. self.Value:sub(self.Cursor)
	self.Cursor = self.Cursor + #Text
	if (self.OnChange) then self:OnChange(self.Value) end
end

function Ui.Input:Event(Page, Name, A, X)
	if (Name == "mouse_click") then
		self.AllSelected = false
		self.Cursor = X - self.X + self.Scroll + 1
		self:Clamp()
		return true
	elseif (Name == "char") then
		self:ReplaceSelection()
		self:Insert(A)
		return true
	elseif (Name == "paste") then
		self:ReplaceSelection()
		self:Insert((A:gsub("[\r\n]", "")))
		return true
	elseif (Name == "key") then
		if (self.AllSelected and (A == keys.backspace or A == keys.delete)) then
			self:ReplaceSelection()
			if (self.OnChange) then self:OnChange(self.Value) end
			return true
		elseif (A ~= keys.enter and A ~= keys.numPadEnter and A ~= keys.tab) then
			self.AllSelected = false
		end
		if (A == keys.backspace) then
			if (self.Cursor > 1) then
				self.Value = self.Value:sub(1, self.Cursor - 2) .. self.Value:sub(self.Cursor)
				self.Cursor = self.Cursor - 1
				if (self.OnChange) then self:OnChange(self.Value) end
			end
		elseif (A == keys.delete) then
			self.Value = self.Value:sub(1, self.Cursor - 1) .. self.Value:sub(self.Cursor + 1)
			if (self.OnChange) then self:OnChange(self.Value) end
		elseif (A == keys.left) then
			self.Cursor = self.Cursor - 1
		elseif (A == keys.right) then
			self.Cursor = self.Cursor + 1
		elseif (A == keys.home) then
			self.Cursor = 1
		elseif (A == keys["end"]) then
			self.Cursor = #self.Value + 1
		elseif (A == keys.enter or A == keys.numPadEnter) then
			if (self.OnSubmit) then self:OnSubmit(self.Value) end
		else
			return false
		end
		self:Clamp()
		return true
	end
	return false
end

Ui.List = Class({ X = 1, Y = 1, W = 10, H = 5, Selected = 0, Scroll = 0, Focusable = true })

function Ui.List:Init()
	self.Items = self.Items or {}
end

function Ui.List:SetItems(Items, KeepSelection)
	self.Items = Items
	if (not KeepSelection) then
		self.Selected = 0
		self.Scroll = 0
	end
	if (self.Selected > #Items) then self.Selected = #Items end
	self:EnsureVisible()
end

function Ui.List:EnsureVisible()
	local MaxScroll = math.max(#self.Items - self.H, 0)
	if (self.Selected > 0) then
		if (self.Selected <= self.Scroll) then
			self.Scroll = self.Selected - 1
		elseif (self.Selected > self.Scroll + self.H) then
			self.Scroll = self.Selected - self.H
		end
	end
	self.Scroll = math.max(0, math.min(self.Scroll, MaxScroll))
end

function Ui.List:Draw(T, Th, Page)
	local Bg = Resolve(self.Bg, Th, Page:GetBg(Th))
	local Fg = Resolve(self.Fg, Th, Th.Text)
	local Overflow = #self.Items > self.H
	local TextW = Overflow and self.W - 1 or self.W
	for Row = 1, self.H do
		local Index = Row + self.Scroll
		local Item = self.Items[Index]
		local Y = self.Y + Row - 1
		local RowBg, RowFg, SubFg = Bg, Fg, Th.SubText
		if (Item and Index == self.Selected) then
			RowBg = Th.Accent
			RowFg = Th.AccentFg
			SubFg = Th.AccentFg
		end
		Gfx.Fill(T, self.X, Y, TextW, 1, RowBg)
		if (Item) then
			if (self.RenderItem) then
				self:RenderItem(T, Th, Item, self.X, Y, TextW, Index == self.Selected, RowBg, RowFg)
			else
				local X = self.X
				if (Item.Icon) then
					Gfx.Write(T, X, Y, Item.Icon, (Index == self.Selected) and RowFg or Resolve(Item.IconFg, Th, RowFg), RowBg)
					X = X + #Item.Icon + 1
				end
				local Right = Item.Right and tostring(Item.Right) or ""
				local Space = self.X + TextW - X - (#Right > 0 and #Right + 1 or 0)
				Gfx.Write(T, X, Y, Gfx.Truncate(Item.Text or "", Space), (Index == self.Selected) and RowFg or Resolve(Item.Fg, Th, RowFg), RowBg)
				if (#Right > 0) then
					Gfx.Write(T, self.X + TextW - #Right, Y, Right, SubFg, RowBg)
				end
			end
		end
	end
	if (Overflow) then
		local Track = self.H
		local Thumb = math.max(1, math.floor(Track * self.H / #self.Items))
		local MaxScroll = #self.Items - self.H
		local ThumbY = math.floor((Track - Thumb) * self.Scroll / MaxScroll + .5)
		Gfx.Fill(T, self.X + self.W - 1, self.Y, 1, Track, Th.Border)
		Gfx.Fill(T, self.X + self.W - 1, self.Y + ThumbY, 1, Thumb, Th.SubText)
	end
end

function Ui.List:Select(Index)
	if (Index < 1 or Index > #self.Items) then return end
	self.Selected = Index
	self:EnsureVisible()
	if (self.OnSelect) then self:OnSelect(Index, self.Items[Index]) end
end

function Ui.List:Event(Page, Name, A, X, Y)
	if (Name == "mouse_click") then
		local Index = Y - self.Y + 1 + self.Scroll
		local Item = self.Items[Index]
		if (not Item) then
			if (A == 2 and self.OnContext) then self:OnContext(nil, nil, X, Y) end
			return true
		end
		local Now = os.clock()
		local Double = (self.LastClick == Index and Now - (self.LastTime or 0) < .5)
		self.LastClick = Index
		self.LastTime = Now
		if (Index ~= self.Selected) then
			self:Select(Index)
		end
		if (A == 2) then
			if (self.OnContext) then self:OnContext(Index, Item, X, Y) end
		elseif (Double or self.SingleClick) then
			self.LastClick = nil
			if (self.OnActivate) then self:OnActivate(Index, Item) end
		end
		return true
	elseif (Name == "mouse_scroll") then
		self.Scroll = math.max(0, math.min(self.Scroll + A, math.max(#self.Items - self.H, 0)))
		return true
	elseif (Name == "key") then
		if (A == keys.up) then
			self:Select(math.max(1, self.Selected - 1))
		elseif (A == keys.down) then
			self:Select(math.min(#self.Items, self.Selected + 1))
		elseif (A == keys.pageUp) then
			self:Select(math.max(1, self.Selected - self.H))
		elseif (A == keys.pageDown) then
			self:Select(math.min(#self.Items, self.Selected + self.H))
		elseif (A == keys.home) then
			self:Select(1)
		elseif (A == keys["end"]) then
			self:Select(#self.Items)
		elseif ((A == keys.enter or A == keys.numPadEnter) and self.Items[self.Selected]) then
			if (self.OnActivate) then self:OnActivate(self.Selected, self.Items[self.Selected]) end
		else
			return false
		end
		return true
	end
	return false
end

Ui.Toggle = Class({ X = 1, Y = 1, W = 4, H = 1, Value = false })

function Ui.Toggle:Draw(T, Th)
	if (self.Value) then
		Gfx.Fill(T, self.X, self.Y, 3, 1, Th.Accent)
		Gfx.Fill(T, self.X + 3, self.Y, 1, 1, colors.white)
	else
		Gfx.Fill(T, self.X, self.Y, 1, 1, colors.white)
		Gfx.Fill(T, self.X + 1, self.Y, 3, 1, Th.Dark and colors.black or colors.gray)
	end
end

function Ui.Toggle:Event(Page, Name)
	if (Name == "mouse_click") then
		self.Value = not self.Value
		if (self.OnChange) then self:OnChange(self.Value) end
		return true
	end
	return false
end

Ui.Checkbox = Class({ X = 1, Y = 1, H = 1, Value = false, Text = "" })

function Ui.Checkbox:Init()
	self.W = self.W or #self.Text + 4
end

function Ui.Checkbox:Draw(T, Th, Page)
	local Bg = Resolve(self.Bg, Th, Page:GetBg(Th))
	Gfx.Write(T, self.X, self.Y, self.Value and "[x]" or "[ ]", self.Value and Th.Accent or Th.SubText, Bg)
	Gfx.Write(T, self.X + 4, self.Y, Gfx.Truncate(self.Text, self.W - 4), Resolve(self.Fg, Th, Th.Text), Bg)
end

Ui.Checkbox.Event = Ui.Toggle.Event

Ui.Tabs = Class({ X = 1, Y = 1, W = 20, H = 1, Selected = 1 })

function Ui.Tabs:Init()
	self.Items = self.Items or {}
end

function Ui.Tabs:Draw(T, Th)
	local Count = #self.Items
	if (Count == 0) then return end
	local X = self.X
	for Index, Text in ipairs(self.Items) do
		local Width = math.floor(self.W * Index / Count) - math.floor(self.W * (Index - 1) / Count)
		local Bg = (Index == self.Selected) and Th.Accent or Th.ButtonBg
		local Fg = (Index == self.Selected) and Th.AccentFg or Th.ButtonFg
		Gfx.Write(T, X, self.Y, Gfx.Pad(Text, Width, "center"), Fg, Bg)
		X = X + Width
	end
end

function Ui.Tabs:Event(Page, Name, A, X)
	if (Name ~= "mouse_click") then return false end
	local Count = #self.Items
	local Offset = X - self.X
	for Index = 1, Count do
		if (Offset < math.floor(self.W * Index / Count)) then
			if (Index ~= self.Selected) then
				self.Selected = Index
				if (self.OnChange) then self:OnChange(Index, self.Items[Index]) end
			end
			return true
		end
	end
	return true
end

Ui.Progress = Class({ X = 1, Y = 1, W = 10, H = 1, Value = 0 })

function Ui.Progress:Draw(T, Th)
	local Value = math.max(0, math.min(1, TextOf(self.Value) + 0))
	local Filled = math.floor(self.W * Value + .5)
	Gfx.Fill(T, self.X, self.Y, self.W, self.H, Th.Border)
	Gfx.Fill(T, self.X, self.Y, Filled, self.H, Resolve(self.Color, Th, Th.Accent))
end

Ui.Canvas = Class({ X = 1, Y = 1, W = 1, H = 1 })

function Ui.Canvas:Draw(T, Th, Page)
	if (self.OnDraw) then self:OnDraw(T, Th, Page) end
end

function Ui.Canvas:Event(Page, Name, A, B, C)
	if (self.OnEvent) then
		return self:OnEvent(Name, A, B, C)
	end
	return false
end

function Ui.Canvas:CursorPos(Th)
	if (self.OnCursor) then return self:OnCursor(Th) end
	return nil
end

--
-- Modal dialogs. These block the calling coroutine but keep the
-- current page's timers and background events flowing.
--

local function AnimationsEnabled()
	local Ok, Config = pcall(BlockOS.Require, "config")
	return not (Ok and Config.Settings().Animations == false)
end

-- Grows a menu downwards over a few frames, keeping any events that arrive meanwhile.
local function Unroll(Modal, Pending)
	local FullH = Modal.H
	local Frames = 3
	for Frame = 1, Frames do
		local H = math.max(1, math.ceil(FullH * (1 - (1 - Frame / (Frames + 1)) ^ 2)))
		Modal.Buffer.reposition(Modal.X, Modal.Y, Modal.W, H)
		Modal:Draw()
		local Timer = os.startTimer(.05)
		while (true) do
			local Event = table.pack(os.pullEventRaw())
			if (Event[1] == "timer" and Event[2] == Timer) then break end
			table.insert(Pending, Event)
		end
	end
	Modal.Buffer.reposition(Modal.X, Modal.Y, Modal.W, FullH)
end

local function RunModal(Modal)
	local Previous = Ui.Current
	Ui.Current = Modal
	Modal.Running = true
	if (Modal.OnLayout) then Modal:OnLayout(Modal.W, Modal.H) end
	local Pending = {}
	if (Modal.Unroll and Modal.H > 1 and AnimationsEnabled()) then
		Unroll(Modal, Pending)
	end
	Modal:Draw()
	while (Modal.Running) do
		local Event = table.remove(Pending, 1) or table.pack(os.pullEventRaw())
		local Name = Event[1]
		TrackModifiers(Name, Event[2])
		if (Name == "terminate") then
			Modal.Running = false
		elseif (InputEvents[Name]) then
			local Outside = MouseEvents[Name] and Name == "mouse_click" and not Inside(Modal, Event[3], Event[4])
			if (Outside) then
				if (Modal.OnOutside) then Modal:OnOutside() end
			elseif (not Modal:Dispatch(table.unpack(Event, 1, Event.n)) and Modal.OnEvent) then
				Modal:OnEvent(table.unpack(Event, 1, Event.n))
			end
		elseif (Previous) then
			Previous:Background(table.unpack(Event, 1, Event.n))
			if (Previous.Dirty) then
				Previous:Draw()
			end
		end
		if (Modal.Running) then
			Modal:Draw()
		end
	end
	Modal.Buffer.setVisible(false)
	Ui.Current = Previous
	if (Previous) then
		Previous:Draw()
	end
	return Modal.Result
end

local function CreateModal(W, H, Parent)
	Parent = Parent or (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW, ScreenH = Parent.getSize()
	W = math.min(W, ScreenW)
	H = math.min(H, ScreenH)
	local X = math.floor((ScreenW - W) / 2) + 1
	local Y = math.floor((ScreenH - H) / 2) + 1
	return Ui.Page.new({ Parent = Parent, X = X, Y = Y, W = W, H = H, Bg = "MenuBg" })
end

local function DrawModalTitle(Modal, Title)
	function Modal:OnDraw(T, Th)
		Gfx.Fill(T, 1, 1, self.W, 1, Th.TitleBg)
		Gfx.Center(T, 1, Title, Th.TitleFg, Th.TitleBg)
	end
end

-- Shows a message with buttons; returns the index of the pressed button.
function Ui.Alert(Title, Message, Buttons)
	Buttons = Buttons or { "OK" }
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW = Parent.getSize()
	local ButtonsW = 1
	for _, Text in ipairs(Buttons) do
		ButtonsW = ButtonsW + #Text + 3
	end
	local W = math.min(ScreenW - 2, math.max(26, #Title + 4, ButtonsW))
	local Lines = Gfx.Wrap(Message or "", W - 4)
	local Modal = CreateModal(W, #Lines + 5, Parent)
	DrawModalTitle(Modal, Title)
	for Index, Line in ipairs(Lines) do
		Modal:Add(Ui.Label.new({ X = 3, Y = Index + 2, W = W - 4, Text = Line, Fg = "MenuFg" }))
	end
	local X = Modal.W
	for Index = #Buttons, 1, -1 do
		local Text = Buttons[Index]
		X = X - #Text - 3
		Modal:Add(Ui.Button.new({
			X = X + 1, Y = Modal.H - 1, Text = Text,
			Style = (Index == #Buttons) and "primary" or "default",
			OnClick = function()
				Modal.Result = Index
				Modal.Running = false
			end
		}))
	end
	function Modal:OnEvent(Name, Key)
		if (Name == "key" and (Key == keys.enter or Key == keys.numPadEnter)) then
			self.Result = #Buttons
			self.Running = false
		end
	end
	return RunModal(Modal)
end

function Ui.Confirm(Title, Message, YesText, NoText)
	return Ui.Alert(Title, Message, { NoText or "Cancel", YesText or "OK" }) == 2
end

-- Asks for a line of text; returns nil when cancelled.
function Ui.Prompt(Title, Message, Default, Mask)
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW = Parent.getSize()
	local W = math.min(ScreenW - 2, 32)
	local Lines = Gfx.Wrap(Message or "", W - 4)
	local Modal = CreateModal(W, #Lines + 7, Parent)
	DrawModalTitle(Modal, Title)
	for Index, Line in ipairs(Lines) do
		Modal:Add(Ui.Label.new({ X = 3, Y = Index + 2, W = W - 4, Text = Line, Fg = "MenuFg" }))
	end
	local Field = Modal:Add(Ui.Input.new({ X = 3, Y = #Lines + 4, W = W - 4, Value = Default or "", Mask = Mask }))
	Field:SelectAll()
	Field.OnSubmit = function()
		Modal.Result = Field.Value
		Modal.Running = false
	end
	Modal:Add(Ui.Button.new({
		X = W - 14, Y = Modal.H - 1, W = 8, Text = "Cancel",
		OnClick = function()
			Modal.Result = nil
			Modal.Running = false
		end
	}))
	Modal:Add(Ui.Button.new({
		X = W - 5, Y = Modal.H - 1, W = 4, Text = "OK", Style = "primary",
		OnClick = function()
			Modal.Result = Field.Value
			Modal.Running = false
		end
	}))
	Modal:SetFocus(Field)
	return RunModal(Modal)
end

-- Picks one entry from a list; returns index and item or nil.
function Ui.Choose(Title, Items, Selected)
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW, ScreenH = Parent.getSize()
	local W = math.min(ScreenW - 2, 30)
	local H = math.min(ScreenH - 2, #Items + 5)
	local Modal = CreateModal(W, H, Parent)
	DrawModalTitle(Modal, Title)
	local Entries = {}
	for _, Item in ipairs(Items) do
		if (type(Item) == "table") then
			table.insert(Entries, Item)
		else
			table.insert(Entries, { Text = tostring(Item) })
		end
	end
	local Picker = Modal:Add(Ui.List.new({ X = 2, Y = 3, W = W - 2, H = H - 5, Items = Entries, Bg = "MenuBg" }))
	Picker.Selected = Selected or 1
	Picker:EnsureVisible()
	Picker.OnActivate = function(_, Index)
		Modal.Result = Index
		Modal.Running = false
	end
	Modal:Add(Ui.Button.new({
		X = W - 14, Y = H - 1, W = 8, Text = "Cancel",
		OnClick = function()
			Modal.Running = false
		end
	}))
	Modal:Add(Ui.Button.new({
		X = W - 5, Y = H - 1, W = 4, Text = "OK", Style = "primary",
		OnClick = function()
			if (Picker.Selected > 0) then Modal.Result = Picker.Selected end
			Modal.Running = false
		end
	}))
	Modal:SetFocus(Picker)
	local Index = RunModal(Modal)
	return Index, Index and Items[Index]
end

-- Character map of all 256 font characters. Type a key, click or use the arrows; returns the byte or nil.
function Ui.PickChar(Title, Selected)
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local Modal = CreateModal(34, 13, Parent)
	DrawModalTitle(Modal, Title or "Characters")
	local Current = Selected or 65
	local LastClick = 0
	local function Finish()
		Modal.Result = Current
		Modal.Running = false
	end
	Modal:Add(Ui.Canvas.new({
		X = 2, Y = 3, W = 32, H = 8,
		OnDraw = function(Self, T, Th)
			for Row = 0, 7 do
				local Chars = {}
				for Column = 0, 31 do
					Chars[Column + 1] = string.char(Row * 32 + Column)
				end
				Gfx.Write(T, Self.X, Self.Y + Row, table.concat(Chars), Th.InputFg, Th.InputBg)
			end
			Gfx.Write(T, Self.X + Current % 32, Self.Y + math.floor(Current / 32), string.char(Current), Th.AccentFg, Th.Accent)
		end,
		OnEvent = function(Self, Name, _, X, Y)
			if (Name ~= "mouse_click" and Name ~= "mouse_drag") then return false end
			local Code = (Y - Self.Y) * 32 + (X - Self.X)
			if (Name == "mouse_click" and Code == Current and os.clock() - LastClick < .5) then
				Finish()
			end
			Current = math.max(0, math.min(255, Code))
			LastClick = os.clock()
			return true
		end
	}))
	Modal:Add(Ui.Label.new({
		X = 2, Y = 11, W = 32, Fg = "SubText",
		Text = function()
			return "Character " .. Current .. "  " .. string.char(Current)
		end
	}))
	Modal:Add(Ui.Button.new({
		X = 34 - 17, Y = 12, W = 8, Text = "Cancel",
		OnClick = function()
			Modal.Running = false
		end
	}))
	Modal:Add(Ui.Button.new({ X = 34 - 8, Y = 12, W = 8, Text = "Choose", Style = "primary", OnClick = Finish }))
	function Modal:OnEvent(Name, A)
		if (Name == "char") then
			Current = A:byte()
		elseif (Name == "key") then
			local Steps = { [keys.left] = -1, [keys.right] = 1, [keys.up] = -32, [keys.down] = 32 }
			if (Steps[A]) then
				Current = math.max(0, math.min(255, Current + Steps[A]))
			elseif (A == keys.enter or A == keys.numPadEnter) then
				Finish()
			end
		end
	end
	return RunModal(Modal)
end

-- Pops up a menu at X, Y (in parent coordinates). Items may be strings, "-" separators,
-- or { Text = ..., Disabled = true }. Returns the chosen index or nil.
function Ui.ContextMenu(X, Y, Items)
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW, ScreenH = Parent.getSize()
	local W = 4
	for _, Item in ipairs(Items) do
		local Text = type(Item) == "table" and Item.Text or Item
		W = math.max(W, #Text + 2)
	end
	local H = #Items
	X = math.max(1, math.min(X, ScreenW - W + 1))
	Y = math.max(1, math.min(Y, ScreenH - H + 1))
	local Modal = Ui.Page.new({ Parent = Parent, X = X, Y = Y, W = W, H = H, Bg = "MenuBg", Unroll = true })
	Modal.Hover = 0
	function Modal:OnDraw(T, Th)
		for Index, Item in ipairs(Items) do
			local Text = type(Item) == "table" and Item.Text or Item
			local Disabled = type(Item) == "table" and Item.Disabled
			if (Text == "-") then
				Gfx.Write(T, 1, Index, string.rep("\140", W), Th.MenuDim, Th.MenuBg)
			elseif (Index == self.Hover) then
				Gfx.Write(T, 1, Index, Gfx.Pad(" " .. Text, W), Th.AccentFg, Th.Accent)
			else
				Gfx.Write(T, 1, Index, Gfx.Pad(" " .. Text, W), Disabled and Th.MenuDim or Th.MenuFg, Th.MenuBg)
			end
		end
	end
	local function Selectable(Index)
		local Item = Items[Index]
		if (not Item) then return false end
		local Text = type(Item) == "table" and Item.Text or Item
		return Text ~= "-" and not (type(Item) == "table" and Item.Disabled)
	end
	function Modal:OnOutside()
		self.Running = false
	end
	function Modal:OnEvent(Name, A, MouseX, MouseY)
		if (Name == "mouse_click" or (Name == "mouse_up" and self.Dragged)) then
			local Index = MouseY - self.Y + 1
			if (Selectable(Index)) then
				self.Result = Index
				self.Running = false
			end
		elseif (Name == "mouse_drag") then
			local Index = MouseY - self.Y + 1
			self.Dragged = true
			if (Selectable(Index)) then self.Hover = Index end
		elseif (Name == "key") then
			if (A == keys.down or A == keys.up) then
				local Step = (A == keys.down) and 1 or -1
				for _ = 1, #Items do
					self.Hover = (self.Hover - 1 + Step) % #Items + 1
					if (Selectable(self.Hover)) then break end
				end
			elseif ((A == keys.enter or A == keys.numPadEnter) and Selectable(self.Hover)) then
				self.Result = self.Hover
				self.Running = false
			elseif (A == keys.backspace) then
				self.Running = false
			end
		end
	end
	return RunModal(Modal)
end

-- File chooser. Opts: Title, Dir, Save (ask for a file name), Extension, Folders (pick folder).
function Ui.PickFile(Opts)
	Opts = Opts or {}
	local Parent = (Ui.Current and Ui.Current.Parent) or term.current()
	local ScreenW, ScreenH = Parent.getSize()
	local W = math.min(ScreenW - 2, 40)
	local H = math.min(ScreenH - 2, 16)
	local Modal = CreateModal(W, H, Parent)
	local Dir = fs.combine(Opts.Dir or "home", "")
	if (not fs.isDir(Dir)) then Dir = "" end
	DrawModalTitle(Modal, Opts.Title or (Opts.Save and "Save As" or "Open"))
	local PathLabel = Modal:Add(Ui.Label.new({ X = 2, Y = 2, W = W - 2, Fg = "SubText" }))
	local Files = Modal:Add(Ui.List.new({ X = 2, Y = 3, W = W - 2, H = H - (Opts.Save and 6 or 5), Bg = "MenuBg" }))
	local NameField
	if (Opts.Save) then
		NameField = Modal:Add(Ui.Input.new({ X = 2, Y = H - 2, W = W - 2, Value = Opts.Name or "", Placeholder = "File name" }))
		NameField:SelectAll()
	end
	local function Refresh()
		PathLabel.Text = "/" .. Dir
		local Items = {}
		if (Dir ~= "") then
			table.insert(Items, { Text = "..", Icon = "\24", IconFg = "SubText", Up = true })
		end
		local Names = fs.list(Dir)
		table.sort(Names, function(A, B) return A:lower() < B:lower() end)
		for _, Name in ipairs(Names) do
			local Path = fs.combine(Dir, Name)
			if (fs.isDir(Path)) then
				table.insert(Items, { Text = Name, Icon = "\16", IconFg = colors.lightBlue, Path = Path, Dir = true })
			end
		end
		if (not Opts.Folders) then
			for _, Name in ipairs(Names) do
				local Path = fs.combine(Dir, Name)
				if (not fs.isDir(Path) and (not Opts.Extension or Name:sub(-#Opts.Extension) == Opts.Extension)) then
					table.insert(Items, { Text = Name, Icon = "\7", IconFg = "SubText", Path = Path })
				end
			end
		end
		Files:SetItems(Items)
	end
	local function Finish()
		if (Opts.Save) then
			if (#NameField.Value == 0) then return end
			Modal.Result = "/" .. fs.combine(Dir, NameField.Value)
		elseif (Opts.Folders) then
			Modal.Result = "/" .. Dir
		else
			local Item = Files.Items[Files.Selected]
			if (not Item or Item.Dir or Item.Up) then return end
			Modal.Result = "/" .. Item.Path
		end
		Modal.Running = false
	end
	Files.OnActivate = function(_, _, Item)
		if (Item.Up) then
			Dir = fs.getDir(Dir)
			Refresh()
		elseif (Item.Dir) then
			Dir = Item.Path
			Refresh()
		else
			Finish()
		end
	end
	Files.OnSelect = function(_, _, Item)
		if (NameField and Item and not Item.Dir and not Item.Up) then
			NameField:SetValue(fs.getName(Item.Path))
		end
	end
	if (NameField) then
		NameField.OnSubmit = Finish
	end
	Modal:Add(Ui.Button.new({
		X = W - 18, Y = H - 1, W = 8, Text = "Cancel",
		OnClick = function()
			Modal.Running = false
		end
	}))
	Modal:Add(Ui.Button.new({
		X = W - 9, Y = H - 1, W = 8, Text = Opts.Save and "Save" or (Opts.Folders and "Choose" or "Open"), Style = "primary",
		OnClick = Finish
	}))
	Refresh()
	Modal:SetFocus(NameField or Files)
	return RunModal(Modal)
end

return Ui
]=]
Files["blockos/lib/updater.lua"] = [[
-- Checks the update channel for a newer manifest and installs it in place.

local Config = BlockOS.Require("config")

local Updater = {}

Updater.State = { Status = "idle" }

-- Which release this computer follows. The desktop uses the defaults; BlockOS Server Edition
-- swaps in its own channel and manifest, and a manifest for a different edition is refused.
Updater.Profile = { Edition = nil, Manifest = "manifest.cfg", Url = nil }

local Protected = { ["blockos/data"] = true, ["blockos/userapps"] = true }

function Updater.Base()
	local Profile = Updater.Profile
	local Base = (Profile.Url and Profile.Url()) or Config.Settings().UpdateURL or Config.Repo
	if (Base:sub(-1) ~= "/") then Base = Base .. "/" end
	return Base
end

local function ParseVersion(Version)
	local Parts = {}
	for Number in tostring(Version):gmatch("%d+") do
		table.insert(Parts, tonumber(Number))
	end
	return Parts
end

function Updater.Compare(A, B)
	local Left, Right = ParseVersion(A), ParseVersion(B)
	for Index = 1, math.max(#Left, #Right) do
		local L, R = Left[Index] or 0, Right[Index] or 0
		if (L ~= R) then
			return L < R and -1 or 1
		end
	end
	return 0
end

local function Get(Url)
	if (not http) then return nil, "HTTP is disabled" end
	local Separator = Url:find("?", 1, true) and "&" or "?"
	local Response, Err = http.get(Url .. Separator .. "t=" .. tostring(os.epoch and os.epoch("utc") or os.clock()), nil, true)
	if (not Response) then return nil, Err or "Request failed" end
	local Body = Response.readAll()
	Response.close()
	return Body
end

Updater.Get = Get

function Updater.Check()
	Updater.State.Status = "checking"
	local Body, Err = Get(Updater.Base() .. (Updater.Profile.Manifest or "manifest.cfg"))
	if (not Body) then
		Updater.State.Status = "error"
		Updater.State.Error = Err
		return nil, Err
	end
	local Manifest = textutils.unserialise(Body)
	if (type(Manifest) ~= "table" or type(Manifest.Files) ~= "table") then
		Updater.State.Status = "error"
		Updater.State.Error = "Invalid manifest"
		return nil, "Invalid manifest"
	end
	if ((Manifest.Edition or "desktop") ~= (Updater.Profile.Edition or "desktop")) then
		Updater.State.Status = "error"
		Updater.State.Error = "The update channel is for BlockOS " .. tostring(Manifest.Edition or "desktop") .. ", not this edition"
		return nil, Updater.State.Error
	end
	Manifest.Newer = Updater.Compare(Config.Version(), Manifest.Version) < 0
	Updater.State.Latest = Manifest
	Updater.State.Status = Manifest.Newer and "available" or "uptodate"
	Updater.State.Checked = os.epoch and os.epoch("utc") or 0
	return Manifest
end

-- Downloads every file in the manifest to a staging folder, then swaps them in.
function Updater.Apply(Manifest, OnProgress)
	local Staging = "/blockos/.update"
	if (fs.exists(Staging)) then fs.delete(Staging) end
	Updater.State.Status = "downloading"
	local Base = Updater.Base()
	for Index, Path in ipairs(Manifest.Files) do
		local Top = Path:match("^(blockos/[^/]+)")
		if (not Protected[Top or ""]) then
			if (OnProgress) then OnProgress(Index - 1, #Manifest.Files, Path) end
			local Body, Err = Get(Base .. Path)
			if (not Body) then
				Updater.State.Status = "error"
				Updater.State.Error = Path .. ": " .. tostring(Err)
				fs.delete(Staging)
				return false, Updater.State.Error
			end
			Config.WriteText(fs.combine(Staging, Path), Body)
		end
	end
	for _, Path in ipairs(Manifest.Files) do
		local Source = fs.combine(Staging, Path)
		if (fs.exists(Source)) then
			if (fs.exists(Path)) then fs.delete(Path) end
			local Dir = fs.getDir(Path)
			if (Dir ~= "" and not fs.exists(Dir)) then fs.makeDir(Dir) end
			fs.move(Source, Path)
		end
	end
	fs.delete(Staging)
	Config.WriteText("/blockos/version.txt", Manifest.Version)
	if (OnProgress) then OnProgress(#Manifest.Files, #Manifest.Files, "") end
	Updater.State.Status = "ready"
	return true
end

return Updater
]]
Files["blockos/server/bin/bcloud.lua"] = [=[
-- bcloud: BlockOS Server administration from the shell (setup, recovery, scripting).
-- Talks to the running services directly, so it works in the console's Shell and in the
-- recovery shell alike.

local Server = BlockOS.Require("server/config")
local Manager = BlockOS.Require("server/service_manager")
local Clients = BlockOS.Require("server/clients")
local Log = BlockOS.Require("server/log")
local Rpc = BlockOS.Require("server/rpc")
local Path = BlockOS.Require("cloud/path")
local Volumes = BlockOS.Require("server/volumes")

local Args = { ... }
local Command = Args[1]

local function Usage()
	print("Usage: bcloud <command>")
	print("  status                    services, storage, clients")
	print("  pending                   computers waiting to pair")
	print("  approve <n> <code> [read] approve request n")
	print("  deny <n>                  decline request n")
	print("  clients                   paired computers")
	print("  perm <n> read|write       change a client's access")
	print("  remove <n>                unpair client n")
	print("  restart <service>         restart a service")
	print("  disks                     disk drives and how they are used")
	print("  disk <n> pool|share|off   pool disk n, give it its own")
	print("                            share, or leave it unused")
	print("  disk <n> name <name>      rename disk n")
	print("  logs [lines]              recent log lines")
	print("  update [install]          check for (and install) updates")
	print("  set <key> <value>         hostname, name, storage,")
	print("                            quota, public on|off,")
	print("                            visitors read|write, pairing, encrypt,")
	print("                            disks on|off, diskmode pool|share|off")
	print("  password                  set the admin password")
end

local function Core()
	local Service = Manager.Get("core")
	return Service and Service.Module
end

local function Pick(List, Text)
	local Index = tonumber(Text)
	local Item = Index and List[Index]
	if (not Item) then printError("No entry " .. tostring(Text) .. ". Run the list command first.") end
	return Item
end

if (not Manager.Get("core")) then
	printError("BlockCloud is not running on this computer.")
	return
end

if (Command == "status") then
	local Settings = Server.Settings()
	print(Settings.Hostname .. " (" .. Settings.DisplayName .. "), computer #" .. os.getComputerID() .. ", BlockOS Server " .. Server.Version())
	for _, Status in ipairs(Manager.Status()) do
		print(string.format("  %-16s %-10s %s", Status.Title, Status.State, Status.Detail or ""))
	end
	local Drive = Manager.Get("blockdrive")
	if (Drive and Drive.Module.Root) then
		local Usage = Drive.Module.Usage()
		print("Storage " .. Drive.Module.Root() .. ": " .. Usage.Files .. " files, " .. Usage.Bytes .. " bytes, " .. fs.getFreeSpace(Drive.Module.Root()) .. " bytes free")
	end
	local Visitors = 0
	for _ in pairs(Rpc.Visitors) do Visitors = Visitors + 1 end
	local Settings = Server.Settings()
	print((Settings.Public ~= false and ("Public: visitors may " .. (Settings.Visitors == "read" and "read" or "read and write")) or "Private: pairing required")
		.. "; " .. #Clients.List() .. " paired, " .. Visitors .. " visitors, " .. #Clients.PendingList() .. " pending, " .. Rpc.Stats.Requests .. " requests")
elseif (Command == "pending") then
	local List = Clients.PendingList()
	if (#List == 0) then print("No pairing requests.") end
	for Index, Request in ipairs(List) do
		print(Index .. ". " .. Request.Name .. " (computer #" .. Request.ComputerID .. ")")
	end
elseif (Command == "approve" and Args[2] and Args[3]) then
	local Request = Pick(Clients.PendingList(), Args[2])
	if (not Request) then return end
	local Client, Err = Core().Approve(Request.ID, Args[3], Args[4] == "read" and "read" or "write")
	if (Client) then print("Paired " .. Client.Name .. " (" .. Client.Permission .. ").") else printError(Err) end
elseif (Command == "deny" and Args[2]) then
	local Request = Pick(Clients.PendingList(), Args[2])
	if (Request) then
		Core().Deny(Request.ID)
		print("Declined.")
	end
elseif (Command == "clients") then
	local List = Clients.List()
	if (#List == 0) then print("No paired computers.") end
	for Index, Client in ipairs(List) do
		print(Index .. ". " .. Client.Name .. " (computer #" .. Client.ComputerID .. ", " .. Client.Permission .. ")")
	end
elseif (Command == "perm" and Args[2] and (Args[3] == "read" or Args[3] == "write")) then
	local Client = Pick(Clients.List(), Args[2])
	if (Client) then
		Clients.SetPermission(Client.ID, Args[3])
		print(Client.Name .. " is now " .. Args[3] .. ".")
	end
elseif (Command == "remove" and Args[2]) then
	local Client = Pick(Clients.List(), Args[2])
	if (Client) then
		Clients.Revoke(Client.ID)
		print("Unpaired " .. Client.Name .. ".")
	end
elseif (Command == "restart" and Args[2]) then
	if (not Manager.Get(Args[2])) then
		printError("No service " .. Args[2])
		return
	end
	Manager.Restart(Args[2])
	print("Restarted " .. Args[2] .. ".")
elseif (Command == "disks") then
	Volumes.Refresh()
	local List = Volumes.List()
	local Drive = Manager.Get("blockdrive")
	if (Drive and Drive.Module.PoolSpace) then
		local Free, Capacity, Pooled = Drive.Module.PoolSpace()
		print("Pool: " .. Volumes.Primary() .. " + " .. Pooled .. " disks, " .. Free .. " of " .. tostring(Capacity) .. " bytes free")
	end
	if (#List == 0) then print("No disk drives with a disk.") end
	for Index, Volume in ipairs(List) do
		local Free = Volume.Mode ~= "off" and fs.exists(Volume.Root) and fs.getFreeSpace(Volume.Root) or nil
		print(Index .. ". " .. Volume.Name .. "  " .. Volume.Mode .. "  " .. Volume.Side .. " " .. Volume.Mount .. (Free and ("  " .. Free .. " free") or ""))
	end
	if (Server.Settings().ShareDisks == false) then print("Disks are not used: bcloud set disks on") end
elseif (Command == "disk" and Args[2] and Args[3]) then
	Volumes.Refresh()
	local Volume = Pick(Volumes.List(), Args[2])
	if (not Volume) then return end
	if (Args[3] == "name" and Args[4]) then
		local Name = table.concat(Args, " ", 4)
		local Ok, Err = Volumes.Rename(Volume.Key, Name)
		if (Ok) then print("Disk " .. Volume.Name .. " is now called " .. Name .. ".") else printError(Err) end
	elseif (Volumes.Modes[Args[3]]) then
		local Warning = Volumes.ModeWarning(Volume, Args[3])
		if (Warning) then print(Warning) end
		Volumes.SetMode(Volume.Key, Args[3])
		print("Disk " .. Volume.Name .. ": " .. ({ pool = "pooled", share = "shared on its own", off = "not used" })[Args[3]] .. ".")
	else
		Usage()
	end
elseif (Command == "logs") then
	local Count = tonumber(Args[2]) or 15
	for Index = math.max(1, #Log.Lines - Count + 1), #Log.Lines do
		local Entry = Log.Lines[Index]
		print(Entry.Time:sub(12) .. " " .. Entry.Level .. " " .. Entry.Source .. ": " .. Entry.Text)
	end
elseif (Command == "update") then
	local Updates = Manager.Get("updater").Module
	print("Checking " .. Server.Settings().UpdateURL)
	Updates.Check(Args[2] == "install")
	print(Updates.Message)
elseif (Command == "set" and Args[2] and Args[3]) then
	local Settings = Server.Settings()
	local Value = table.concat(Args, " ", 3)
	local Key = Args[2]
	if (Key == "hostname") then
		if (not Server.ValidHostname(Value)) then return printError("Use 1-24 letters, digits, - or _.") end
		Settings.Hostname = Value
		os.setComputerLabel(Value)
	elseif (Key == "name") then
		Settings.DisplayName = Value:sub(1, 32)
	elseif (Key == "storage") then
		local Ok, Err = Path.ValidRoot(Value)
		if (not Ok) then return printError(Err) end
		Settings.StorageRoot = "/" .. fs.combine(Value, "")
	elseif (Key == "quota") then
		Settings.QuotaMB = tonumber(Value) or 0
	elseif (Key == "public") then
		Settings.Public = Value == "on" or Value == "true" or Value == "yes"
	elseif (Key == "visitors") then
		if (Value ~= "read" and Value ~= "write") then return printError("Use read or write.") end
		Settings.Visitors = Value
	elseif (Key == "diskmode") then
		if (not Volumes.Modes[Value]) then return printError("Use pool, share or off.") end
		Settings.DiskMode = Value
	elseif (Key == "pairing" or Key == "encrypt" or Key == "disks") then
		Settings[({ pairing = "PairingOpen", encrypt = "Encrypt", disks = "ShareDisks" })[Key]] = Value == "on" or Value == "true" or Value == "yes"
	else
		return printError("Unknown setting " .. Key)
	end
	Server.Save()
	if (Key == "storage") then Manager.Restart("blockdrive") end
	if (Key == "disks") then Volumes.Refresh() os.queueEvent("blockcloud_storage") end
	if (Key == "hostname" or Key == "encrypt" or Key == "public" or Key == "visitors") then Core().Announce() end
	print("Saved.")
elseif (Command == "password") then
	write("New admin password (empty for none): ")
	local First = read("*")
	if (First ~= "") then
		write("Again: ")
		if (read("*") ~= First) then return printError("The passwords did not match.") end
	end
	Server.SetPassword(First)
	print(First == "" and "Password removed." or "Password set.")
else
	Usage()
end
]=]
Files["blockos/server/boot.lua"] = [[
-- BlockOS Server Edition boot: installs the BlockOS API, runs first-time setup, starts the
-- BlockCloud services and then the admin console. Services start without anyone logging in.
-- Press S on the boot screen for a recovery shell (services keep running there too).

local Shell = shell
local Loaded = {}
local Fresh = { ui = true }

_G.BlockOS = { Root = "/blockos", Edition = "server" }

function BlockOS.Load(Path, ...)
	local Fn, Err = loadfile(Path, nil, _G)
	if (not Fn) then error(Err, 2) end
	return Fn(...)
end

-- "server/<name>" loads from /blockos/server, anything else from /blockos/lib.
function BlockOS.Require(Name)
	if (Loaded[Name]) then return Loaded[Name] end
	local Path = (Name:sub(1, 7) == "server/") and ("/blockos/" .. Name .. ".lua") or ("/blockos/lib/" .. Name .. ".lua")
	local Module = BlockOS.Load(Path)
	if (not Fresh[Name]) then Loaded[Name] = Module end
	return Module
end

local function Panic(Err)
	term.redirect(term.native())
	if (term.nativePaletteColor) then
		for Index = 0, 15 do
			term.setPaletteColor(2 ^ Index, term.nativePaletteColor(2 ^ Index))
		end
	end
	term.setBackgroundColor(term.isColor() and colors.blue or colors.black)
	term.setTextColor(colors.white)
	term.clear()
	term.setCursorPos(2, 2)
	print(" :(  BlockOS Server ran into a problem.")
	print()
	print(" " .. tostring(Err))
	print()
	print(" [R] Restart now    [S] Recovery shell")
	print(" Details: /blockos/data/cloud/logs/server.log")
	local Handle = fs.open("/blockos/data/cloud/logs/server.log", "a")
	if (Handle) then
		Handle.writeLine("PANIC " .. tostring(Err))
		Handle.close()
	end
	-- Unattended servers restart themselves so storage comes back without anyone present.
	local Remaining = 30
	local Timer = os.startTimer(1)
	while (true) do
		local _, H = term.getSize()
		term.setCursorPos(2, H - 1)
		term.clearLine()
		write(" Restarting automatically in " .. Remaining .. "s")
		local Event, A = os.pullEventRaw()
		if (Event == "timer" and A == Timer) then
			Remaining = Remaining - 1
			if (Remaining <= 0) then os.reboot() end
			Timer = os.startTimer(1)
		elseif (Event == "key" and A == keys.r) then
			os.reboot()
		elseif (Event == "key" and A == keys.s) then
			term.setBackgroundColor(colors.black)
			term.clear()
			term.setCursorPos(1, 1)
			return
		end
	end
end

-- Logo, name and a line of progress while the services start.
local function BootScreen(Step)
	if (not term.isColor()) then
		print("BlockOS Server: " .. Step)
		return
	end
	local Logo = BlockOS.Require("logo")
	local W, H = term.getSize()
	local LogoW, LogoH = Logo.Size(Logo.Big)
	local Y = math.max(1, math.floor((H - LogoH - 4) / 2))
	term.setBackgroundColor(colors.black)
	term.clear()
	Logo.Draw(term.current(), math.floor((W - LogoW) / 2) + 1, Y, Logo.Big)
	local Gfx = BlockOS.Require("gfx")
	Gfx.Center(term.current(), Y + LogoH + 1, "BlockOS Server", colors.white, colors.black)
	Gfx.Center(term.current(), Y + LogoH + 3, Step, colors.gray, colors.black)
	Gfx.Center(term.current(), H, "Press S for a recovery shell", colors.gray, colors.black)
end

local function WantsRecovery()
	local Timer = os.startTimer(.6)
	while (true) do
		local Event, A = os.pullEventRaw()
		if (Event == "timer" and A == Timer) then return false end
		if ((Event == "key" and A == keys.s) or (Event == "char" and A == "s")) then return true end
	end
end

-- Services plus a plain CraftOS shell: used on basic computers and for recovery.
local function RunHeadless(Runtime, Reason)
	term.setBackgroundColor(colors.black)
	term.setTextColor(colors.white)
	term.clear()
	term.setCursorPos(1, 1)
	local Server = BlockOS.Require("server/config")
	local Settings = Server.Settings()
	print("BlockOS Server " .. Server.Version() .. " - " .. Reason)
	print(Settings.Hostname .. " (computer #" .. os.getComputerID() .. "), storage " .. Settings.StorageRoot)
	print("BlockCloud services are running. Type 'bcloud' for")
	print("server commands, 'reboot' to restart.")
	parallel.waitForAny(function()
		Runtime.Run()
	end, function()
		while (true) do
			Shell.run("/rom/programs/shell.lua")
			print("The shell exited; the services are still running. Press any key for a new shell.")
			os.pullEvent("key")
		end
	end)
end

local Ok, Err = pcall(function()
	local Config = BlockOS.Require("config")
	BlockOS.Version = Config.Version()
	math.randomseed(os.epoch("utc") + os.getComputerID())
	local Server = BlockOS.Require("server/config")
	Server.ConfigureUpdater()
	-- CraftOS boots a disk's startup file instead of this one when any attached disk has one.
	-- A server full of disks must not be taken over by a stray floppy, so turn that off.
	if (settings.get("shell.allow_disk_startup") ~= false) then
		settings.set("shell.allow_disk_startup", false)
		settings.save()
	end

	if (not Server.Settings().Configured) then
		local Setup = BlockOS.Load("/blockos/server/setup.lua")
		if (term.isColor()) then
			Setup.Run({ Mode = "firstboot" })
		else
			Setup.RunText()
		end
	end

	for _, Dir in ipairs({ "/blockos/bin", "/blockos/server/bin" }) do
		if (not Shell.path():find(Dir, 1, true)) then
			Shell.setPath(Shell.path() .. ":" .. Dir)
		end
	end

	BootScreen("Starting services...")
	-- Asked before the services start, so no network message is missed while waiting.
	local Recovery = term.isColor() and WantsRecovery()
	local Runtime = BlockOS.Require("server/init")
	Runtime.Start()
	if (not term.isColor() or Recovery) then
		RunHeadless(Runtime, Recovery and "recovery shell" or "headless mode")
		return
	end
	local Host = BlockOS.Load("/blockos/server/ui/host.lua")
	Host.Start(Shell)
	Runtime.Run(Host)
end)

if (not Ok) then
	Panic(Err)
end
]]
Files["blockos/server/clients.lua"] = [[
-- Paired client computers and pending pairing requests.
-- Paired clients persist in /blockos/data/cloud/clients.dat; pending requests live in memory
-- and expire, so a restart simply asks the client to pair again.

local Config = BlockOS.Require("config")
local Auth = BlockOS.Require("cloud/auth")
local Log = BlockOS.Require("server/log")

local Clients = {}

Clients.Path = "/blockos/data/cloud/clients.dat"
Clients.PendingLimit = 16
Clients.PendingLifetime = 10 * 60 * 1000

local Data = nil
local Dirty = false
local LastSave = 0
Clients.Pending = {}

local function Load()
	if (not Data) then
		local Saved = Config.Read(Clients.Path)
		Data = type(Saved) == "table" and Saved or {}
	end
	return Data
end

function Clients.Save()
	Config.Write(Clients.Path, Load())
	Dirty = false
	LastSave = os.epoch("utc")
	os.queueEvent("blockcloud_clients")
end

-- Writes LastSeen updates at most once a minute to spare the disk.
function Clients.Flush(Force)
	if (Dirty and (Force or os.epoch("utc") - LastSave > 60000)) then
		Clients.Save()
	end
end

function Clients.Get(ClientID)
	if (type(ClientID) ~= "string") then return nil end
	return Load()[ClientID]
end

function Clients.List()
	local List = {}
	for _, Client in pairs(Load()) do
		table.insert(List, Client)
	end
	table.sort(List, function(A, B) return (A.Name or ""):lower() < (B.Name or ""):lower() end)
	return List
end

function Clients.Touch(Client)
	Client.LastSeen = os.epoch("utc")
	Dirty = true
end

function Clients.SetPermission(ClientID, Permission)
	local Client = Clients.Get(ClientID)
	if (not Client or (Permission ~= "read" and Permission ~= "write")) then return false end
	Client.Permission = Permission
	Clients.Save()
	Log.Info("auth", "Permission for " .. Client.Name .. " set to " .. Permission)
	return true
end

function Clients.Rename(ClientID, Name)
	local Client = Clients.Get(ClientID)
	if (not Client) then return false end
	Client.Name = tostring(Name):sub(1, 32)
	Clients.Save()
	return true
end

function Clients.Revoke(ClientID)
	local Client = Clients.Get(ClientID)
	if (not Client) then return false end
	Load()[ClientID] = nil
	Clients.Save()
	Log.Info("auth", "Removed client " .. Client.Name .. " (computer #" .. Client.ComputerID .. ")")
	return true
end

--
-- Pairing
--

function Clients.Expire()
	local Now = os.epoch("utc")
	for ID, Request in pairs(Clients.Pending) do
		if (Now - Request.Created > Clients.PendingLifetime) then
			Clients.Pending[ID] = nil
		end
	end
end

-- Records a request from a client. One request per computer; a new one replaces the old.
function Clients.Request(ComputerID, Name, ClientNonce, Check)
	Clients.Expire()
	local Count = 0
	for ID, Request in pairs(Clients.Pending) do
		if (Request.ComputerID == ComputerID) then
			Clients.Pending[ID] = nil
		elseif (Request.Status == "pending") then
			Count = Count + 1
		end
	end
	if (Count >= Clients.PendingLimit) then return nil, "busy" end
	local Request = {
		ID = Auth.RandomHex(8),
		ComputerID = ComputerID,
		Name = tostring(Name or ("Computer #" .. ComputerID)):sub(1, 32),
		ClientNonce = ClientNonce,
		ServerNonce = Auth.RandomHex(16),
		Check = Check,
		Created = os.epoch("utc"),
		Status = "pending"
	}
	Clients.Pending[Request.ID] = Request
	Log.Info("auth", "Pairing request from " .. Request.Name .. " (computer #" .. ComputerID .. ")")
	os.queueEvent("blockcloud_clients")
	return Request
end

function Clients.PendingList()
	Clients.Expire()
	local List = {}
	for _, Request in pairs(Clients.Pending) do
		if (Request.Status == "pending") then table.insert(List, Request) end
	end
	table.sort(List, function(A, B) return A.Created < B.Created end)
	return List
end

-- Approves a request with the code shown on the client. Returns the new client or nil, reason.
function Clients.Approve(RequestID, CodeText, Permission, Name)
	local Request = Clients.Pending[RequestID]
	if (not Request or Request.Status ~= "pending") then return nil, "That request is no longer waiting." end
	local Code = Auth.CleanCode(CodeText)
	if (Auth.CodeCheck(Code, Request.ClientNonce) ~= Request.Check) then
		Log.Warn("auth", "Wrong pairing code entered for " .. Request.Name)
		return nil, "That code does not match the one shown on the client."
	end
	Permission = (Permission == "read") and "read" or "write"
	local Key = Auth.DeriveKey(Code, Request.ID, Request.ClientNonce, Request.ServerNonce)
	local Client = {
		ID = Auth.RandomHex(12),
		ComputerID = Request.ComputerID,
		Name = tostring(Name or Request.Name):sub(1, 32),
		Key = BlockOS.Require("cloud/codec").ToHex(Key),
		Permission = Permission,
		PairedAt = os.epoch("utc"),
		LastSeen = os.epoch("utc")
	}
	Load()[Client.ID] = Client
	Clients.Save()
	Request.Status = "approved"
	Request.ClientID = Client.ID
	Request.Proof = Auth.ApprovalProof(Key, Request.ID, Client.ID, Permission)
	Request.Permission = Permission
	Log.Info("auth", "Paired " .. Client.Name .. " (computer #" .. Client.ComputerID .. ", " .. Permission .. ")")
	return Client
end

function Clients.Deny(RequestID)
	local Request = Clients.Pending[RequestID]
	if (not Request) then return false end
	Request.Status = "denied"
	Log.Info("auth", "Declined pairing request from " .. Request.Name)
	os.queueEvent("blockcloud_clients")
	return true
end

return Clients
]]
Files["blockos/server/config.lua"] = [[
-- Server Edition configuration, stored in /blockos/data/cloud/server.dat next to the
-- other BlockOS settings so updates never touch it.

local Config = BlockOS.Require("config")
local Auth = BlockOS.Require("cloud/auth")

local Server = {}

Server.DataDir = "/blockos/data/cloud"
Server.Channel = "https://raw.githubusercontent.com/tamayaren/BlockOS/server/"
Server.Manifest = "server-manifest.cfg"

Config.Defaults["cloud/server"] = {
	Configured = false,
	Hostname = "datacenter",
	DisplayName = "Data Center",
	StorageRoot = "/blockcloud/storage",
	DefaultShare = "Shared",
	-- Disk drives (direct or over wired modems): ShareDisks turns them all off, DiskMode is how
	-- new disks are used (pool, share or off), Disks holds per-disk { Name, Mode } by disk ID.
	ShareDisks = true,
	DiskMode = "pool",
	Disks = {},
	-- Public servers let any computer in range use BlockDrive without pairing, with Visitors
	-- ("read" or "write") access. Paired computers keep their own permission either way.
	Public = true,
	Visitors = "write",
	PairingOpen = true,
	Encrypt = true,
	QuotaMB = 0,
	MaxFileKB = 0,
	LockMinutes = 10,
	AutoUpdate = true,
	AutoInstall = true,
	AutoRestart = true,
	UpdateHours = 6,
	UpdateURL = Server.Channel,
	Services = { blockdrive = true },
	LogLevel = "info"
}

local Migrated = false

-- Servers set up before public access existed and that already have paired computers stay
-- private: updating must never open someone's storage to everyone.
local function Migrate()
	Migrated = true
	local Saved = Config.Read(fs.combine(Config.DataDir, "cloud/server.dat"))
	if (type(Saved) ~= "table" or Saved.Public ~= nil) then return end
	local Paired = Config.Read(fs.combine(Server.DataDir, "clients.dat"))
	if (type(Paired) == "table" and next(Paired) ~= nil) then
		local Settings = Config.Load("cloud/server")
		Settings.Public = false
		Config.Save("cloud/server")
	end
end

function Server.Settings()
	if (not Migrated) then Migrate() end
	local Settings = Config.Load("cloud/server")
	if (type(Settings.NodeID) ~= "string") then
		Settings.NodeID = Auth.RandomHex(8)
		Config.Save("cloud/server")
	end
	return Settings
end

function Server.Save()
	Config.Save("cloud/server")
	os.queueEvent("blockcloud_config")
end

function Server.Version()
	return Config.Version()
end

-- Hostnames are announced on the network; keep them short and simple.
function Server.ValidHostname(Name)
	return type(Name) == "string" and #Name >= 1 and #Name <= 24 and Name:match("^[%w%-_]+$") ~= nil
end

function Server.HasPassword()
	return type(Server.Settings().AdminHash) == "string"
end

function Server.SetPassword(Password)
	local Settings = Server.Settings()
	if (not Password or Password == "") then
		Settings.AdminSalt = nil
		Settings.AdminHash = nil
	else
		Settings.AdminSalt = Auth.RandomHex(8)
		Settings.AdminHash = Auth.HashPassword(Password, Settings.AdminSalt)
	end
	Server.Save()
end

function Server.CheckPassword(Password)
	local Settings = Server.Settings()
	if (not Settings.AdminHash) then return true end
	return Auth.HashPassword(Password or "", Settings.AdminSalt or "") == Settings.AdminHash
end

-- Points the shared updater at the Server Edition channel and manifest, never the desktop one.
function Server.ConfigureUpdater()
	local Updater = BlockOS.Require("updater")
	Updater.Profile = {
		Edition = "server",
		Manifest = Server.Manifest,
		Url = function() return Server.Settings().UpdateURL or Server.Channel end
	}
	return Updater
end

return Server
]]
Files["blockos/server/init.lua"] = [[
-- BlockCloud runtime: one event loop feeds every event to the request dispatcher, its worker
-- coroutines and the services, and then to the admin interface. Services never depend on the
-- interface: if it is closed or crashes, they keep running.

local Protocol = BlockOS.Require("cloud/protocol")
local Rpc = BlockOS.Require("server/rpc")
local Log = BlockOS.Require("server/log")
local Server = BlockOS.Require("server/config")
local Manager = BlockOS.Require("server/service_manager")

local Runtime = {}

Runtime.Started = nil

local function Guard(Label, Fn, ...)
	local Ok, Err = pcall(Fn, ...)
	if (not Ok) then Log.Error("runtime", Label .. ": " .. tostring(Err)) end
end

function Runtime.Start()
	local Settings = Server.Settings()
	Log.Level = Settings.LogLevel or "info"
	Log.Info("runtime", "BlockOS Server " .. Server.Version() .. " starting on computer #" .. os.getComputerID() .. " as " .. Settings.Hostname)
	Protocol.OpenModems()
	Manager.Load()
	Manager.StartAll()
	Runtime.Started = os.epoch("utc")
end

function Runtime.Dispatch(Event)
	local Name = Event[1]
	if (Name == "terminate") then return end
	if (Name == "rednet_message" and Protocol.ServiceOf(Event[4])) then
		Guard("request", Rpc.Handle, Event[2], Event[3], Event[4])
	end
	Guard("workers", Rpc.Dispatch, Event)
	Guard("services", Manager.Dispatch, Event)
end

-- Runs forever. Ui, when given, receives every event after the services.
function Runtime.Run(Ui)
	while (true) do
		local Event = table.pack(os.pullEventRaw())
		Runtime.Dispatch(Event)
		if (Ui) then
			local Ok, Err = pcall(Ui.Dispatch, Event)
			if (not Ok) then
				Log.Error("console", tostring(Err))
				if (Ui.Recover) then pcall(Ui.Recover, Err) end
			end
		end
	end
end

return Runtime
]]
Files["blockos/server/log.lua"] = [[
-- Server log: the last few hundred lines in memory for the console, and a rotating file on disk.

local Log = {}

Log.Path = "/blockos/data/cloud/logs/server.log"
Log.OldPath = "/blockos/data/cloud/logs/server.old.log"
Log.MaxFile = 32 * 1024
Log.Lines = {}
Log.Limit = 200
Log.Levels = { debug = 1, info = 2, warn = 3, error = 4 }
Log.Level = "info"
Log.Counter = 0

local function Stamp()
	local Ok, Text = pcall(os.date, "%Y-%m-%d %H:%M:%S")
	return Ok and Text or tostring(os.clock())
end

local function Append(Line)
	local Dir = fs.getDir(Log.Path)
	if (not fs.exists(Dir)) then fs.makeDir(Dir) end
	if (fs.exists(Log.Path) and fs.getSize(Log.Path) > Log.MaxFile) then
		if (fs.exists(Log.OldPath)) then fs.delete(Log.OldPath) end
		fs.move(Log.Path, Log.OldPath)
	end
	local Handle = fs.open(Log.Path, "a")
	if (Handle) then
		Handle.writeLine(Line)
		Handle.close()
	end
end

function Log.Write(Level, Source, Text)
	if ((Log.Levels[Level] or 2) < (Log.Levels[Log.Level] or 2)) then return end
	local Entry = { Time = Stamp(), Level = Level, Source = Source, Text = tostring(Text) }
	table.insert(Log.Lines, Entry)
	if (#Log.Lines > Log.Limit) then table.remove(Log.Lines, 1) end
	Log.Counter = Log.Counter + 1
	pcall(Append, Entry.Time .. " " .. Level:upper() .. " [" .. Source .. "] " .. Entry.Text)
	os.queueEvent("blockcloud_log")
end

function Log.Info(Source, Text) Log.Write("info", Source, Text) end
function Log.Warn(Source, Text) Log.Write("warn", Source, Text) end
function Log.Error(Source, Text) Log.Write("error", Source, Text) end
function Log.Debug(Source, Text) Log.Write("debug", Source, Text) end

return Log
]]
Files["blockos/server/rpc.lua"] = [[
-- BlockCloud request dispatcher. Services register operations here; incoming requests are
-- validated, authenticated, de-duplicated and run in their own worker coroutine so a slow
-- operation never stops the server from receiving other messages.

local Protocol = BlockOS.Require("cloud/protocol")
local Auth = BlockOS.Require("cloud/auth")
local Clients = BlockOS.Require("server/clients")
local Log = BlockOS.Require("server/log")

local Rpc = {}

Rpc.Services = {}
Rpc.Workers = {}
Rpc.MaxWorkers = 8
Rpc.Stats = { Requests = 0, Errors = 0, Rejected = 0, Started = os.epoch("utc") }

local Seen = {}
local Buckets = {}
-- Computers using a public server without pairing, by computer ID: last time seen.
Rpc.Visitors = {}

-- Access is "public" (no pairing needed), "read" or "write".
function Rpc.Register(Service, Ops)
	Rpc.Services[Service] = Rpc.Services[Service] or {}
	for Op, Def in pairs(Ops) do
		Rpc.Services[Service][Op] = Def
	end
end

function Rpc.Unregister(Service)
	Rpc.Services[Service] = nil
end

-- Handlers raise protocol errors with this; anything else is reported as an internal error.
function Rpc.Fail(Code, Detail)
	error({ BlockCloud = true, Code = Code, Message = Detail or Protocol.Errors[Code] }, 0)
end

-- Gives other coroutines a turn during long work (and avoids "too long without yielding").
function Rpc.Yield()
	os.queueEvent("blockcloud_yield")
	os.pullEvent("blockcloud_yield")
end

local function Reply(Sender, ProtocolName, Request, Body, Keys)
	local Response = Protocol.Seal({
		K = "res", ID = Request.ID, Svc = Request.Svc, Op = Request.Op, Cl = Request.Cl
	}, Body, Keys, Request.E)
	rednet.send(Sender, Response, ProtocolName)
	return Response
end

local function ErrorBody(Code, Detail)
	return { Ok = false, Code = Code, Msg = Detail or Protocol.Errors[Code] or Code }
end

-- Unpaired computers get a request budget, so spam stays cheap. Visitors on a public server
-- transfer files (one request per 8 KB), so their budget is larger.
local function Allowed(Sender, Limit)
	local Now = os.epoch("utc")
	local Bucket = Buckets[Sender]
	if (not Bucket or Now - Bucket.Since > 10000) then
		Bucket = { Since = Now, Count = 0 }
		Buckets[Sender] = Bucket
	end
	Bucket.Count = Bucket.Count + 1
	return Bucket.Count <= (Limit or 30)
end

-- An unpaired computer on a public server. It is only ever trusted with the visitor permission.
local function Visitor(Sender, Settings)
	Rpc.Visitors[Sender] = os.epoch("utc")
	return {
		ID = "visitor-" .. Sender, ComputerID = Sender, Name = "Computer #" .. Sender, Visitor = true,
		Permission = Settings.Visitors == "read" and "read" or "write"
	}
end

local function Resume(Worker, ...)
	local Ok, Result = coroutine.resume(Worker.Co, ...)
	if (not Ok) then
		Log.Error("rpc", Worker.Label .. ": " .. tostring(Result))
	elseif (coroutine.status(Worker.Co) ~= "dead") then
		Worker.Filter = Result
		return
	end
	for Index, Other in ipairs(Rpc.Workers) do
		if (Other == Worker) then
			table.remove(Rpc.Workers, Index)
			break
		end
	end
end

-- Handles a rednet message on a blockcloud/svc/* protocol.
function Rpc.Handle(Sender, Msg, ProtocolName)
	if (not Protocol.Valid(Msg) or Msg.K ~= "req" or Protocol.Name(Msg.Svc) ~= ProtocolName) then return end
	Rpc.Stats.Requests = Rpc.Stats.Requests + 1
	local Service = Rpc.Services[Msg.Svc]
	local Def = Service and Service[Msg.Op]
	local Client, Keys
	local Settings = BlockOS.Require("server/config").Settings()
	if (Def and Def.Access ~= "public" and Msg.Cl == nil and Settings.Public) then
		if (not Allowed(Sender, 400)) then
			Rpc.Stats.Rejected = Rpc.Stats.Rejected + 1
			return
		end
		Client = Visitor(Sender, Settings)
	elseif (Def and Def.Access ~= "public") then
		Client = Clients.Get(Msg.Cl)
		if (not Client or Client.ComputerID ~= Sender) then
			Rpc.Stats.Rejected = Rpc.Stats.Rejected + 1
			Reply(Sender, ProtocolName, Msg, ErrorBody("not_paired"))
			return
		end
		Keys = Auth.Keys(Client.Key)
	elseif (not Allowed(Sender)) then
		Rpc.Stats.Rejected = Rpc.Stats.Rejected + 1
		return
	end

	-- A retry of a request already answered gets the same answer; one still running is ignored.
	local SeenKey = (Msg.Cl or ("#" .. Sender)) .. ":" .. Msg.ID
	local Previous = Seen[SeenKey]
	if (Previous) then
		if (Previous.Response) then rednet.send(Sender, Previous.Response, ProtocolName) end
		return
	end

	local Args, Err = Protocol.Open(Msg, Keys)
	if (Err) then
		Rpc.Stats.Rejected = Rpc.Stats.Rejected + 1
		if (Client) then Log.Warn("auth", "Rejected a request claiming to be " .. Client.Name .. ": " .. Err) end
		Reply(Sender, ProtocolName, Msg, ErrorBody(Err))
		return
	end
	if (Keys and not Protocol.Fresh(Msg)) then
		Rpc.Stats.Rejected = Rpc.Stats.Rejected + 1
		Reply(Sender, ProtocolName, Msg, ErrorBody("replay"), Keys)
		return
	end
	if (not Service) then
		Reply(Sender, ProtocolName, Msg, ErrorBody("unknown_service"), Keys)
		return
	end
	if (not Def) then
		Reply(Sender, ProtocolName, Msg, ErrorBody("unknown_op"), Keys)
		return
	end
	if (Def.Access == "write" and Client.Permission ~= "write") then
		Reply(Sender, ProtocolName, Msg, ErrorBody("denied"), Keys)
		return
	end
	if (#Rpc.Workers >= Rpc.MaxWorkers) then
		Reply(Sender, ProtocolName, Msg, ErrorBody("busy"), Keys)
		return
	end
	if (Client and not Client.Visitor) then Clients.Touch(Client) end

	local Entry = { Time = os.epoch("utc") }
	Seen[SeenKey] = Entry
	local Ctx = { Sender = Sender, Client = Client, Service = Msg.Svc, Op = Msg.Op, ID = Msg.ID }
	local Worker = { Label = Msg.Svc .. "." .. Msg.Op }
	Worker.Co = coroutine.create(function()
		local Ok, Result = pcall(Def.Handler, Ctx, type(Args) == "table" and Args or {})
		local Body
		if (Ok) then
			Body = { Ok = true, R = Result }
		elseif (type(Result) == "table" and Result.BlockCloud) then
			Body = ErrorBody(Result.Code, Result.Message)
		else
			Rpc.Stats.Errors = Rpc.Stats.Errors + 1
			Log.Error(Msg.Svc, Msg.Op .. ": " .. tostring(Result))
			Body = ErrorBody("internal")
		end
		local SendOk, Response = pcall(Reply, Sender, ProtocolName, Msg, Body, Keys)
		if (SendOk) then
			Entry.Response = Response
		else
			Log.Error("rpc", "Could not send a reply: " .. tostring(Response))
			Entry.Response = Reply(Sender, ProtocolName, Msg, ErrorBody("internal"), Keys)
		end
	end)
	table.insert(Rpc.Workers, Worker)
	Resume(Worker)
end

-- Passes an event to the workers waiting for it.
function Rpc.Dispatch(Event)
	if (#Rpc.Workers == 0) then return end
	for _, Worker in ipairs({ table.unpack(Rpc.Workers) }) do
		if (Worker.Filter == nil or Worker.Filter == Event[1]) then
			Resume(Worker, table.unpack(Event, 1, Event.n))
		end
	end
end

-- Forgets answered requests once their timestamps could no longer pass the freshness check.
function Rpc.Cleanup()
	local Cutoff = os.epoch("utc") - Protocol.MaxSkew * 2
	for Key, Entry in pairs(Seen) do
		if (Entry.Time < Cutoff) then Seen[Key] = nil end
	end
	for Sender, Bucket in pairs(Buckets) do
		if (os.epoch("utc") - Bucket.Since > 60000) then Buckets[Sender] = nil end
	end
	for Sender, Seen in pairs(Rpc.Visitors) do
		if (os.epoch("utc") - Seen > 3600000) then Rpc.Visitors[Sender] = nil end
	end
end

return Rpc
]]
Files["blockos/server/service_manager.lua"] = [=[
-- Starts, supervises and restarts BlockCloud services. Each service is a module in
-- /blockos/server/services with:
--   Name, Title, Description, Version, System (always on)
--   Init(Ctx)    register RPC operations and prepare state (may error)
--   Run(Ctx)     optional background loop using os.pullEvent; restarted if it crashes
--   Health()     optional: returns "ok" | "warn" | "error", detail text
--   Info()       optional: extra fields announced during discovery
-- New services (storage nodes, job workers, ...) only need a file here and an entry in Order.

local Log = BlockOS.Require("server/log")
local Rpc = BlockOS.Require("server/rpc")
local Server = BlockOS.Require("server/config")

local Manager = {}

Manager.Dir = "/blockos/server/services"
Manager.Order = { "core", "blockdrive", "updater" }
Manager.Services = {}

local Timers = {}

local function Context(Service)
	return { Rpc = Rpc, Log = Log, Server = Server, Manager = Manager, Service = Service }
end

function Manager.Enabled(Name)
	local Service = Manager.Services[Name]
	if (Service and Service.Module.System) then return true end
	local Flags = Server.Settings().Services or {}
	return Flags[Name] ~= false
end

local function Schedule(Service)
	Service.Restarts = Service.Restarts + 1
	local Delay = math.min(60, 5 * 2 ^ math.min(Service.Restarts - 1, 4))
	Service.State = "restarting"
	Service.RetryAt = os.clock() + Delay
	Timers[os.startTimer(Delay)] = Service
end

local function Fail(Service, Stage, Err)
	Service.Co = nil
	Service.LastError = tostring(Err)
	Log.Error(Service.Name, Stage .. " failed: " .. Service.LastError)
	Schedule(Service)
	os.queueEvent("blockcloud_status")
end

local function Resume(Service, ...)
	local Ok, Result = coroutine.resume(Service.Co, ...)
	if (not Ok) then
		Fail(Service, "Service", Result)
	elseif (coroutine.status(Service.Co) == "dead") then
		Service.Co = nil
		Service.State = "running"
	else
		Service.Filter = Result
	end
end

local function Start(Service)
	if (not Manager.Enabled(Service.Name)) then
		Service.State = "disabled"
		return
	end
	if (not Service.Initialised) then
		local Ok, Err = pcall(Service.Module.Init, Context(Service))
		if (not Ok) then
			Fail(Service, "Start", Err)
			return
		end
		Service.Initialised = true
	end
	Service.State = "running"
	Service.Since = os.epoch("utc")
	if (Service.Module.Run) then
		Service.Co = coroutine.create(function() Service.Module.Run(Context(Service)) end)
		Service.Filter = nil
		Resume(Service)
	end
	os.queueEvent("blockcloud_status")
end

function Manager.Load()
	for _, Name in ipairs(Manager.Order) do
		local Path = fs.combine(Manager.Dir, Name .. ".lua")
		if (fs.exists(Path)) then
			local Ok, Module = pcall(BlockOS.Load, "/" .. Path)
			if (Ok and type(Module) == "table") then
				Manager.Services[Name] = {
					Name = Name, Module = Module, State = "stopped", Restarts = 0, Initialised = false
				}
			else
				Log.Error("services", "Could not load " .. Name .. ": " .. tostring(Module))
			end
		end
	end
end

function Manager.StartAll()
	for _, Name in ipairs(Manager.Order) do
		local Service = Manager.Services[Name]
		if (Service) then Start(Service) end
	end
end

function Manager.Get(Name)
	return Manager.Services[Name]
end

-- Stops a service's background loop and removes its operations.
function Manager.Stop(Name)
	local Service = Manager.Services[Name]
	if (not Service) then return end
	if (Service.Module.Stop) then pcall(Service.Module.Stop) end
	Service.Co = nil
	Service.Initialised = false
	Service.State = "stopped"
	Rpc.Unregister(Name)
	os.queueEvent("blockcloud_status")
end

function Manager.Restart(Name)
	local Service = Manager.Services[Name]
	if (not Service) then return end
	Manager.Stop(Name)
	Service.Restarts = 0
	Start(Service)
	Log.Info(Name, "Restarted")
end

function Manager.SetEnabled(Name, Enabled)
	local Settings = Server.Settings()
	Settings.Services = Settings.Services or {}
	Settings.Services[Name] = Enabled and true or false
	Server.Save()
	if (Enabled) then
		Manager.Restart(Name)
	else
		Manager.Stop(Name)
		Manager.Services[Name].State = "disabled"
		Log.Info(Name, "Disabled")
	end
end

function Manager.Dispatch(Event)
	if (Event[1] == "timer" and Timers[Event[2]]) then
		local Service = Timers[Event[2]]
		Timers[Event[2]] = nil
		if (Service.State == "restarting") then
			Log.Info(Service.Name, "Restarting (attempt " .. Service.Restarts .. ")")
			Start(Service)
		end
		return
	end
	for _, Name in ipairs(Manager.Order) do
		local Service = Manager.Services[Name]
		if (Service and Service.Co and (Service.Filter == nil or Service.Filter == Event[1])) then
			Resume(Service, table.unpack(Event, 1, Event.n))
		end
	end
end

-- One entry per service for the console: Name, Title, State, Level, Detail.
function Manager.Status()
	local List = {}
	for _, Name in ipairs(Manager.Order) do
		local Service = Manager.Services[Name]
		if (Service) then
			local Level, Detail = "ok", nil
			if (Service.State == "running" and Service.Module.Health) then
				local Ok, A, B = pcall(Service.Module.Health)
				if (Ok) then
					Level, Detail = A or "ok", B
				else
					Level, Detail = "error", tostring(A)
				end
			elseif (Service.State == "restarting" or Service.State == "stopped") then
				Level, Detail = "error", Service.LastError
			elseif (Service.State == "disabled") then
				Level = "off"
			end
			table.insert(List, {
				Name = Name, Title = Service.Module.Title or Name, State = Service.State,
				Level = Level, Detail = Detail, Restarts = Service.Restarts, System = Service.Module.System
			})
		end
	end
	return List
end

-- Services announced to clients during discovery.
function Manager.Announced()
	local List = {}
	for _, Name in ipairs(Manager.Order) do
		local Service = Manager.Services[Name]
		if (Service and Service.State == "running" and not Service.Module.Hidden) then
			local Entry = { Name = Name, Title = Service.Module.Title, Version = Service.Module.Version }
			if (Service.Module.Info) then
				for Key, Value in pairs(Service.Module.Info()) do Entry[Key] = Value end
			end
			table.insert(List, Entry)
		end
	end
	return List
end

return Manager
]=]
Files["blockos/server/services/blockdrive.lua"] = [[
-- BlockDrive: network file storage. Every remote path is resolved inside the storage volumes
-- (see server/volumes): the main storage folder pooled with the server's disk drives, plus
-- disks shared on their own. Uploads are staged in a hidden folder on the disk that will hold
-- the file and swapped in only once complete and verified, so an interrupted transfer never
-- damages an existing file.

local Path = BlockOS.Require("cloud/path")
local Codec = BlockOS.Require("cloud/codec")
local Auth = BlockOS.Require("cloud/auth")
local Server = BlockOS.Require("server/config")
local Volumes = BlockOS.Require("server/volumes")

local Drive = {
	Name = "blockdrive",
	Title = "BlockDrive",
	Description = "Network file storage.",
	Version = "1.1"
}

Drive.ChunkSize = 8192
Drive.TransferIdle = 90 * 1000
Drive.MaxTransfers = 16
Drive.MaxPerClient = 4
-- Space left free on the computer's own disk so the server can still write logs and settings.
Drive.Reserve = 16 * 1024

local Transfers = {}
local Usage = { Bytes = 0, Files = 0, Folders = 0, Scanned = false, Dirty = true }
local Rpc, Log

local function Fail(Code, Detail)
	Rpc.Fail(Code, Detail)
end

-- The main storage folder; disks are listed by Drive.Volumes().
function Drive.Root()
	return Volumes.Primary()
end

function Drive.Volumes()
	return Volumes.List()
end

local function Target(Remote)
	local Result, Err = Volumes.Target(Remote)
	if (not Result) then Fail(Err) end
	return Result
end

local function Modified(Local)
	local Ok, Attributes = pcall(fs.attributes, Local)
	return Ok and Attributes and Attributes.modified or 0
end

local function Entry(Local, Name)
	local Dir = fs.isDir(Local)
	return { Name = Name, Dir = Dir, Size = Dir and 0 or fs.getSize(Local), Modified = Modified(Local) }
end

-- Usable free bytes on one root.
local function FreeSpace(Root)
	Root = Root or Drive.Root()
	if (not fs.exists(Root)) then return 0 end
	local Free = tonumber(fs.getFreeSpace(Root)) or 0
	local OwnDisk = not fs.getDrive or fs.getDrive(Root) == "hdd"
	return math.max(0, Free - (OwnDisk and Drive.Reserve or 0))
end

local function QuotaLeft()
	local Quota = (tonumber(Server.Settings().QuotaMB) or 0) * 1024 * 1024
	if (Quota <= 0) then return math.huge end
	return math.max(0, Quota - Usage.Bytes)
end

-- Bytes clients may still add to a space (its roots together), limited by the quota.
local function Available(Roots)
	local Total = 0
	for _, Root in ipairs(Roots) do Total = Total + FreeSpace(Root) end
	return math.min(Total, QuotaLeft())
end

-- The largest single file a space can take: files are never split across disks.
local function Largest(Roots)
	local Best = 0
	for _, Root in ipairs(Roots) do Best = math.max(Best, FreeSpace(Root)) end
	return math.min(Best, QuotaLeft())
end

local function Capacity(Roots)
	if (not fs.getCapacity) then return nil end
	local Total = 0
	for _, Root in ipairs(Roots) do
		if (fs.exists(Root)) then Total = Total + (tonumber(fs.getCapacity(Root)) or 0) end
	end
	return Total
end

local function MaxFile()
	local Limit = (tonumber(Server.Settings().MaxFileKB) or 0) * 1024
	return Limit > 0 and Limit or nil
end

-- Walks every volume to total its size, yielding now and then on large trees.
local function Scan()
	local Bytes, Files, Folders, Steps = 0, 0, 0, 0
	local function Walk(Dir)
		for _, Name in ipairs(fs.list(Dir)) do
			if (Name ~= Path.Reserved) then
				local Child = fs.combine(Dir, Name)
				if (fs.isDir(Child)) then
					Folders = Folders + 1
					Walk(Child)
				else
					Files = Files + 1
					Bytes = Bytes + fs.getSize(Child)
				end
				Steps = Steps + 1
				if (Steps % 200 == 0) then sleep(0) end
			end
		end
	end
	for _, Root in ipairs(Volumes.Roots()) do
		if (fs.isDir(Root)) then pcall(Walk, Root) end
	end
	Usage.Bytes, Usage.Files, Usage.Folders = Bytes, Files, Folders
	Usage.Scanned = true
	Usage.Dirty = false
end

function Drive.Usage()
	return Usage
end

local function Changed()
	Usage.Dirty = true
	os.queueEvent("blockcloud_storage")
end

local function ParentOf(T)
	return { Normal = Path.Parent(T.Normal), Rel = Path.Parent(T.Rel), Roots = T.Roots, Space = T.Space, Volume = T.Volume }
end

local function RequireParent(T)
	if (not Volumes.IsDir(ParentOf(T))) then
		local Parent = Path.Parent(T.Normal)
		Fail("not_found", "The folder " .. (Parent == "" and "/" or Parent) .. " does not exist.")
	end
end

-- Top-level folders are the shares clients see first; they can only be changed on the server.
local function RequireNotShare(T)
	if (T.Normal == "" or not T.Normal:find("/")) then
		Fail("denied", "Shares can only be created, renamed or removed on the server.")
	end
end

local function Transfer(Ctx, ID, Kind)
	local Item = Transfers[ID]
	if (not Item or Item.Kind ~= Kind or Item.Client ~= Ctx.Client.ID) then Fail("transfer_lost") end
	Item.Touched = os.epoch("utc")
	return Item
end

local function NewTransfer(Ctx, Kind)
	local Count, Mine = 0, 0
	for _, Item in pairs(Transfers) do
		Count = Count + 1
		if (Item.Client == Ctx.Client.ID) then Mine = Mine + 1 end
	end
	if (Count >= Drive.MaxTransfers or Mine >= Drive.MaxPerClient) then Fail("busy") end
	local Item = { ID = Auth.RandomHex(8), Kind = Kind, Client = Ctx.Client.ID, Touched = os.epoch("utc") }
	Transfers[Item.ID] = Item
	return Item
end

local function EndTransfer(Item)
	Transfers[Item.ID] = nil
	if (Item.Temp and fs.exists(Item.Temp)) then pcall(fs.delete, Item.Temp) end
end

-- Reads Length bytes at Offset from a file.
local function ReadAt(Local, Offset, Length)
	local Handle = fs.open(Local, "rb")
	if (not Handle) then Fail("not_found") end
	if (Handle.seek) then
		Handle.seek("set", Offset)
	elseif (Offset > 0) then
		Handle.read(Offset)
	end
	local Data = Handle.read(Length) or ""
	Handle.close()
	return Data
end

local function Checksum(Local, Size)
	local Sum = 1
	for Offset = 0, Size - 1, Drive.ChunkSize * 4 do
		Sum = Codec.Adler32(ReadAt(Local, Offset, Drive.ChunkSize * 4), Sum)
		Rpc.Yield()
	end
	return Sum
end

-- Shares: the pool's top-level folders (from every pooled root), then disks shared on their own.
local function Shares()
	local Seen, List = {}, {}
	for _, Root in ipairs(Volumes.Pool()) do
		if (fs.isDir(Root)) then
			for _, Name in ipairs(fs.list(Root)) do
				if (Name ~= Path.Reserved and not Seen[Name] and fs.isDir(fs.combine(Root, Name))) then
					Seen[Name] = true
					table.insert(List, { Name = Name, Roots = Volumes.Pool(), Kind = "storage" })
				end
			end
		end
	end
	table.sort(List, function(A, B) return A.Name:lower() < B.Name:lower() end)
	for _, Volume in ipairs(Volumes.List()) do
		if (Volume.Mode == "share" and Volumes.Get(Volume.Name) == Volume) then
			table.insert(List, { Name = Volume.Name, Roots = { Volume.Root }, Kind = "disk", Label = Volume.Label })
		end
	end
	return List
end

local Ops = {}

function Ops.info(Ctx)
	local Settings = Server.Settings()
	local Names, Details = {}, {}
	for _, Share in ipairs(Shares()) do
		table.insert(Names, Share.Name)
		table.insert(Details, {
			Name = Share.Name, Kind = Share.Kind, Label = Share.Label, Disks = #Share.Roots,
			Free = Available(Share.Roots), Largest = Largest(Share.Roots), Capacity = Capacity(Share.Roots)
		})
	end
	local Pool = Volumes.Pool()
	return {
		Name = Settings.DisplayName,
		Shares = Names,
		Volumes = Details,
		Free = Available(Pool),
		Largest = Largest(Pool),
		Capacity = Capacity(Pool),
		PooledDisks = #Pool - 1,
		Used = Usage.Bytes,
		Quota = (tonumber(Settings.QuotaMB) or 0) * 1024 * 1024,
		MaxFile = MaxFile(),
		ChunkSize = Drive.ChunkSize,
		Permission = Ctx.Client.Permission
	}
end

function Ops.list(Ctx, Args)
	local T = Target(Args.Path or "")
	local Parts = Volumes.Find(T)
	if (#Parts == 0) then Fail("not_found") end
	local Merged, Entries = {}, {}
	local Count = 0
	for _, Part in ipairs(Parts) do
		if (not Part.Dir) then Fail("not_dir") end
		for _, Name in ipairs(fs.list(Part.Local)) do
			if (Name ~= Path.Reserved) then
				local Item = Entry(fs.combine(Part.Local, Name), Name)
				local Previous = Merged[Name]
				-- The same name on several disks: one folder, or the newest file.
				if (not Previous or (not Previous.Dir and (Item.Dir or Item.Modified > Previous.Modified))) then
					Merged[Name] = Item
				end
			end
			Count = Count + 1
			if (Count % 100 == 0) then Rpc.Yield() end
		end
	end
	for _, Item in pairs(Merged) do table.insert(Entries, Item) end
	if (T.Normal == "") then
		for _, Share in ipairs(Shares()) do
			if (Share.Kind == "disk") then
				local Item = Entry(Share.Roots[1], Share.Name)
				Item.Disk, Item.Label = true, Share.Label
				table.insert(Entries, Item)
			end
		end
	end
	table.sort(Entries, function(A, B)
		if (A.Dir ~= B.Dir) then return A.Dir end
		return A.Name:lower() < B.Name:lower()
	end)
	return { Path = T.Normal, Entries = Entries, Free = Available(T.Roots), Largest = Largest(T.Roots), ReadOnly = Ctx.Client.Permission ~= "write" }
end

function Ops.stat(Ctx, Args)
	local T = Target(Args.Path or "")
	local Part = Volumes.Locate(T)
	if (not Part) then Fail("not_found") end
	local Result = Entry(Part.Local, Path.Name(T.Normal))
	Result.Path = T.Normal
	return Result
end

function Ops.mkdir(Ctx, Args)
	local T = Target(Args.Path)
	RequireNotShare(T)
	if (Volumes.Locate(T)) then Fail("exists") end
	RequireParent(T)
	-- Folders cost almost nothing; make it where its parent already is.
	local Root = Volumes.Place(T, 0, FreeSpace)
	fs.makeDir(Volumes.Local(Root, T.Rel))
	Log.Info("blockdrive", Ctx.Client.Name .. " created " .. T.Normal)
	Changed()
	return Ops.stat(Ctx, { Path = T.Normal })
end

function Ops.delete(Ctx, Args)
	local T = Target(Args.Path)
	RequireNotShare(T)
	local Parts = Volumes.Find(T)
	if (#Parts == 0) then Fail("not_found") end
	for _, Part in ipairs(Parts) do fs.delete(Part.Local) end
	Log.Info("blockdrive", Ctx.Client.Name .. " deleted " .. T.Normal)
	Changed()
	return true
end

local function Relocate(Ctx, Args, Copy)
	local From, To = Target(Args.From), Target(Args.To)
	if (not Copy) then RequireNotShare(From) end
	RequireNotShare(To)
	local Shown = Volumes.Locate(From)
	if (not Shown) then Fail("not_found") end
	if (Volumes.Locate(To)) then Fail("exists") end
	if (From.Space == To.Space and Path.Within(From.Rel, To.Rel)) then Fail("invalid", "A folder cannot be moved or copied into itself.") end
	RequireParent(To)
	-- A folder may be spread over several disks; a file is its newest copy.
	local Parts = Shown.Dir and Volumes.Find(From) or { Shown }
	if (not Copy and From.Space == To.Space) then
		-- Within one space, each disk renames its own part: no data moves, no space needed.
		for _, Part in ipairs(Parts) do
			local Dest = Volumes.Local(Part.Root, To.Rel)
			local Parent = fs.getDir(Dest)
			if (not fs.exists(Parent)) then fs.makeDir(Parent) end
			fs.move(Part.Local, Dest)
		end
		for _, Part in ipairs(Volumes.Find(From)) do fs.delete(Part.Local) end
	else
		-- Copy file by file, each to a disk with room for it, so a folder spread over several
		-- disks can be copied even when no single disk could hold all of it.
		local Files, Dirs, Size = {}, {}, 0
		local function Collect(Local, Rel)
			if (fs.isDir(Local)) then
				table.insert(Dirs, Rel)
				for _, Name in ipairs(fs.list(Local)) do
					if (Name ~= Path.Reserved) then Collect(fs.combine(Local, Name), Path.Join(Rel, Name)) end
				end
			else
				table.insert(Files, { Source = Local, Rel = Rel, Size = fs.getSize(Local) })
				Size = Size + fs.getSize(Local)
			end
		end
		for _, Part in ipairs(Parts) do Collect(Part.Local, To.Rel) end
		if (Size > Available(To.Roots)) then Fail("no_space") end
		local Ok, Err = pcall(function()
			for _, Rel in ipairs(Dirs) do
				local Spot = { Rel = Rel, Roots = To.Roots }
				if (not Volumes.IsDir(Spot)) then fs.makeDir(Volumes.Local(Volumes.Place(Spot, 0, FreeSpace), Rel)) end
			end
			for Index, File in ipairs(Files) do
				local Spot = { Rel = File.Rel, Roots = To.Roots }
				if (not Volumes.Locate(Spot)) then
					local Root = Volumes.Place(Spot, File.Size, FreeSpace)
					if (not Root) then error("no disk has room for " .. File.Rel, 0) end
					local Dest = Volumes.Local(Root, File.Rel)
					local Parent = fs.getDir(Dest)
					if (not fs.exists(Parent)) then fs.makeDir(Parent) end
					fs.copy(File.Source, Dest)
				end
				if (Index % 20 == 0) then Rpc.Yield() end
			end
		end)
		if (not Ok) then
			-- A half-made copy is worse than none (usually a disk filled up or was removed).
			for _, Root in ipairs(To.Roots) do
				local Dest = Volumes.Local(Root, To.Rel)
				if (fs.exists(Dest)) then pcall(fs.delete, Dest) end
			end
			Changed()
			Fail("no_space", "The copy did not fit: " .. tostring(Err))
		end
		if (not Copy) then
			for _, Part in ipairs(Volumes.Find(From)) do fs.delete(Part.Local) end
		end
	end
	Log.Info("blockdrive", Ctx.Client.Name .. (Copy and " copied " or " moved ") .. From.Normal .. " to " .. To.Normal)
	Changed()
	return Ops.stat(Ctx, { Path = To.Normal })
end

function Ops.move(Ctx, Args) return Relocate(Ctx, Args, false) end
function Ops.copy(Ctx, Args) return Relocate(Ctx, Args, true) end

function Ops.upload_begin(Ctx, Args)
	local T = Target(Args.Path)
	local Size, Sum = tonumber(Args.Size), tonumber(Args.Sum)
	if (not Size or Size < 0 or Size ~= math.floor(Size) or not Sum) then Fail("invalid") end
	RequireNotShare(T)
	RequireParent(T)
	local Existing = Volumes.Locate(T)
	if (Existing and Existing.Dir) then Fail("is_dir") end
	if (Existing and not Args.Overwrite) then Fail("exists") end
	if (MaxFile() and Size > MaxFile()) then Fail("too_large", "Files on this server can be at most " .. math.floor(MaxFile() / 1024) .. " KB.") end
	-- The quota counts the net change; the chosen disk must hold the whole staged copy.
	if (Size - (Existing and fs.getSize(Existing.Local) or 0) > QuotaLeft()) then Fail("no_space") end
	local Root = Volumes.Place(T, Size, FreeSpace, Existing and Existing.Root)
	if (not Root) then
		Fail("no_space", #T.Roots > 1 and "No single disk has room for a file this size (files are not split across disks)." or nil)
	end
	local Item = NewTransfer(Ctx, "up")
	Item.Path, Item.Target, Item.Size, Item.Sum, Item.Overwrite = T.Normal, T, Size, Sum, Args.Overwrite and true or false
	-- Staged on the disk that will hold the file, so the final swap is a rename.
	Item.Root = Root
	Item.Local = Volumes.Local(Root, T.Rel)
	Item.Temp = fs.combine(Volumes.TempDir(Root), Item.ID)
	Item.Received, Item.Next, Item.Running = 0, 1, 1
	local Handle = fs.isDir(Volumes.TempDir(Root)) and fs.open(Item.Temp, "wb")
	if (not Handle) then
		Transfers[Item.ID] = nil
		Fail("internal", "Could not create a staging file.")
	end
	Handle.close()
	return { Transfer = Item.ID, ChunkSize = Drive.ChunkSize }
end

function Ops.upload_chunk(Ctx, Args)
	local Item = Transfer(Ctx, Args.Transfer, "up")
	local Index, Data = tonumber(Args.Index), Args.Data
	if (type(Data) ~= "string" or #Data > Drive.ChunkSize) then Fail("invalid") end
	-- Any chunk but the next one (usually a resend after a lost ack) just reports progress,
	-- and the client continues from Next.
	if (Index ~= Item.Next) then return { Next = Item.Next, Received = Item.Received } end
	if (Codec.Adler32(Data) ~= tonumber(Args.Sum)) then Fail("checksum") end
	if (Item.Received + #Data > Item.Size) then Fail("invalid", "More data than announced.") end
	local Handle = fs.exists(Item.Temp) and fs.open(Item.Temp, "ab")
	if (not Handle) then
		-- The disk was removed under the transfer.
		EndTransfer(Item)
		Fail("transfer_lost")
	end
	local Written = pcall(Handle.write, Data)
	pcall(Handle.close)
	if (not Written or fs.getSize(Item.Temp) ~= Item.Received + #Data) then
		EndTransfer(Item)
		Fail("no_space")
	end
	Item.Received = Item.Received + #Data
	Item.Running = Codec.Adler32(Data, Item.Running)
	Item.Next = Item.Next + 1
	return { Next = Item.Next, Received = Item.Received }
end

function Ops.upload_commit(Ctx, Args)
	local Item = Transfer(Ctx, Args.Transfer, "up")
	if (not fs.exists(Item.Temp)) then
		EndTransfer(Item)
		Fail("transfer_lost")
	end
	if (Item.Received ~= Item.Size or Item.Running ~= Item.Sum or fs.getSize(Item.Temp) ~= Item.Size) then
		EndTransfer(Item)
		Fail("checksum")
	end
	local Existing = Volumes.Locate(Item.Target)
	if (Existing and (Existing.Dir or not Item.Overwrite)) then
		EndTransfer(Item)
		Fail(Existing.Dir and "is_dir" or "exists")
	end
	local Parent = fs.getDir(Item.Local)
	if (not fs.exists(Parent)) then fs.makeDir(Parent) end
	-- Swap the finished file in. The old version is kept aside until the new one is in place.
	local Backup = Item.Temp .. ".old"
	if (fs.exists(Item.Local)) then fs.move(Item.Local, Backup) end
	local Ok, Err = pcall(fs.move, Item.Temp, Item.Local)
	if (not Ok) then
		if (fs.exists(Backup)) then fs.move(Backup, Item.Local) end
		EndTransfer(Item)
		Fail("internal", "Could not save the file: " .. tostring(Err))
	end
	if (fs.exists(Backup)) then fs.delete(Backup) end
	-- The new copy went to another disk: remove the old one (until then, the newer one wins).
	for _, Part in ipairs(Volumes.Find(Item.Target)) do
		if (Part.Local ~= Item.Local) then pcall(fs.delete, Part.Local) end
	end
	Transfers[Item.ID] = nil
	Log.Info("blockdrive", Ctx.Client.Name .. " uploaded " .. Item.Path .. " (" .. Item.Size .. " bytes)")
	Changed()
	return Ops.stat(Ctx, { Path = Item.Path })
end

function Ops.upload_abort(Ctx, Args)
	local Item = Transfers[Args.Transfer]
	if (Item and Item.Client == Ctx.Client.ID) then EndTransfer(Item) end
	return true
end

function Ops.download_begin(Ctx, Args)
	local T = Target(Args.Path)
	local Part = Volumes.Locate(T)
	if (not Part) then Fail("not_found") end
	if (Part.Dir) then Fail("is_dir") end
	local Item = NewTransfer(Ctx, "down")
	Item.Path, Item.Local = T.Normal, Part.Local
	Item.Size = fs.getSize(Part.Local)
	Item.Modified = Modified(Part.Local)
	Item.Sum = Checksum(Part.Local, Item.Size)
	return {
		Transfer = Item.ID, Size = Item.Size, Sum = Item.Sum, ChunkSize = Drive.ChunkSize,
		Chunks = math.ceil(Item.Size / Drive.ChunkSize), Modified = Item.Modified
	}
end

function Ops.download_chunk(Ctx, Args)
	local Item = Transfer(Ctx, Args.Transfer, "down")
	local Index = tonumber(Args.Index)
	if (not Index or Index < 1 or (Index - 1) * Drive.ChunkSize >= math.max(Item.Size, 1)) then Fail("invalid") end
	if (not fs.exists(Item.Local) or fs.getSize(Item.Local) ~= Item.Size or Modified(Item.Local) ~= Item.Modified) then
		EndTransfer(Item)
		Fail("changed")
	end
	local Data = ReadAt(Item.Local, (Index - 1) * Drive.ChunkSize, Drive.ChunkSize)
	return { Data = Data, Sum = Codec.Adler32(Data) }
end

function Ops.download_end(Ctx, Args)
	local Item = Transfers[Args.Transfer]
	if (Item and Item.Client == Ctx.Client.ID) then EndTransfer(Item) end
	return true
end

local Access = {
	info = "read", list = "read", stat = "read", download_begin = "read", download_chunk = "read", download_end = "read",
	mkdir = "write", delete = "write", move = "write", copy = "write",
	upload_begin = "write", upload_chunk = "write", upload_commit = "write", upload_abort = "write"
}

-- Creates the storage root and default share, clears staging files left by a shutdown,
-- and finds the disks.
function Drive.Prepare()
	local Settings = Server.Settings()
	local Ok, Err = Path.ValidRoot(Settings.StorageRoot)
	if (not Ok) then error(Err, 0) end
	local Root = Drive.Root()
	if (not fs.exists(Root)) then fs.makeDir(Root) end
	if (Settings.DefaultShare and Path.ValidName(Settings.DefaultShare)) then
		local Share = fs.combine(Root, Settings.DefaultShare)
		if (not fs.exists(Share)) then fs.makeDir(Share) end
	end
	local Temp = Volumes.TempDir(Root)
	if (fs.exists(Temp)) then fs.delete(Temp) end
	fs.makeDir(Temp)
	Transfers = {}
	Volumes.Refresh()
end

function Drive.Init(Ctx)
	Rpc, Log = Ctx.Rpc, Ctx.Log
	Drive.Prepare()
	local Registered = {}
	for Op, Level in pairs(Access) do
		Registered[Op] = { Access = Level, Handler = Ops[Op] }
	end
	Rpc.Register("blockdrive", Registered)
	Log.Info("blockdrive", "Serving " .. Drive.Root())
end

-- After disks come and go: update the volumes and drop uploads whose disk went away.
local function DisksChanged()
	if (not Volumes.Refresh()) then return end
	local Roots = {}
	for _, Root in ipairs(Volumes.Roots()) do Roots[Root] = true end
	for _, Item in pairs(Transfers) do
		if (Item.Root and not Roots[Item.Root]) then
			Log.Warn("blockdrive", "Stopped the upload of " .. tostring(Item.Path) .. ": its disk was removed")
			EndTransfer(Item)
		end
	end
	Changed()
end

local DiskEvents = { disk = true, disk_eject = true, peripheral = true, peripheral_detach = true, blockcloud_config = true }

function Drive.Run(Ctx)
	local Timer = os.startTimer(1)
	local DiskTimer
	while (true) do
		local Event, A = os.pullEvent()
		if (Event == "timer" and A == Timer) then
			local Now = os.epoch("utc")
			for _, Item in pairs(Transfers) do
				if (Now - Item.Touched > Drive.TransferIdle) then
					Log.Warn("blockdrive", "Abandoned " .. (Item.Kind == "up" and "upload of " or "download of ") .. tostring(Item.Path))
					EndTransfer(Item)
				end
			end
			if (Usage.Dirty) then
				Scan()
				os.queueEvent("blockcloud_storage")
			end
			Timer = os.startTimer(30)
		elseif (Event == "timer" and A == DiskTimer) then
			DiskTimer = nil
			DisksChanged()
		elseif (DiskEvents[Event]) then
			-- A wired network of drives sends a burst of events; look once it settles.
			if (DiskTimer) then os.cancelTimer(DiskTimer) end
			DiskTimer = os.startTimer(1)
		elseif (Event == "blockcloud_storage" and Usage.Dirty) then
			-- Rescan soon after changes, but not on every single one.
			os.cancelTimer(Timer)
			Timer = os.startTimer(5)
		end
	end
end

function Drive.ActiveTransfers()
	local Count = 0
	for _ in pairs(Transfers) do Count = Count + 1 end
	return Count
end

function Drive.Health()
	local Pool = Volumes.Pool()
	local Free = Available(Pool)
	local Active = Drive.ActiveTransfers()
	local Detail = (Active > 0 and (Active .. " transfer" .. (Active == 1 and "" or "s") .. ", ") or "")
		.. math.floor(Free / 1024) .. " KB free" .. (#Pool > 1 and (", " .. (#Pool - 1) .. " disk" .. (#Pool == 2 and "" or "s")) or "")
	if (Free < 32 * 1024) then return "warn", "Storage nearly full (" .. Detail .. ")" end
	return "ok", Detail
end

-- Space figures for the console and bcloud.
Drive.FreeSpace = FreeSpace
function Drive.PoolSpace()
	local Pool = Volumes.Pool()
	return Available(Pool), Capacity(Pool), #Pool - 1
end

function Drive.Info()
	return { ChunkSize = Drive.ChunkSize }
end

return Drive
]]
Files["blockos/server/services/core.lua"] = [[
-- BlockCloud Core: discovery, health checks and pairing. Always running.

local Protocol = BlockOS.Require("cloud/protocol")
local Clients = BlockOS.Require("server/clients")
local Server = BlockOS.Require("server/config")

local Core = {
	Name = "core",
	Title = "BlockCloud Core",
	Description = "Discovery, pairing and authentication.",
	Version = "1.0",
	System = true
}

local Manager

-- What this computer tells clients about itself.
function Core.Node()
	local Settings = Server.Settings()
	return {
		NodeID = Settings.NodeID,
		Hostname = Settings.Hostname,
		Name = Settings.DisplayName,
		Version = Server.Version(),
		Edition = "server",
		Encrypt = Settings.Encrypt ~= false,
		Pairing = Settings.PairingOpen ~= false,
		Public = Settings.Public ~= false,
		Visitors = Settings.Visitors == "read" and "read" or "write",
		Services = Manager and Manager.Announced() or {}
	}
end

local function Announce(Target)
	local Message = { BC = Protocol.Version, K = "announce", Node = Core.Node() }
	if (Target) then
		rednet.send(Target, Message, Protocol.Discover)
	else
		rednet.broadcast(Message, Protocol.Discover)
	end
end

Core.Announce = Announce

local function ValidNonce(Value)
	return type(Value) == "string" and #Value >= 16 and #Value <= 64 and Value:match("^%x+$") ~= nil
end

function Core.Init(Ctx)
	Manager = Ctx.Manager
	Ctx.Rpc.Register("core", {
		ping = { Access = "public", Handler = function()
			return { Node = Core.Node(), Time = os.epoch("utc") }
		end },

		pair_request = { Access = "public", Handler = function(Req, Args)
			if (Server.Settings().PairingOpen == false) then Ctx.Rpc.Fail("pairing_closed") end
			if (not ValidNonce(Args.Nonce) or type(Args.Check) ~= "string" or #Args.Check ~= 64) then
				Ctx.Rpc.Fail("invalid")
			end
			local Request, Err = Clients.Request(Req.Sender, Args.Name, Args.Nonce, Args.Check)
			if (not Request) then Ctx.Rpc.Fail(Err) end
			return { RequestID = Request.ID, ServerNonce = Request.ServerNonce, Status = "pending", Node = Core.Node() }
		end },

		-- Only the computer that asked can see the outcome of its request.
		pair_status = { Access = "public", Handler = function(Req, Args)
			Clients.Expire()
			local Request = Clients.Pending[Args.RequestID]
			if (not Request or Request.ComputerID ~= Req.Sender) then Ctx.Rpc.Fail("pairing_expired") end
			if (Request.Status == "denied") then
				Clients.Pending[Request.ID] = nil
				Ctx.Rpc.Fail("pairing_denied")
			elseif (Request.Status == "approved") then
				return { Status = "approved", ClientID = Request.ClientID, Permission = Request.Permission, Proof = Request.Proof, Node = Core.Node() }
			end
			return { Status = "pending" }
		end },

		-- Paired clients (and visitors on a public server) confirm access and learn their permission.
		hello = { Access = "read", Handler = function(Req)
			for ID, Request in pairs(Clients.Pending) do
				if (Request.ClientID == Req.Client.ID) then Clients.Pending[ID] = nil end
			end
			return { Permission = Req.Client.Permission, Name = Req.Client.Name, Node = Core.Node() }
		end },

		unpair = { Access = "read", Handler = function(Req)
			Clients.Revoke(Req.Client.ID)
			return true
		end }
	})
end

-- Approval from the console or bcloud: also nudges the waiting client so it need not poll.
function Core.Approve(RequestID, Code, Permission, Name)
	local Client, Err = Clients.Approve(RequestID, Code, Permission, Name)
	if (Client) then
		pcall(rednet.send, Client.ComputerID, { BC = Protocol.Version, K = "push", Op = "pair_status", ID = RequestID }, Protocol.Name("core"))
	end
	return Client, Err
end

function Core.Deny(RequestID)
	local Request = Clients.Pending[RequestID]
	local Ok = Clients.Deny(RequestID)
	if (Ok and Request) then
		pcall(rednet.send, Request.ComputerID, { BC = Protocol.Version, K = "push", Op = "pair_status", ID = RequestID }, Protocol.Name("core"))
	end
	return Ok
end

function Core.Run(Ctx)
	local Settings = Server.Settings()
	if (Protocol.OpenModems() > 0) then
		pcall(rednet.host, Protocol.Discover, Settings.Hostname)
		-- One announcement at boot lets clients that were waiting reconnect straight away.
		Announce()
		Ctx.Log.Info("core", "Announced " .. Settings.Hostname .. " on the network")
	else
		Ctx.Log.Warn("core", "No modem attached. Attach a wireless, ender or wired modem.")
	end
	local Housekeeping = os.startTimer(30)
	while (true) do
		local Event, A, B, C = os.pullEvent()
		if (Event == "rednet_message" and C == Protocol.Discover) then
			if (type(B) == "table" and B.BC == Protocol.Version and B.K == "discover") then
				Announce(A)
			end
		elseif (Event == "timer" and A == Housekeeping) then
			Ctx.Rpc.Cleanup()
			Clients.Expire()
			Clients.Flush()
			Housekeeping = os.startTimer(30)
		elseif (Event == "peripheral") then
			if (Protocol.OpenModems() > 0) then
				pcall(rednet.host, Protocol.Discover, Server.Settings().Hostname)
				Announce()
			end
			os.queueEvent("blockcloud_status")
		elseif (Event == "peripheral_detach") then
			os.queueEvent("blockcloud_status")
		elseif (Event == "blockcloud_config") then
			-- The hostname may have changed.
			if (Protocol.OpenModems() > 0) then
				pcall(rednet.unhost, Protocol.Discover)
				pcall(rednet.host, Protocol.Discover, Server.Settings().Hostname)
			end
		end
	end
end

function Core.Health()
	local Modems = Protocol.Modems()
	if (#Modems == 0) then return "error", "No modem attached" end
	local Pending = #Clients.PendingList()
	if (Pending > 0) then return "warn", Pending .. " pairing request" .. (Pending == 1 and "" or "s") end
	return "ok", #Modems .. " modem" .. (#Modems == 1 and "" or "s")
end

function Core.Stop()
	Clients.Flush(true)
end

return Core
]]
Files["blockos/server/services/updater.lua"] = [[
-- Software Update for Server Edition: checks the server channel on a schedule, installs new
-- releases in the background and restarts when no transfer is running.

local Server = BlockOS.Require("server/config")

local Service = {
	Name = "updater",
	Title = "Software Update",
	Description = "Keeps BlockOS Server Edition up to date.",
	Version = "1.0",
	System = true,
	Hidden = true
}

local Updater
local Log
Service.Message = "Not checked yet"

local function Busy(Ctx)
	local Drive = Ctx.Manager.Get("blockdrive")
	local Module = Drive and Drive.Module
	return Module and Module.ActiveTransfers and Module.ActiveTransfers() > 0
end

-- Checks, and installs when Install is true. Returns the manifest when one was found.
function Service.Check(Install)
	if (not http) then
		Service.Message = "HTTP is disabled on this Minecraft server"
		return nil
	end
	local Manifest, Err = Updater.Check()
	if (not Manifest) then
		Service.Message = "Check failed: " .. tostring(Err)
		Log.Warn("updater", Service.Message)
		return nil
	end
	if (not Manifest.Newer) then
		Service.Message = "Up to date (" .. Server.Version() .. ")"
		return Manifest
	end
	Service.Message = "Version " .. Manifest.Version .. " is available"
	Log.Info("updater", Service.Message)
	if (Install) then
		Service.Message = "Installing " .. Manifest.Version .. "..."
		os.queueEvent("blockcloud_status")
		local Ok, ApplyErr = Updater.Apply(Manifest)
		if (Ok) then
			Service.Message = "Installed " .. Manifest.Version .. "; restart to finish"
			Service.Pending = Manifest.Version
			Log.Info("updater", Service.Message)
		else
			Service.Message = "Install failed: " .. tostring(ApplyErr)
			Log.Error("updater", Service.Message)
		end
	end
	return Manifest
end

function Service.Init(Ctx)
	Log = Ctx.Log
	Updater = Server.ConfigureUpdater()
end

function Service.Run(Ctx)
	local Timer = os.startTimer(60)
	while (true) do
		local Event, A = os.pullEvent()
		local Settings = Server.Settings()
		if (Event == "blockcloud_update") then
			-- From the console or bcloud: A is "check" or "install".
			Service.Check(A == "install")
			os.queueEvent("blockcloud_status")
			if (Service.Pending and Settings.AutoRestart) then
				os.cancelTimer(Timer)
				Timer = os.startTimer(10)
			end
		elseif (Event == "timer" and A == Timer) then
			if (Service.Pending and Settings.AutoRestart) then
				if (not Busy(Ctx)) then
					Log.Info("updater", "Restarting to finish installing " .. Service.Pending)
					sleep(2)
					os.reboot()
				end
			elseif (Settings.AutoUpdate and not Service.Pending) then
				Service.Check(Settings.AutoInstall)
				os.queueEvent("blockcloud_status")
			end
			local Hours = math.max(1, tonumber(Settings.UpdateHours) or 6)
			Timer = os.startTimer(Service.Pending and 30 or Hours * 3600)
		end
	end
end

function Service.Health()
	if (Service.Pending) then return "warn", "Restart to finish installing " .. Service.Pending end
	return "ok", Service.Message
end

return Service
]]
Files["blockos/server/setup.lua"] = [=[
-- Server Edition setup: hostname, storage location, admin password and updates.
-- Shown by the installer, and on first boot if setup never finished.

local Server = BlockOS.Require("server/config")
local Path = BlockOS.Require("cloud/path")

local Setup = {}

local function Defaults()
	local Settings = Server.Settings()
	local Label = os.getComputerLabel()
	return {
		Hostname = (Label and Server.ValidHostname(Label)) and Label or Settings.Hostname,
		DisplayName = Settings.DisplayName,
		StorageRoot = Settings.StorageRoot,
		Password = "",
		Confirm = "",
		AutoUpdate = Settings.AutoUpdate ~= false,
		AutoInstall = Settings.AutoInstall ~= false,
		Public = Settings.Public ~= false,
		Visitors = Settings.Visitors == "read" and "read" or "write"
	}
end

-- Storage locations to offer: the default folder and a folder on each attached disk drive.
local function Locations()
	local List = { { Text = "This computer  /blockcloud/storage", Path = "/blockcloud/storage" } }
	for _, Side in ipairs(peripheral.getNames()) do
		if (peripheral.getType(Side) == "drive" and disk.hasData(Side)) then
			local Mount = disk.getMountPath(Side)
			table.insert(List, { Text = "Disk " .. (disk.getLabel(Side) or Mount) .. "  /" .. Mount .. "/blockcloud", Path = "/" .. Mount .. "/blockcloud" })
		end
	end
	return List
end

local function Finish(State)
	local Settings = Server.Settings()
	Settings.Hostname = State.Hostname
	Settings.DisplayName = State.DisplayName
	Settings.StorageRoot = "/" .. fs.combine(State.StorageRoot, "")
	Settings.AutoUpdate = State.AutoUpdate
	Settings.AutoInstall = State.AutoInstall
	Settings.Public = State.Public ~= false
	Settings.Visitors = State.Visitors == "read" and "read" or "write"
	Settings.Configured = true
	Server.Save()
	if (State.Password ~= "") then Server.SetPassword(State.Password) end
	os.setComputerLabel(State.Hostname)
	if (not fs.exists(Settings.StorageRoot)) then fs.makeDir(Settings.StorageRoot) end
end

Setup.Finish = Finish

-- Validates the answers; returns an error message or nil.
local function Check(State, Step)
	if (Step == "identity") then
		if (not Server.ValidHostname(State.Hostname)) then return "The hostname needs 1-24 letters, digits, - or _." end
		if (#State.DisplayName == 0 or #State.DisplayName > 32) then return "The name needs 1-32 characters." end
	elseif (Step == "storage") then
		local Ok, Err = Path.ValidRoot(State.StorageRoot)
		if (not Ok) then return Err end
	elseif (Step == "admin") then
		if (State.Password ~= State.Confirm) then return "The passwords do not match." end
	end
	return nil
end

function Setup.Run(Opts)
	Opts = Opts or {}
	local Ui = BlockOS.Require("ui")
	local Gfx = BlockOS.Require("gfx")
	local Logo = BlockOS.Require("logo")
	local State = Defaults()
	local Steps = { "welcome", "identity", "storage", "access", "admin", "updates" }
	if (Opts.Install) then table.insert(Steps, "install") end
	table.insert(Steps, "done")
	local Page = Ui.Page.new({ Bg = "WindowBg" })
	local StepIndex = 1
	local Error = nil
	local Build

	local function Go(Delta)
		if (Delta > 0) then
			Error = Check(State, Steps[StepIndex])
			if (Error) then
				Page:Invalidate()
				Build()
				return
			end
		end
		StepIndex = math.max(1, math.min(#Steps, StepIndex + Delta))
		Error = nil
		Build()
	end

	local function Heading(Title, Subtitle)
		Page:Add(Ui.Label.new({ X = 3, Y = 2, W = Page.W - 4, Text = Title, Fg = "Accent" }))
		if (Subtitle) then
			Page:Add(Ui.Label.new({ X = 3, Y = 3, W = Page.W - 4, H = 2, Text = Subtitle, Fg = "SubText" }))
		end
	end

	local function Footer(NextText, OnNext)
		local W, H = Page.W, Page.H
		if (StepIndex > 1 and not State.Finished) then
			Page:Add(Ui.Button.new({ X = 2, Y = H - 1, Text = " Back ", OnClick = function() Go(-1) end }))
		end
		Page:Add(Ui.Button.new({ X = W - #NextText - 3, Y = H - 1, Text = " " .. NextText .. " ", Style = "primary", OnClick = OnNext or function() Go(1) end }))
		Page:Add(Ui.Label.new({ X = 3, Y = H - 3, W = W - 4, Fg = colors.red, Text = function() return Error or "" end }))
	end

	local function Field(Y, Label, Key, Opts2)
		Opts2 = Opts2 or {}
		Page:Add(Ui.Label.new({ X = 3, Y = Y, Text = Label }))
		local Input = Page:Add(Ui.Input.new({ X = 17, Y = Y, W = math.min(28, Page.W - 19), Value = State[Key], Mask = Opts2.Mask, MaxLength = Opts2.Max }))
		Input.OnChange = function(_, Value) State[Key] = Value end
		Input.OnSubmit = function() Go(1) end
		return Input
	end

	local Builders = {}

	function Builders.welcome()
		local W, H = Page.W, Page.H
		local LogoW, LogoH = Logo.Size(Logo.Big)
		Page:Add(Ui.Canvas.new({ X = 1, Y = 2, W = W, H = LogoH, OnDraw = function(Self, T)
			Logo.Draw(T, math.floor((W - LogoW) / 2) + 1, Self.Y, Logo.Big)
		end }))
		Page:Add(Ui.Label.new({ X = 1, Y = LogoH + 3, W = W, Align = "center", Text = "BlockOS Server Edition" .. (Opts.Version and (" " .. Opts.Version) or "") }))
		Page:Add(Ui.Label.new({ X = 3, Y = LogoH + 5, W = W - 4, H = 3, Align = "center", Fg = "SubText",
			Text = "Turns this computer into a BlockCloud server with BlockDrive network storage for your BlockOS computers." }))
		Footer("Set Up \26")
	end

	function Builders.identity()
		Heading("Name this server", "Clients find it by its hostname and show its name in BlockDrive.")
		local First = Field(6, "Hostname", "Hostname", { Max = 24 })
		Field(8, "Display name", "DisplayName", { Max = 32 })
		Page:Add(Ui.Label.new({ X = 3, Y = 10, W = Page.W - 4, Fg = "SubText", Text = "Computer ID: " .. os.getComputerID() }))
		Page:SetFocus(First)
		Footer("Continue")
	end

	function Builders.storage()
		Heading("Storage location", "BlockDrive keeps shared files here. Disk drives you attach, also over wired modems, are pooled with it automatically.")
		local Items = Locations()
		local List = Page:Add(Ui.List.new({ X = 3, Y = 6, W = Page.W - 4, H = math.min(#Items, 4), Items = Items, Bg = "Panel" }))
		for Index, Item in ipairs(Items) do
			if (Item.Path == State.StorageRoot) then List.Selected = Index end
		end
		local Input = Field(math.min(#Items, 4) + 7, "Folder", "StorageRoot")
		List.OnSelect = function(_, _, Item)
			State.StorageRoot = Item.Path
			Input:SetValue(Item.Path)
		end
		Footer("Continue")
	end

	function Builders.access()
		Heading("Who can use it", "A public server works for every computer in range straight away. A private one needs the administrator to pair each computer with a code.")
		local Visitors
		Page:Add(Ui.Toggle.new({ X = 3, Y = 6, Value = not State.Public, OnChange = function(_, Value)
			State.Public = not Value
			Visitors.Visible = State.Public
			Page:Invalidate()
		end }))
		Page:Add(Ui.Label.new({ X = 9, Y = 6, Text = "Require pairing (private server)" }))
		Visitors = Page:Add(Ui.Tabs.new({ X = 3, Y = 8, W = math.min(30, Page.W - 4), Items = { "Visitors: read only", "Read & write" },
			Selected = State.Visitors == "read" and 1 or 2, Visible = State.Public, OnChange = function(_, Index)
				State.Visitors = Index == 1 and "read" or "write"
			end }))
		Page:Add(Ui.Label.new({ X = 3, Y = 10, W = Page.W - 4, H = 3, Fg = "SubText",
			Text = "Paired computers always keep their own permission and encrypted transfers. Change this later in Settings > Security." }))
		Footer("Continue")
	end

	function Builders.admin()
		Heading("Administrator password", "Locks this console. Leave it empty if the Data Center is private. Services run either way.")
		local First = Field(6, "Password", "Password", { Mask = "\7" })
		Field(8, "Confirm", "Confirm", { Mask = "\7" })
		Page:SetFocus(First)
		Footer("Continue")
	end

	function Builders.updates()
		Heading("Software updates", "Server Edition updates from its own channel, never the desktop one.")
		Page:Add(Ui.Toggle.new({ X = 3, Y = 6, Value = State.AutoUpdate, OnChange = function(_, Value) State.AutoUpdate = Value end }))
		Page:Add(Ui.Label.new({ X = 9, Y = 6, Text = "Check for updates automatically" }))
		Page:Add(Ui.Toggle.new({ X = 3, Y = 8, Value = State.AutoInstall, OnChange = function(_, Value) State.AutoInstall = Value end }))
		Page:Add(Ui.Label.new({ X = 9, Y = 8, Text = "Install them in the background" }))
		Page:Add(Ui.Label.new({ X = 3, Y = 10, W = Page.W - 4, H = 2, Fg = "SubText", Text = "Change this later in the console under Settings > Updates." }))
		Footer(Opts.Install and "Install" or "Continue")
	end

	function Builders.install()
		Heading("Installing BlockOS Server " .. (Opts.Version or ""), "Copying system files. Your stored files and settings are kept.")
		local Bar = Page:Add(Ui.Progress.new({ X = 3, Y = 7, W = Page.W - 4, Value = 0 }))
		local Status = Page:Add(Ui.Label.new({ X = 3, Y = 9, W = Page.W - 4, Text = "Preparing...", Fg = "SubText" }))
		Page:Draw()
		local Ok, Err = pcall(Opts.Install, function(Done, Total, Name)
			Bar.Value = Total > 0 and Done / Total or 1
			Status.Text = Name or ""
			Page:Draw()
		end)
		if (not Ok) then
			Status.Text = "Install failed: " .. tostring(Err)
			Status.Fg = colors.red
			Page:Add(Ui.Button.new({ X = Page.W - 8, Y = Page.H - 1, Text = " Quit ", OnClick = function() Page:Stop() end }))
			Page:Invalidate()
			return
		end
		Finish(State)
		State.Finished = true
		Go(1)
	end

	function Builders.done()
		if (not State.Finished) then
			Finish(State)
			State.Finished = true
		end
		Heading("Ready", nil)
		Page:Add(Ui.Label.new({ X = 3, Y = 4, W = Page.W - 4, H = 6, Text =
			State.Hostname .. " will start BlockCloud and BlockDrive every time it boots. To connect a BlockOS computer, install BlockDrive there, choose Add Server, and approve it in this console under Pairing." }))
		local Text = Opts.Install and "Restart" or "Start Server"
		Footer(Text, function() Page:Stop() end)
	end

	function Build()
		Page:Clear()
		Builders[Steps[StepIndex]]()
		function Page:OnDrawOver(T, Th)
			local X = math.floor((self.W - (#Steps * 2 - 1)) / 2) + 1
			for Index = 1, #Steps do
				Gfx.Write(T, X + (Index - 1) * 2, self.H, "\7", Index == StepIndex and Th.Accent or Th.Border, Th.WindowBg)
			end
		end
		Page:Invalidate()
	end

	function Page:OnLayout() Build() end
	function Page:OnTerminate()
		if (Opts.Install) then self:Stop() end
	end
	Page:Run()
	term.setBackgroundColor(colors.black)
	term.clear()
	term.setCursorPos(1, 1)
	return State
end

-- Plain prompts for basic computers (no colour screen) and unattended scripts.
function Setup.RunText(Opts)
	Opts = Opts or {}
	local State = Defaults()
	local function Ask(Question, Key, Mask)
		while (true) do
			write(Question .. " [" .. (Mask and "" or tostring(State[Key])) .. "]: ")
			local Answer = read(Mask)
			if (Answer ~= "") then State[Key] = Answer end
			return
		end
	end
	print("BlockOS Server setup")
	for _, Step in ipairs({ "identity", "storage", "access", "admin" }) do
		while (true) do
			if (Step == "access") then
				write("Require pairing (private server)? (y/N): ")
				State.Public = (read() or ""):lower():sub(1, 1) ~= "y"
			elseif (Step == "identity") then
				Ask("Hostname", "Hostname")
				Ask("Display name", "DisplayName")
			elseif (Step == "storage") then
				Ask("Storage folder", "StorageRoot")
			else
				State.Password, State.Confirm = "", ""
				Ask("Admin password (empty for none)", "Password", "*")
				if (State.Password ~= "") then Ask("Confirm password", "Confirm", "*") end
				if (State.Password == "") then State.Confirm = "" end
			end
			local Err = Check(State, Step)
			if (not Err) then break end
			printError(Err)
		end
	end
	if (Opts.Install) then Opts.Install() end
	Finish(State)
	print("Setup complete.")
	return State
end

return Setup
]=]
Files["blockos/server/ui/console.lua"] = [=[
-- BlockOS Server console: status at a glance, paired clients, pairing approvals, logs and
-- server settings. Administration only; the services run whether or not this is open.

local Host = ...
local Ui = BlockOS.Require("ui")
local Gfx = BlockOS.Require("gfx")
local Theme = BlockOS.Require("theme")
local Config = BlockOS.Require("config")
local Server = BlockOS.Require("server/config")
local Manager = BlockOS.Require("server/service_manager")
local Clients = BlockOS.Require("server/clients")
local Rpc = BlockOS.Require("server/rpc")
local Log = BlockOS.Require("server/log")
local Protocol = BlockOS.Require("cloud/protocol")
local Path = BlockOS.Require("cloud/path")
local Updater = BlockOS.Require("updater")
local Volumes = BlockOS.Require("server/volumes")

local Page = Ui.Page.new()
local Tabs = { "Overview", "Clients", "Pairing", "Logs", "Settings" }
local State = { Tab = 1, Section = 1, Locked = Server.HasPassword(), Message = nil, RebuildTimer = nil, Password = "" }
local Build

local Dots = { ok = colors.lime, warn = colors.orange, error = colors.red, off = colors.gray }

local Util = {}

function Util.Ago(Epoch)
	if (not Epoch) then return "never" end
	local Seconds = math.max(0, math.floor((os.epoch("utc") - Epoch) / 1000))
	if (Seconds < 60) then return "just now" end
	if (Seconds < 3600) then return math.floor(Seconds / 60) .. "m ago" end
	if (Seconds < 86400) then return math.floor(Seconds / 3600) .. "h ago" end
	return math.floor(Seconds / 86400) .. "d ago"
end

function Util.Uptime()
	local Seconds = math.floor(os.clock())
	local Hours = math.floor(Seconds / 3600)
	local Minutes = math.floor(Seconds / 60) % 60
	return Hours > 0 and (Hours .. "h " .. Minutes .. "m") or (Minutes .. "m")
end

function Util.Drive()
	local Service = Manager.Get("blockdrive")
	return Service and Service.Module
end

function Util.Core()
	local Service = Manager.Get("core")
	return Service and Service.Module
end

function Util.Updates()
	local Service = Manager.Get("updater")
	return Service and Service.Module
end

function Util.Say(Text)
	State.Message = Text
	Page:Invalidate()
end

-- Several status events often arrive together; rebuild once, shortly after.
function Util.Soon()
	if (not State.RebuildTimer) then State.RebuildTimer = os.startTimer(.5) end
end

-- One line of label + coloured dot + text, for the overview.
function Util.Line(Y, Label, Level, Text, X, W)
	Page:Add(Ui.Canvas.new({
		X = X, Y = Y, W = W, H = 1,
		OnDraw = function(Self, T, Th)
			Gfx.Write(T, Self.X, Self.Y, Gfx.Pad(Label, 10), Th.SubText, Th.WindowBg)
			local TextX = Self.X + 10
			if (Level) then
				Gfx.Write(T, TextX, Self.Y, "\7", Dots[Level] or Th.SubText, Th.WindowBg)
				TextX = TextX + 2
			end
			Gfx.Write(T, TextX, Self.Y, Gfx.Truncate(Text, Self.W - (TextX - Self.X)), Th.Text, Th.WindowBg)
		end
	}))
end

local Tab = {}

function Tab.Overview(X, Y, W, H)
	local Settings = Server.Settings()
	Page:Add(Ui.Label.new({ X = X, Y = Y, W = W, Fg = "Accent", Text = Settings.Hostname .. "  \7  " .. Settings.DisplayName }))
	Page:Add(Ui.Label.new({ X = X, Y = Y + 1, W = W, Fg = "SubText",
		Text = "BlockOS Server " .. Server.Version() .. "  \7  Computer #" .. os.getComputerID() .. "  \7  up " .. Util.Uptime() }))
	local Row = Y + 3
	local Modems = Protocol.Modems()
	local Sides = {}
	for _, Modem in ipairs(Modems) do
		table.insert(Sides, Modem.Side .. (Modem.Wireless and " wireless" or " wired") .. (Modem.Open and "" or " closed"))
	end
	Util.Line(Row, "Network", #Modems > 0 and "ok" or "error", #Modems > 0 and table.concat(Sides, ", ") or "No modem attached!", X, W)
	Row = Row + 1
	for Index, Status in ipairs(Manager.Status()) do
		Util.Line(Row, Index == 1 and "Services" or "", Status.Level, Gfx.Pad(Status.Title, 17) .. (Status.State ~= "running" and Status.State or (Status.Detail or "")), X, W)
		Row = Row + 1
	end
	local Drive = Util.Drive()
	Row = Row + 1
	if (Drive and Drive.Root) then
		local Root = Drive.Root()
		local Usage = Drive.Usage()
		-- The pool: the main storage folder and every pooled disk together.
		local Free, Capacity, Pooled = Drive.PoolSpace()
		local Counts = Volumes.Summary()
		Page:Add(Ui.Label.new({ X = X, Y = Row, Text = "Storage", Fg = "SubText" }))
		if (Capacity and Capacity > 0) then
			Page:Add(Ui.Progress.new({ X = X + 10, Y = Row, W = math.max(4, W - 30), Value = 1 - Free / Capacity }))
			Page:Add(Ui.Label.new({ X = X + W - 19, Y = Row, W = 19, Align = "right", Text = Gfx.FormatSize(Free) .. " free" }))
		else
			Page:Add(Ui.Label.new({ X = X + 10, Y = Row, W = W - 10, Text = Gfx.FormatSize(Free) .. " free" }))
		end
		Page:Add(Ui.Label.new({ X = X + 10, Y = Row + 1, W = W - 10, Fg = "SubText",
			Text = Root .. (Pooled > 0 and (" + " .. Pooled .. " disk" .. (Pooled == 1 and "" or "s")) or "") .. "  \7  " .. Usage.Files .. " files, " .. Gfx.FormatSize(Usage.Bytes) }))
		if (Counts.share + Counts.off > 0) then
			Page:Add(Ui.Label.new({ X = X + 10, Y = Row + 2, W = W - 10, Fg = "SubText",
				Text = Counts.share .. " disk" .. (Counts.share == 1 and "" or "s") .. " shared on their own, " .. Counts.off .. " unused" }))
			Row = Row + 1
		end
		Row = Row + 3
	end
	local List = Clients.List()
	local Recent = 0
	for _, Client in ipairs(List) do
		if (Client.LastSeen and os.epoch("utc") - Client.LastSeen < 600000) then Recent = Recent + 1 end
	end
	local Pending = #Clients.PendingList()
	local Visitors = 0
	for _, Seen in pairs(Rpc.Visitors) do
		if (os.epoch("utc") - Seen < 600000) then Visitors = Visitors + 1 end
	end
	Util.Line(Row, "Access", nil, Util.AccessText(), X, W)
	Util.Line(Row + 1, "Clients", Pending > 0 and "warn" or nil,
		#List .. " paired, " .. Recent .. " active" .. (Server.Settings().Public ~= false and (", " .. Visitors .. " visitors") or "")
		.. (Pending > 0 and (", " .. Pending .. " waiting to pair") or ""), X, W)
	Util.Line(Row + 2, "Requests", nil, Rpc.Stats.Requests .. " handled, " .. Rpc.Stats.Rejected .. " rejected, " .. Rpc.Stats.Errors .. " errors", X, W)
end

function Tab.Clients(X, Y, W, H)
	local Items = {}
	for _, Client in ipairs(Clients.List()) do
		table.insert(Items, {
			Text = Client.Name .. " (#" .. Client.ComputerID .. ")",
			Right = (Client.Permission == "write" and "read/write" or "read only") .. "  " .. Util.Ago(Client.LastSeen),
			Icon = "\2", IconFg = Client.Permission == "write" and "Accent" or "SubText",
			Client = Client
		})
	end
	if (#Items == 0) then
		Page:Add(Ui.Label.new({ X = X, Y = Y, W = W, H = 4, Fg = "SubText",
			Text = "No computers are paired yet. On a BlockOS computer, open BlockDrive and choose Add Server; the request appears under Pairing." }))
		return
	end
	local List = Page:Add(Ui.List.new({ X = X, Y = Y, W = W, H = H - 2, Items = Items, Bg = "Panel" }))
	List.Selected = 1
	local function Selected()
		local Item = List.Items[List.Selected]
		return Item and Item.Client
	end
	Page:Add(Ui.Button.new({ X = X, Y = Y + H - 1, Text = " Permission ", OnClick = function()
		local Client = Selected()
		if (not Client) then return end
		local Choice = Ui.Alert("Permission", "What may " .. Client.Name .. " do?", { "Cancel", "Read only", "Read & write" })
		if (Choice == 2 or Choice == 3) then
			Clients.SetPermission(Client.ID, Choice == 2 and "read" or "write")
			Build()
		end
	end }))
	Page:Add(Ui.Button.new({ X = X + 13, Y = Y + H - 1, Text = " Rename ", OnClick = function()
		local Client = Selected()
		local Name = Client and Ui.Prompt("Rename", "Name for computer #" .. Client.ComputerID .. ":", Client.Name)
		if (Name and #Name > 0) then
			Clients.Rename(Client.ID, Name)
			Build()
		end
	end }))
	Page:Add(Ui.Button.new({ X = X + 22, Y = Y + H - 1, Text = " Remove ", Style = "danger", OnClick = function()
		local Client = Selected()
		if (Client and Ui.Confirm("Remove", "Unpair " .. Client.Name .. "? It will have to pair again to use BlockDrive.", "Remove")) then
			Clients.Revoke(Client.ID)
			Build()
		end
	end }))
end

-- Public: any computer may use BlockDrive with the visitor permission. Private: pairing needed.
function Util.AccessText()
	local Settings = Server.Settings()
	if (Settings.Public == false) then return "Private: computers must pair" end
	return "Public: anyone may " .. (Settings.Visitors == "read" and "read" or "read and write") .. ", no pairing"
end

function Tab.Pairing(X, Y, W, H)
	local Settings = Server.Settings()
	Page:Add(Ui.Label.new({ X = X, Y = Y + 1, W = W, Fg = "Accent", Text = Util.AccessText() .. (Settings.Public ~= false and " (optional)" or "") }))
	Y, H = Y + 1, H - 1
	Page:Add(Ui.Toggle.new({ X = X, Y = Y, Value = Settings.PairingOpen ~= false, OnChange = function(_, Value)
		Settings.PairingOpen = Value
		Server.Save()
		Log.Info("auth", Value and "Pairing requests allowed" or "Pairing requests turned off")
	end }))
	Page:Add(Ui.Label.new({ X = X + 5, Y = Y, W = W - 5, Text = "Accept new pairing requests" }))
	local Items = {}
	for _, Request in ipairs(Clients.PendingList()) do
		table.insert(Items, { Text = Request.Name .. " (#" .. Request.ComputerID .. ")", Right = Util.Ago(Request.Created), Icon = "?", IconFg = "Accent", Request = Request })
	end
	if (#Items == 0) then
		Page:Add(Ui.Label.new({ X = X, Y = Y + 2, W = W, H = 5, Fg = "SubText",
			Text = "No computers are waiting. When one asks to pair, it shows an 8-character code: approve the request here and type that code to confirm it is the right computer."
				.. (Settings.Public ~= false and " On a public server, pairing gives a computer its own permission and encrypted transfers." or "") }))
		return
	end
	local List = Page:Add(Ui.List.new({ X = X, Y = Y + 2, W = W, H = H - 4, Items = Items, Bg = "Panel" }))
	List.Selected = 1
	local function Approve()
		local Item = List.Items[List.Selected]
		if (not Item) then return end
		local Request = Item.Request
		local Code = Ui.Prompt("Approve " .. Request.Name, "Type the code shown on computer #" .. Request.ComputerID .. ":", "")
		if (not Code or Code == "") then return end
		local Choice = Ui.Alert("Permission", "What may " .. Request.Name .. " do?", { "Cancel", "Read only", "Read & write" })
		if (Choice ~= 2 and Choice ~= 3) then return end
		local Client, Err = Util.Core().Approve(Request.ID, Code, Choice == 2 and "read" or "write")
		if (Client) then
			Util.Say("Paired " .. Client.Name .. ".")
		else
			Ui.Alert("Not approved", Err or "Unknown error")
		end
		Build()
	end
	List.OnActivate = Approve
	Page:Add(Ui.Button.new({ X = X, Y = Y + H - 1, Text = " Approve... ", Style = "primary", OnClick = Approve }))
	Page:Add(Ui.Button.new({ X = X + 13, Y = Y + H - 1, Text = " Decline ", OnClick = function()
		local Item = List.Items[List.Selected]
		if (Item) then
			Util.Core().Deny(Item.Request.ID)
			Build()
		end
	end }))
end

function Tab.Logs(X, Y, W, H)
	local Colours = { debug = "SubText", info = "Text", warn = colors.orange, error = colors.red }
	local Items = {}
	for _, Entry in ipairs(Log.Lines) do
		table.insert(Items, { Text = Entry.Time:sub(12) .. " " .. Entry.Source .. ": " .. Entry.Text, Fg = Colours[Entry.Level] })
	end
	local List = Page:Add(Ui.List.new({ X = X, Y = Y, W = W, H = H, Items = Items, Bg = "Panel" }))
	List.Scroll = math.max(0, #Items - H)
	List.OnActivate = function(_, _, Item) Ui.Alert("Log", Item.Text) end
end

--
-- Settings
--

local Sections = { "General", "Storage", "Disks", "Security", "Updates", "Services", "Appearance" }
local Section = {}

-- A labelled input with a Set button; Apply returns an error message or nil.
function Util.Field(X, Y, W, Label, Value, Apply, Mask)
	Page:Add(Ui.Label.new({ X = X, Y = Y, Text = Label }))
	local Field = Page:Add(Ui.Input.new({ X = X + 11, Y = Y, W = W - 18, Value = tostring(Value or ""), Mask = Mask }))
	local function Submit()
		local Err = Apply(Field.Value)
		if (Err) then Ui.Alert(Label, Err) else Util.Say(Label .. " saved.") end
		Build()
	end
	Field.OnSubmit = Submit
	Page:Add(Ui.Button.new({ X = X + W - 6, Y = Y, W = 6, Text = "Set", OnClick = Submit }))
	return Field
end

function Util.Switch(X, Y, W, Label, Key, After)
	local Settings = Server.Settings()
	Page:Add(Ui.Toggle.new({ X = X, Y = Y, Value = Settings[Key] ~= false, OnChange = function(_, Value)
		Settings[Key] = Value
		Server.Save()
		if (After) then After(Value) end
	end }))
	Page:Add(Ui.Label.new({ X = X + 5, Y = Y, W = W - 5, Text = Label }))
end

function Section.General(X, Y, W)
	local Settings = Server.Settings()
	Util.Field(X, Y, W, "Hostname", Settings.Hostname, function(Value)
		if (not Server.ValidHostname(Value)) then return "Use 1-24 letters, digits, - or _." end
		Settings.Hostname = Value
		os.setComputerLabel(Value)
		Server.Save()
		Util.Core().Announce()
	end)
	Util.Field(X, Y + 2, W, "Name", Settings.DisplayName, function(Value)
		if (#Value == 0 or #Value > 32) then return "Use 1-32 characters." end
		Settings.DisplayName = Value
		Server.Save()
	end)
	Page:Add(Ui.Label.new({ X = X, Y = Y + 4, W = W, H = 2, Fg = "SubText", Text = "Clients see the name in BlockDrive: BlockDrive > " .. Settings.DisplayName .. " > Shared." }))
	Page:Add(Ui.Button.new({ X = X, Y = Y + 7, Text = " Restart Server ", OnClick = function()
		if (Ui.Confirm("Restart", "Restart this computer? Clients reconnect automatically.", "Restart")) then os.reboot() end
	end }))
	Page:Add(Ui.Button.new({ X = X + 17, Y = Y + 7, Text = " Shut Down ", Style = "danger", OnClick = function()
		if (Ui.Confirm("Shut Down", "Shut down? BlockDrive will be unavailable until the computer is turned on again.", "Shut Down")) then os.shutdown() end
	end }))
end

function Section.Storage(X, Y, W)
	local Settings = Server.Settings()
	Util.Field(X, Y, W, "Location", Settings.StorageRoot, function(Value)
		local Ok, Err = Path.ValidRoot(Value)
		if (not Ok) then return Err end
		if (not Ui.Confirm("Storage location", "Serve files from /" .. fs.combine(Value, "") .. "? Existing files are not moved.", "Change")) then return nil end
		Settings.StorageRoot = "/" .. fs.combine(Value, "")
		Server.Save()
		Manager.Restart("blockdrive")
	end)
	Util.Field(X, Y + 2, W, "Quota MB", Settings.QuotaMB, function(Value)
		local Number = tonumber(Value)
		if (not Number or Number < 0) then return "Enter a number of megabytes, or 0 for no quota." end
		Settings.QuotaMB = Number
		Server.Save()
	end)
	Util.Field(X, Y + 4, W, "Max file KB", Settings.MaxFileKB, function(Value)
		local Number = tonumber(Value)
		if (not Number or Number < 0) then return "Enter a size in KB, or 0 for no limit." end
		Settings.MaxFileKB = Number
		Server.Save()
	end)
	Page:Add(Ui.Label.new({ X = X, Y = Y + 6, W = W, H = 2, Fg = "SubText", Text = "Shares are the top-level folders. Make new shares in Finder." }))
	Page:Add(Ui.Button.new({ X = X, Y = Y + 8, Text = " Open in Finder ", Style = "primary", OnClick = function()
		local Drive = Util.Drive()
		Host.Launch("finder", { Drive and Drive.Root() or Settings.StorageRoot })
	end }))
end

local ModeNames = { pool = "pooled", share = "own share", off = "unused" }

-- Disk drives, attached directly or over wired modems: pooled, shared on their own, or unused.
function Section.Disks(X, Y, W, H)
	local Settings = Server.Settings()
	Volumes.Refresh()
	Util.Switch(X, Y, W, "Use disk drives", "ShareDisks", function()
		Volumes.Refresh()
		os.queueEvent("blockcloud_storage")
		Build()
	end)
	Page:Add(Ui.Label.new({ X = X, Y = Y + 1, Text = "New disks" }))
	local Modes = { "pool", "share", "off" }
	local Selected = 1
	for Index, Mode in ipairs(Modes) do
		if (Mode == (Settings.DiskMode or "pool")) then Selected = Index end
	end
	Page:Add(Ui.Tabs.new({ X = X + 10, Y = Y + 1, W = math.min(27, W - 10), Items = { "Pool", "Own share", "Unused" }, Selected = Selected,
		OnChange = function(_, Index)
			Settings.DiskMode = Modes[Index]
			Server.Save()
			Volumes.Refresh()
			os.queueEvent("blockcloud_storage")
		end }))
	local Drive = Util.Drive()
	local Items = {}
	for _, Volume in ipairs(Volumes.List()) do
		local Free = Volume.Mode ~= "off" and Drive and Drive.FreeSpace(Volume.Root)
		table.insert(Items, {
			Text = Volume.Name, Volume = Volume, Icon = "\22",
			IconFg = Volume.Mode == "pool" and "Accent" or (Volume.Mode == "share" and colors.cyan or "SubText"),
			Right = ModeNames[Volume.Mode] .. (Free and ("  " .. Gfx.FormatSize(Free)) or "")
		})
	end
	if (#Items == 0) then
		Page:Add(Ui.Label.new({ X = X, Y = Y + 3, W = W, H = 5, Fg = "SubText",
			Text = "No disk drives with a disk. Attach disk drives directly or over wired modems; each disk adds its space to the pool, or becomes its own share." }))
		return
	end
	local List = Page:Add(Ui.List.new({ X = X, Y = Y + 3, W = W, H = math.max(2, H - 7), Items = Items, Bg = "Panel" }))
	List.Selected = 1
	Page:Add(Ui.Label.new({ X = X, Y = Y + H - 3, W = W, Fg = "SubText", Text = function()
		local Item = List.Items[List.Selected]
		local Volume = Item and Item.Volume
		if (not Volume) then return "" end
		return Volume.Side .. "  " .. Volume.Mount .. (Volume.ID and ("  id " .. Volume.ID) or "") .. (Volume.Label and ("  \"" .. Volume.Label .. "\"") or "")
	end }))
	local function SetMode(Mode)
		local Item = List.Items[List.Selected]
		if (not Item) then return end
		local Warning = Volumes.ModeWarning(Item.Volume, Mode)
		if (Warning and not Ui.Confirm("Disk", Warning, "Change")) then return end
		Volumes.SetMode(Item.Volume.Key, Mode)
		Log.Info("blockdrive", Item.Volume.Name .. " is now " .. ModeNames[Mode])
		Build()
	end
	local ButtonY = Y + H - 1
	Page:Add(Ui.Button.new({ X = X, Y = ButtonY, Text = " Pool ", OnClick = function() SetMode("pool") end }))
	Page:Add(Ui.Button.new({ X = X + 7, Y = ButtonY, Text = " Own Share ", OnClick = function() SetMode("share") end }))
	Page:Add(Ui.Button.new({ X = X + 19, Y = ButtonY, Text = " Unused ", OnClick = function() SetMode("off") end }))
	Page:Add(Ui.Button.new({ X = X + 28, Y = ButtonY, Text = " Rename ", OnClick = function()
		local Item = List.Items[List.Selected]
		local Name = Item and Ui.Prompt("Rename disk", "Name (the share name when it has its own share):", Item.Volume.Name)
		if (Name and Name ~= "" and Name ~= Item.Volume.Name) then
			local Ok, Err = Volumes.Rename(Item.Volume.Key, Name)
			if (not Ok) then Ui.Alert("Rename disk", Err) end
			Build()
		end
	end }))
end

function Section.Security(X, Y, W)
	local Settings = Server.Settings()
	-- Pairing is optional unless required here; visitors get the permission chosen below.
	Page:Add(Ui.Toggle.new({ X = X, Y = Y, Value = Settings.Public == false, OnChange = function(_, Value)
		Settings.Public = not Value
		Server.Save()
		Util.Core().Announce()
		Log.Info("auth", Value and "Pairing is now required (private server)" or "Server is now public: no pairing needed")
		Build()
	end }))
	Page:Add(Ui.Label.new({ X = X + 5, Y = Y, W = W - 5, Text = "Require pairing (private server)" }))
	if (Settings.Public ~= false) then
		Page:Add(Ui.Label.new({ X = X, Y = Y + 1, Text = "Visitors" }))
		Page:Add(Ui.Tabs.new({ X = X + 11, Y = Y + 1, W = math.min(26, W - 11), Items = { "Read only", "Read & write" },
			Selected = Settings.Visitors == "read" and 1 or 2, OnChange = function(_, Index)
				Settings.Visitors = Index == 1 and "read" or "write"
				Server.Save()
				Util.Core().Announce()
			end }))
	end
	Y = Y + 3
	Util.Switch(X, Y, W, "Accept pairing requests", "PairingOpen")
	Util.Switch(X, Y + 2, W, "Encrypt file transfers", "Encrypt", function()
		Util.Core().Announce()
	end)
	Page:Add(Ui.Label.new({ X = X, Y = Y + 4, Text = "Lock after" }))
	local Minutes = Page:Add(Ui.Input.new({ X = X + 11, Y = Y + 4, W = 4, Value = tostring(Settings.LockMinutes or 0) }))
	Page:Add(Ui.Label.new({ X = X + 16, Y = Y + 4, Text = "min idle", Fg = "SubText" }))
	Page:Add(Ui.Button.new({ X = X + W - 6, Y = Y + 4, W = 6, Text = "Set", OnClick = function()
		Settings.LockMinutes = math.max(0, tonumber(Minutes.Value) or 0)
		Server.Save()
		Util.Say("Auto-lock saved.")
	end }))
	Page:Add(Ui.Button.new({ X = X, Y = Y + 6, Text = Server.HasPassword() and " Change Password " or " Set Password ", OnClick = function()
		if (Server.HasPassword()) then
			local Old = Ui.Prompt("Password", "Current admin password:", "", "\7")
			if (not Old) then return end
			if (not Server.CheckPassword(Old)) then
				Ui.Alert("Password", "That is not the current password.")
				return
			end
		end
		local New = Ui.Prompt("Password", "New admin password (empty for none):", "", "\7")
		if (not New) then return end
		if (New ~= "" and Ui.Prompt("Password", "Type it again:", "", "\7") ~= New) then
			Ui.Alert("Password", "The passwords did not match.")
			return
		end
		Server.SetPassword(New)
		Log.Info("console", New == "" and "Admin password removed" or "Admin password changed")
		Build()
	end }))
	Page:Add(Ui.Button.new({ X = X + 19, Y = Y + 6, Text = " Lock Now ", Enabled = Server.HasPassword(), OnClick = function()
		State.Locked = true
		Host.SetLocked(true)
		Build()
	end }))
end

function Section.Updates(X, Y, W)
	local Settings = Server.Settings()
	local Service = Util.Updates()
	local Latest = Updater.State.Latest
	Page:Add(Ui.Label.new({ X = X, Y = Y, W = W, Text = "Installed: " .. Server.Version() .. (Latest and ("   Latest: " .. tostring(Latest.Version)) or "") }))
	Page:Add(Ui.Label.new({ X = X, Y = Y + 1, W = W, Fg = "Accent", Text = Service and Service.Message or "" }))
	Page:Add(Ui.Button.new({ X = X, Y = Y + 3, Text = " Check Now ", OnClick = function()
		os.queueEvent("blockcloud_update", "check")
		Util.Say("Checking for updates...")
	end }))
	Page:Add(Ui.Button.new({ X = X + 12, Y = Y + 3, Text = " Install Now ", Style = "primary", OnClick = function()
		os.queueEvent("blockcloud_update", "install")
		Util.Say("Installing in the background...")
	end }))
	if (Service and Service.Pending) then
		Page:Add(Ui.Button.new({ X = X + 26, Y = Y + 3, Text = " Restart ", OnClick = function() os.reboot() end }))
	end
	Util.Switch(X, Y + 5, W, "Check automatically", "AutoUpdate")
	Util.Switch(X, Y + 6, W, "Install in the background", "AutoInstall")
	Util.Switch(X, Y + 7, W, "Restart when no one is transferring", "AutoRestart")
	Util.Field(X, Y + 9, W, "Every (h)", Settings.UpdateHours, function(Value)
		local Number = tonumber(Value)
		if (not Number or Number < 1) then return "Enter a number of hours (1 or more)." end
		Settings.UpdateHours = Number
		Server.Save()
	end)
	Util.Field(X, Y + 11, W, "Channel", Settings.UpdateURL, function(Value)
		if (not Value:match("^https?://")) then return "Enter an http(s) URL ending in /." end
		Settings.UpdateURL = Value
		Server.Save()
	end)
end

function Section.Services(X, Y, W, H)
	local Items = {}
	for _, Status in ipairs(Manager.Status()) do
		table.insert(Items, { Text = Status.Title, Right = Status.State, Icon = "\7", IconFg = Dots[Status.Level] or "SubText", Status = Status })
	end
	local List = Page:Add(Ui.List.new({ X = X, Y = Y, W = W, H = math.min(#Items, H - 6), Items = Items, Bg = "Panel" }))
	List.Selected = 1
	local Detail = Page:Add(Ui.Label.new({ X = X, Y = Y + #Items + 1, W = W, H = 2, Fg = "SubText", Text = function()
		local Item = List.Items[List.Selected]
		return Item and (Item.Status.Detail or "") or ""
	end }))
	local ButtonY = Detail.Y + 3
	Page:Add(Ui.Button.new({ X = X, Y = ButtonY, Text = " Restart ", OnClick = function()
		local Item = List.Items[List.Selected]
		if (Item) then
			Manager.Restart(Item.Status.Name)
			Build()
		end
	end }))
	Page:Add(Ui.Button.new({ X = X + 10, Y = ButtonY, Text = " Enable/Disable ", OnClick = function()
		local Item = List.Items[List.Selected]
		if (not Item) then return end
		if (Item.Status.System) then
			Ui.Alert(Item.Status.Title, "This service is part of BlockCloud and is always on.")
			return
		end
		Manager.SetEnabled(Item.Status.Name, Item.Status.State == "disabled")
		Build()
	end }))
end

function Section.Appearance(X, Y, W)
	local Settings = Config.Settings()
	Page:Add(Ui.Label.new({ X = X, Y = Y, Text = "Mode" }))
	Page:Add(Ui.Tabs.new({ X = X + 8, Y = Y, W = 16, Items = { "Light", "Dark" }, Selected = Settings.Theme == "dark" and 2 or 1, OnChange = function(_, Index)
		Settings.Theme = Index == 2 and "dark" or "light"
		Config.Save("settings")
	end }))
	Page:Add(Ui.Label.new({ X = X, Y = Y + 2, Text = "Accent" }))
	Page:Add(Ui.Canvas.new({
		X = X + 8, Y = Y + 2, W = #Theme.Accents * 3, H = 1,
		OnDraw = function(Self, T)
			for Index, Color in ipairs(Theme.Accents) do
				Gfx.Write(T, Self.X + (Index - 1) * 3, Self.Y, Color == Settings.Accent and " \7 " or "   ", colors.white, Color)
			end
		end,
		OnEvent = function(Self, Name, _, MouseX)
			if (Name ~= "mouse_click") then return false end
			local Color = Theme.Accents[math.floor((MouseX - Self.X) / 3) + 1]
			if (Color) then
				Settings.Accent = Color
				Config.Save("settings")
			end
			return true
		end
	}))
end

function Tab.Settings(X, Y, W, H)
	local SideW = W >= 44 and 12 or 0
	local Side = Page:Add(Ui.List.new({ X = X, Y = Y, W = SideW, H = H, Bg = "Panel", SingleClick = true, Visible = SideW > 0 }))
	local Items = {}
	for _, Name in ipairs(Sections) do table.insert(Items, { Text = Name }) end
	Side:SetItems(Items)
	Side.Selected = State.Section
	Side.OnActivate = function(_, Index)
		State.Section = Index
		Build()
	end
	if (SideW == 0) then
		Page:Add(Ui.Button.new({ X = X, Y = Y, W = W, Text = "\31 " .. Sections[State.Section], Bg = "Panel", OnClick = function()
			local Index = Ui.Choose("Settings", Sections, State.Section)
			if (Index) then
				State.Section = Index
				Build()
			end
		end }))
		Y, H = Y + 2, H - 2
	end
	Section[Sections[State.Section]](X + SideW + (SideW > 0 and 1 or 0), Y, W - SideW - (SideW > 0 and 1 or 0), H)
end

--
-- Lock screen
--

function Util.BuildLock(W, H)
	local Settings = Server.Settings()
	local Logo = BlockOS.Require("logo")
	local LogoW, LogoH = Logo.Size(Logo.Small)
	local Top = math.max(2, math.floor((H - LogoH - 9) / 2))
	Page:Add(Ui.Canvas.new({ X = 1, Y = Top, W = W, H = LogoH, OnDraw = function(Self, T)
		Logo.Draw(T, math.floor((W - LogoW) / 2) + 1, Self.Y, Logo.Small)
	end }))
	Page:Add(Ui.Label.new({ X = 1, Y = Top + LogoH + 1, W = W, Align = "center", Fg = "Accent", Text = Settings.Hostname .. "  \7  " .. Settings.DisplayName }))
	local Errors = 0
	for _, Status in ipairs(Manager.Status()) do
		if (Status.Level == "error") then Errors = Errors + 1 end
	end
	Page:Add(Ui.Label.new({ X = 1, Y = Top + LogoH + 2, W = W, Align = "center", Fg = "SubText",
		Text = Errors == 0 and "All services running" or (Errors .. " service" .. (Errors == 1 and "" or "s") .. " need attention") }))
	local FieldW = math.min(24, W - 4)
	local Field = Page:Add(Ui.Input.new({ X = math.floor((W - FieldW) / 2) + 1, Y = Top + LogoH + 4, W = FieldW, Mask = "\7", Placeholder = "Admin password" }))
	Field.OnSubmit = function(_, Value)
		if (Server.CheckPassword(Value)) then
			State.Locked = false
			State.Message = nil
			Host.SetLocked(false)
			Host.LastInput = os.clock()
			Log.Info("console", "Console unlocked")
		else
			State.Message = "Wrong password."
			Field:SetValue("")
		end
		Build()
	end
	Page:Add(Ui.Label.new({ X = 1, Y = Top + LogoH + 6, W = W, Align = "center", Fg = colors.red, Text = function() return State.Message or "" end }))
	Page:SetFocus(Field)
end

--
-- Layout
--

function Build()
	Page:Clear()
	local W, H = Page.W, Page.H
	if (Host.Locked ~= State.Locked) then Host.SetLocked(State.Locked) end
	Page:Add(Ui.Canvas.new({ X = 1, Y = 1, W = W, H = 1, OnDraw = function(Self, T, Th)
		Gfx.Fill(T, 1, 1, W, 1, Th.TopbarBg)
		Gfx.Write(T, 2, 1, "\4 BlockOS Server", Th.TopbarFg, Th.TopbarBg)
		local Settings = Server.Settings()
		local Right = Settings.Hostname .. "  " .. textutils.formatTime(os.time("local"), true)
		Gfx.Write(T, W - #Right, 1, Right, Th.TopbarDim, Th.TopbarBg)
	end }))
	if (State.Locked) then
		Util.BuildLock(W, H)
		Page:Invalidate()
		return
	end
	local Names = {}
	for Index, Name in ipairs(Tabs) do
		Names[Index] = Name
	end
	local Pending = #Clients.PendingList()
	if (Pending > 0) then Names[3] = "Pairing " .. Pending end
	Page:Add(Ui.Tabs.new({ X = 1, Y = 2, W = W, Items = Names, Selected = State.Tab, OnChange = function(_, Index)
		State.Tab = Index
		State.Message = nil
		Build()
	end }))
	Tab[Tabs[State.Tab]](2, 4, W - 2, H - 5)
	-- Bottom bar: the one graphical app, an admin shell, and the last message.
	Page:Add(Ui.Panel.new({ X = 1, Y = H, W = W, H = 1, Bg = "Panel" }))
	Page:Add(Ui.Button.new({ X = 1, Y = H, Text = " \16 Finder ", Bg = "Panel", OnClick = function()
		local Drive = Util.Drive()
		Host.Launch("finder", { Drive and Drive.Root() or "/" })
	end }))
	Page:Add(Ui.Button.new({ X = 11, Y = H, Text = " >_ Shell ", Bg = "Panel", OnClick = function() Host.Launch("shell") end }))
	if (Server.HasPassword()) then
		Page:Add(Ui.Button.new({ X = 21, Y = H, Text = " Lock ", Bg = "Panel", OnClick = function()
			State.Locked = true
			Build()
		end }))
	end
	Page:Add(Ui.Label.new({ X = 28, Y = H, W = W - 28, Align = "right", Bg = "Panel", Fg = "SubText", Text = function() return State.Message or "" end }))
	Page:Invalidate()
end

function Page:OnLayout()
	Build()
end

local Refresh = { blockcloud_status = true, blockcloud_clients = true, blockcloud_storage = true, blockcloud_config = true, peripheral = true, peripheral_detach = true }

function Page:OnEvent(Name, A)
	if (Name == "timer" and A == State.RebuildTimer) then
		State.RebuildTimer = nil
		-- Avoid rebuilding under the admin's fingers in Settings, where fields hold typed text.
		if (Tabs[State.Tab] ~= "Settings" or State.Locked) then Build() end
		return true
	elseif (Refresh[Name]) then
		Util.Soon()
		if (Name == "blockcloud_clients" and #Clients.PendingList() > 0) then
			Util.Say("A computer is waiting to pair.")
		end
	elseif (Name == "blockcloud_log" and Tabs[State.Tab] == "Logs") then
		Util.Soon()
	end
	return false
end

function Page:OnTerminate() end

-- The clock, uptime and auto-lock tick slowly: nothing here needs to redraw often.
Page:SetInterval(15, function()
	local Minutes = tonumber(Server.Settings().LockMinutes) or 0
	if (not State.Locked and Server.HasPassword() and Minutes > 0 and os.clock() - Host.LastInput > Minutes * 60) then
		State.Locked = true
		Log.Info("console", "Console locked after " .. Minutes .. " idle minutes")
		Build()
		return true
	end
	if (Tabs[State.Tab] == "Overview" and not State.Locked) then Build() end
	return true
end)

Page:Run()
]=]
Files["blockos/server/ui/host.lua"] = [[
-- Server Edition app host: runs the admin console, Finder (the only graphical app) and admin
-- shells, one full-screen at a time under a BlockOS-style title bar. Much lighter than the
-- desktop window manager: no dock, Launchpad, animations or overlapping windows.

local Gfx = BlockOS.Require("gfx")
local Theme = BlockOS.Require("theme")
local Apps = BlockOS.Require("apps")
local Log = BlockOS.Require("server/log")

local Host = {}

local Native, RootShell
local W, H = 51, 19
local Console = nil
local Procs = {}
local Front = nil
local CurrentProc = nil
local NextID = 1
local Fake

Host.Locked = false
Host.LastInput = os.clock()

local InputEvents = {
	mouse_click = true, mouse_drag = true, mouse_up = true, mouse_scroll = true,
	key = true, key_up = true, char = true, paste = true
}

local function Visible()
	return Front or Console
end

local function DrawBar()
	if (not Front) then return end
	local Th = Theme.Get()
	Gfx.Fill(Native, 1, 1, W, 1, Th.TopbarBg)
	Gfx.Write(Native, 1, 1, " x ", colors.white, Th.Close)
	Gfx.Write(Native, 5, 1, "\17 Console", Th.Accent, Th.TopbarBg)
	local Title = Gfx.Truncate(Front.Title, W - 22)
	Gfx.Write(Native, math.floor((W - #Title) / 2) + 1, 1, Title, Th.TopbarFg, Th.TopbarBg)
	local Clock = textutils.formatTime(os.time("local"), true)
	Gfx.Write(Native, W - #Clock, 1, Clock, Th.TopbarDim, Th.TopbarBg)
end

local function Show()
	for _, Proc in ipairs(Procs) do
		Proc.Window.setVisible(Proc == Front)
	end
	if (Console) then Console.Window.setVisible(Front == nil) end
	if (not Console and not Front) then return end
	DrawBar()
	local Target = Visible()
	if (Target) then
		Target.Window.redraw()
		Target.Window.restoreCursor()
	end
end

local function Remove(Proc)
	for Index, Other in ipairs(Procs) do
		if (Other == Proc) then
			table.remove(Procs, Index)
			break
		end
	end
	Proc.Dead = true
	Proc.Window.setVisible(false)
	if (Front == Proc) then Front = Procs[#Procs] end
	Show()
end

local function Resume(Proc, ...)
	if (Proc.Dead) then return end
	local Name = ...
	if (Name and Proc.Filter and Proc.Filter ~= Name and Name ~= "terminate") then return end
	local Previous = term.redirect(Proc.Window)
	local PreviousProc = CurrentProc
	CurrentProc = Proc
	local Ok, Result = coroutine.resume(Proc.Co, ...)
	CurrentProc = PreviousProc
	term.redirect(Previous)
	if (not Ok) then
		Log.Error("ui", Proc.Title .. ": " .. tostring(Result))
		if (Proc == Console) then
			error(Result, 0)
		end
		Remove(Proc)
	elseif (coroutine.status(Proc.Co) == "dead" or Proc.Closing) then
		if (Proc == Console) then
			error("The console exited", 0)
		end
		Remove(Proc)
	else
		Proc.Filter = Result
	end
end

local function Spawn(Opts)
	local Proc = { ID = NextID, Title = Opts.Title, AppID = Opts.AppID }
	NextID = NextID + 1
	if (Opts.Console) then
		Proc.Window = window.create(Native, 1, 1, W, H, true)
	else
		Proc.Window = window.create(Native, 1, 2, W, H - 1, false)
	end
	Proc.Co = coroutine.create(Opts.Fn)
	if (Opts.Console) then
		Console = Proc
	else
		table.insert(Procs, Proc)
		Front = Proc
		Show()
	end
	Resume(Proc)
	return Proc
end

local function Quote(Arg)
	Arg = tostring(Arg)
	if (Arg == "" or Arg:find("[%s\"]")) then
		return "\"" .. Arg:gsub("\"", "") .. "\""
	end
	return Arg
end

-- Runs a program in a fresh CraftOS shell so it gets its own shell API, like the desktop does.
local function ProgramFn(Path, Args, Hold)
	return function()
		local List = { "/blockos/sys/run.lua", Hold and "hold" or "nohold", Quote(Path) }
		for _, Arg in ipairs(Args or {}) do
			table.insert(List, Quote(Arg))
		end
		os.run({ shell = RootShell, multishell = Fake }, "/rom/programs/shell.lua", table.unpack(List))
	end
end

local function Post(Proc, ...)
	Resume(Proc, ...)
end

local function Find(AppID)
	for _, Proc in ipairs(Procs) do
		if (Proc.AppID == AppID) then return Proc end
	end
	return nil
end

function Host.Launch(Target, Args, Opts)
	Opts = Opts or {}
	if (Host.Locked) then return nil, "The console is locked" end
	if (Target == "finder") then
		local Existing = Find("finder")
		if (Existing) then
			Front = Existing
			Show()
			if (Args and Args[1]) then Post(Existing, "blockos_open", Args[1]) end
			return Existing.ID
		end
		local App = Apps.Get("finder")
		return Spawn({ Title = "Finder", AppID = "finder", Fn = ProgramFn(App.Path, Args, false) }).ID
	elseif (Target == "terminal" or Target == "shell") then
		local Dir = Args and Args[1]
		return Spawn({ Title = "Shell", AppID = "shell", Fn = function()
			term.setBackgroundColor(colors.black)
			term.clear()
			term.setCursorPos(1, 1)
			term.setTextColor(colors.yellow)
			print("BlockOS Server shell. 'bcloud' manages the server;")
			print("'exit' returns to the console.")
			term.setTextColor(colors.white)
			local Env = { shell = RootShell, multishell = Fake }
			if (Dir and fs.isDir(Dir)) then
				os.run(Env, "/rom/programs/shell.lua", "/rom/programs/cd.lua", Dir)
			end
			os.run(Env, "/rom/programs/shell.lua")
		end }).ID
	elseif (Target == "editor" or Target == "edit") then
		local Path = Args and Args[1]
		if (not Path) then return nil, "No file given" end
		return Spawn({ Title = "Edit " .. fs.getName(Path), AppID = "edit", Fn = ProgramFn("/rom/programs/edit.lua", { Path }, false) }).ID
	end
	local Path = type(Target) == "string" and Target
	if (Path and not fs.exists(Path)) then Path = RootShell.resolveProgram(Path) end
	if (Path and fs.exists(Path) and not fs.isDir(Path)) then
		return Spawn({ Title = fs.getName(Path), Fn = ProgramFn(Path, Args, Opts.Hold ~= false) }).ID
	end
	return nil, tostring(Target) .. " is not available on BlockOS Server"
end

-- Folders open in Finder; files open in the CraftOS editor (nothing runs by accident).
function Host.Open(Path)
	if (not fs.exists(Path)) then return false end
	if (fs.isDir(Path)) then
		Host.Launch("finder", { Path })
	else
		Host.Launch("editor", { Path })
	end
	return true
end

function Host.ShowConsole()
	Front = nil
	Show()
end

function Host.Apps()
	return Procs
end

-- Locking hides every app until the administrator unlocks the console.
function Host.SetLocked(Locked)
	Host.Locked = Locked
	if (Locked) then Front = nil end
	Show()
end

local function InstallAPI()
	BlockOS.Desktop = false
	BlockOS.Shell = RootShell
	BlockOS.Clipboard = BlockOS.Clipboard or {}
	BlockOS.Launch = Host.Launch
	BlockOS.Open = Host.Open
	BlockOS.ShowConsole = Host.ShowConsole
	BlockOS.Notify = function(Title, Text)
		Log.Info("notice", tostring(Title) .. ": " .. tostring(Text))
	end
	BlockOS.SetTitle = function(Title)
		if (CurrentProc and CurrentProc ~= Console) then
			CurrentProc.Title = tostring(Title)
			DrawBar()
		end
	end
	BlockOS.Current = function()
		local Proc = CurrentProc
		if (not Proc) then return nil end
		return { ID = Proc.ID, AppID = Proc.AppID, Title = Proc.Title, Fullscreen = true, Focused = Proc == Visible() }
	end
	BlockOS.IsFocused = function() return CurrentProc ~= nil and CurrentProc == Visible() end
	BlockOS.SetFullscreen = function() end
	BlockOS.Minimize = function() Host.ShowConsole() end
	BlockOS.Quit = function()
		if (CurrentProc and CurrentProc ~= Console) then CurrentProc.Closing = true end
	end
	BlockOS.SetCloseHandler = function(Value)
		if (CurrentProc) then CurrentProc.CloseHandler = Value and true or nil end
	end
	BlockOS.Processes = function()
		local List = {}
		for _, Proc in ipairs(Procs) do
			table.insert(List, { ID = Proc.ID, AppID = Proc.AppID, Title = Proc.Title })
		end
		return List
	end
	BlockOS.Restart = function() os.reboot() end
	BlockOS.Shutdown = function() os.shutdown() end
	BlockOS.ScreenSize = function() return W, H end
	Fake = {
		getCurrent = function() return CurrentProc and CurrentProc.ID or 0 end,
		getCount = function() return #Procs end,
		getFocus = function() return Front and Front.ID or 0 end,
		setFocus = function() return false end,
		getTitle = function(ID)
			for _, Proc in ipairs(Procs) do if (Proc.ID == ID) then return Proc.Title end end
		end,
		setTitle = function(ID, Title)
			for _, Proc in ipairs(Procs) do if (Proc.ID == ID) then Proc.Title = tostring(Title) end end
			DrawBar()
		end,
		launch = function(Env, Path, ...)
			local Args = table.pack(...)
			return Spawn({ Title = fs.getName(Path), Fn = function() os.run(Env, Path, table.unpack(Args, 1, Args.n)) end }).ID
		end
	}
	BlockOS.Multishell = Fake
end

local function CloseFront()
	local Proc = Front
	if (not Proc) then return end
	if (Proc.CloseHandler) then
		Resume(Proc, "blockos_close")
	else
		Remove(Proc)
	end
end

function Host.Start(Shell)
	RootShell = Shell
	Native = term.current()
	W, H = Native.getSize()
	InstallAPI()
	Spawn({ Title = "Console", Console = true, Fn = function()
		BlockOS.Load("/blockos/server/ui/console.lua", Host)
	end })
	Show()
end

-- Called by the runtime with every event, after the services have seen it.
function Host.Dispatch(Event)
	local Name = Event[1]
	if (not Console) then
		-- The console kept crashing: wait for R to try again. Services are unaffected.
		if (Name == "key" and Event[2] == keys.r) then
			Host.Crashes = {}
			Host.Recover()
		end
		return
	end
	if (InputEvents[Name]) then
		Host.LastInput = os.clock()
		if (Front and Name == "mouse_click" and Event[4] == 1) then
			if (Event[3] <= 3) then
				CloseFront()
			elseif (Event[3] <= 13) then
				Host.ShowConsole()
			end
			return
		end
		local Target = Visible()
		if (Front and (Name == "mouse_click" or Name == "mouse_drag" or Name == "mouse_up" or Name == "mouse_scroll")) then
			if (Event[4] < 2) then return end
			Resume(Target, Name, Event[2], Event[3], Event[4] - 1)
		else
			Resume(Target, table.unpack(Event, 1, Event.n))
		end
	elseif (Name == "terminate") then
		-- Ctrl+T stops a program in the shell or closes Finder, but never the console.
		if (Front) then Resume(Front, "terminate") end
	elseif (Name == "term_resize") then
		W, H = Native.getSize()
		Console.Window.reposition(1, 1, W, H)
		for _, Proc in ipairs(Procs) do
			Proc.Window.reposition(1, 2, W, H - 1)
		end
		Resume(Console, "term_resize")
		for _, Proc in ipairs({ table.unpack(Procs) }) do Resume(Proc, "term_resize") end
		Show()
	else
		Resume(Console, table.unpack(Event, 1, Event.n))
		for _, Proc in ipairs({ table.unpack(Procs) }) do
			Resume(Proc, table.unpack(Event, 1, Event.n))
		end
		if (Front and Name == "timer") then DrawBar() end
	end
	local Target = Visible()
	if (Target and not Target.Dead) then Target.Window.restoreCursor() end
end

Host.Crashes = {}

-- If the console crashes, start a fresh one; the services were never affected.
function Host.Recover()
	Console = nil
	Front = nil
	local Now = os.clock()
	table.insert(Host.Crashes, Now)
	while (Host.Crashes[1] and Now - Host.Crashes[1] > 60) do table.remove(Host.Crashes, 1) end
	if (#Host.Crashes > 3) then
		Log.Error("ui", "The console keeps crashing; showing the fallback screen")
		term.redirect(Native)
		Native.setBackgroundColor(colors.black)
		Native.setTextColor(colors.white)
		Native.clear()
		Native.setCursorPos(1, 1)
		print("BlockOS Server: the console keeps crashing.")
		print("BlockCloud services are still running.")
		print("Details: /blockos/data/cloud/logs/server.log")
		print()
		print("Press R to try again, or reboot holding S on the")
		print("boot screen for a recovery shell.")
		return
	end
	Log.Warn("ui", "Restarting the console")
	Spawn({ Title = "Console", Console = true, Fn = function()
		BlockOS.Load("/blockos/server/ui/console.lua", Host)
	end })
	Show()
end

return Host
]]
Files["blockos/server/volumes.lua"] = [[
-- Storage volumes for BlockDrive. The main storage folder and the server's disk drives
-- (attached directly or over wired modems, up to a hundred or more) are combined:
--
--   pool   (default) the disk joins the main storage as one pooled space. Shares are the
--          top-level folders of the pool, so "Shared" spans every pooled disk. Each file lives
--          whole on one disk; new files go where their folder already is, or to the emptiest disk.
--   share  the disk is its own share, named after its label or ID.
--   off    the disk is not used.
--
-- A disk's files live in a "blockcloud" folder on it, so nothing else on the disk is exposed
-- (a client could otherwise write a startup file that runs wherever the floppy goes next).
-- Settings follow the floppy's ID, not its diskN mount name, which can change between boots.

local Server = BlockOS.Require("server/config")
local Path = BlockOS.Require("cloud/path")
local Log = BlockOS.Require("server/log")

local Volumes = {}

Volumes.Folder = "blockcloud"
Volumes.Modes = { pool = true, share = true, off = true }

local Current = {}
local ByName = {}
local Pool = {}
local Prepared = {}
local Started = false

function Volumes.Primary()
	return "/" .. fs.combine(Server.Settings().StorageRoot, "")
end

function Volumes.TempDir(Root)
	return "/" .. fs.combine(Root, Path.Reserved .. "/tmp")
end

local function KeyOf(Side, Mount)
	local Ok, ID = pcall(disk.getID, Side)
	if (Ok and ID) then return "id" .. ID, ID end
	return "drive:" .. Side, nil
end

local function DefaultName(Label, ID, Side)
	if (Label and Path.ValidName(Label)) then return Label end
	if (ID) then return "Disk " .. ID end
	return Side
end

-- Natural order, so "Disk 9" sorts before "Disk 10".
local function NaturalLess(A, B)
	local function Key(Text)
		return (Text:lower():gsub("%d+", function(Digits) return string.format("%012d", tonumber(Digits)) end))
	end
	return Key(A) < Key(B)
end

-- Creates the disk's folder and clears staging files left by a shutdown or an eject.
local function Prepare(Volume)
	local Marker = Volume.Key .. "@" .. Volume.Mount
	if (Prepared[Marker]) then return end
	if (not fs.exists(Volume.Root)) then fs.makeDir(Volume.Root) end
	local Temp = Volumes.TempDir(Volume.Root)
	if (fs.exists(Temp)) then fs.delete(Temp) end
	fs.makeDir(Temp)
	Prepared[Marker] = true
	if (Started) then
		Log.Info("blockdrive", "Using disk " .. Volume.Name .. " (" .. Volume.Side .. ", " .. Volume.Mode .. ")")
	end
end

-- Looks at the attached drives again. Returns true when the shared disks changed.
function Volumes.Refresh()
	local Settings = Server.Settings()
	local Saved = Settings.Disks or {}
	local Default = Volumes.Modes[Settings.DiskMode] and Settings.DiskMode or "pool"
	local Primary = Volumes.Primary()
	local List = {}
	for _, Side in ipairs(peripheral.getNames()) do
		local Ok, Type = pcall(peripheral.getType, Side)
		if (Ok and Type == "drive" and disk.hasData(Side)) then
			local MountName = disk.getMountPath(Side)
			local Mount = MountName and ("/" .. MountName)
			-- The disk holding the main storage folder is already part of it.
			if (Mount and Primary ~= Mount and Primary:sub(1, #Mount + 1) ~= Mount .. "/") then
				local Key, ID = KeyOf(Side, Mount)
				local Options = Saved[Key] or {}
				local Label = disk.getLabel(Side)
				local Mode = Options.Mode or (Options.Enabled == false and "off") or Default
				if (Settings.ShareDisks == false) then Mode = "off" end
				table.insert(List, {
					Key = Key, ID = ID, Side = Side, Mount = Mount, Label = Label,
					Root = "/" .. fs.combine(Mount, Volumes.Folder),
					Name = Options.Name or DefaultName(Label, ID, Side),
					Mode = Mode
				})
			end
		end
	end
	table.sort(List, function(A, B) return NaturalLess(A.Name, B.Name) end)
	local Names, NewPool, Signature = {}, { Primary }, {}
	for _, Volume in ipairs(List) do
		if (Volume.Mode == "share" and (Names[Volume.Name] or fs.isDir(fs.combine(Primary, Volume.Name)))) then
			-- Share names must be unique and must not hide a folder in the main storage.
			Volume.Name = Volume.Name .. " (" .. Volume.Side .. ")"
		end
		if (Volume.Mode ~= "off") then
			local Ok, Err = pcall(Prepare, Volume)
			if (not Ok) then
				Volume.Error = tostring(Err)
				Volume.Mode = "off"
				Log.Warn("blockdrive", "Cannot use disk " .. Volume.Name .. ": " .. Volume.Error)
			end
		end
		if (Volume.Mode == "share") then
			Names[Volume.Name] = Volume
		elseif (Volume.Mode == "pool") then
			table.insert(NewPool, Volume.Root)
		end
		if (Volume.Mode ~= "off") then table.insert(Signature, Volume.Mode .. ":" .. Volume.Name .. "=" .. Volume.Root) end
	end
	local Before = {}
	for _, Volume in ipairs(Current) do
		if (Volume.Mode ~= "off") then table.insert(Before, Volume.Mode .. ":" .. Volume.Name .. "=" .. Volume.Root) end
	end
	local Changed = table.concat(Before, "|") ~= table.concat(Signature, "|")
	Current, ByName, Pool = List, Names, NewPool
	if (not Started) then
		Started = true
		local Pooled, Shared = #NewPool - 1, 0
		for _ in pairs(Names) do Shared = Shared + 1 end
		if (#List > 0) then
			Log.Info("blockdrive", #List .. " disk" .. (#List == 1 and "" or "s") .. ": " .. Pooled .. " pooled, " .. Shared .. " shared on their own")
		end
	end
	return Changed
end

-- Every attached disk: Key, ID, Side, Mount, Label, Root, Name, Mode.
function Volumes.List()
	return Current
end

-- A disk shared on its own, by share name.
function Volumes.Get(Name)
	return ByName[Name]
end

-- Roots of the pooled space: the main storage folder first, then the pooled disks.
function Volumes.Pool()
	return Pool
end

-- Every folder that holds BlockDrive files.
function Volumes.Roots()
	local Roots = {}
	for _, Root in ipairs(Pool) do table.insert(Roots, Root) end
	for _, Volume in ipairs(Current) do
		if (Volume.Mode == "share" and ByName[Volume.Name] == Volume) then table.insert(Roots, Volume.Root) end
	end
	return Roots
end

-- Where a remote path lives: { Normal, Rel (path inside each root), Roots, Space ("pool" or the
-- disk's key), Volume (own-share disk or nil) }, or nil and an error code.
function Volumes.Target(Remote)
	local Normal, Err = Path.Normalize(Remote)
	if (not Normal) then return nil, Err end
	local Top = Normal:match("^[^/]+")
	local Volume = Top and ByName[Top]
	if (Volume) then
		return { Normal = Normal, Rel = Normal:sub(#Top + 2), Roots = { Volume.Root }, Space = Volume.Key, Volume = Volume }
	end
	return { Normal = Normal, Rel = Normal, Roots = Pool, Space = "pool" }
end

-- The local path of Rel inside Root (containment checked again, as a second line of defence).
function Volumes.Local(Root, Rel)
	local Local, Err = Path.Resolve(Root, Rel)
	if (not Local) then error({ BlockCloud = true, Code = Err }, 0) end
	return Local
end

local function Modified(Local)
	local Ok, Attributes = pcall(fs.attributes, Local)
	return Ok and Attributes and Attributes.modified or 0
end

-- Every root where the path exists: { Root, Local, Dir }.
function Volumes.Find(Target)
	local Found = {}
	for _, Root in ipairs(Target.Roots) do
		local Local = Volumes.Local(Root, Target.Rel)
		if (fs.exists(Local)) then
			table.insert(Found, { Root = Root, Local = Local, Dir = fs.isDir(Local) })
		end
	end
	return Found
end

-- The copy a client sees: a folder if any root has one, otherwise the newest file (so an
-- update that moved a file to another disk wins even if the old copy was not yet deleted).
function Volumes.Locate(Target)
	local Best
	for _, Part in ipairs(Volumes.Find(Target)) do
		if (Part.Dir) then return Part end
		Part.Modified = Modified(Part.Local)
		if (not Best or Part.Modified > Best.Modified) then Best = Part end
	end
	return Best
end

function Volumes.IsDir(Target)
	local Part = Volumes.Locate(Target)
	return Part ~= nil and Part.Dir
end

-- Picks the root for Size new bytes: one where the parent folder already is, if it fits
-- there, otherwise the one with the most free space. Free(Root) gives usable bytes.
function Volumes.Place(Target, Size, Free, Prefer)
	if (Prefer and Free(Prefer) >= Size) then return Prefer end
	local Parent = Path.Parent(Target.Rel)
	local Best, BestFree
	for _, Root in ipairs(Target.Roots) do
		local Space = Free(Root)
		if (Space >= Size) then
			if (fs.isDir(Volumes.Local(Root, Parent))) then return Root end
			if (not Best or Space > BestFree) then Best, BestFree = Root, Space end
		end
	end
	return Best
end

-- Files a disk holds for BlockDrive, for warnings before a disk leaves the pool or a share.
function Volumes.FileCount(Volume)
	local function Count(Dir)
		if (not fs.isDir(Dir)) then return fs.exists(Dir) and 1 or 0 end
		local Total = 0
		for _, Name in ipairs(fs.list(Dir)) do
			if (Name ~= Path.Reserved) then Total = Total + Count(fs.combine(Dir, Name)) end
		end
		return Total
	end
	local Ok, Total = pcall(Count, Volume.Root)
	return Ok and Total or 0
end

-- How many disks are pooled, shared on their own, or unused.
function Volumes.Summary()
	local Counts = { pool = 0, share = 0, off = 0 }
	for _, Volume in ipairs(Current) do Counts[Volume.Mode] = (Counts[Volume.Mode] or 0) + 1 end
	return Counts
end

-- What changing a disk's mode does to the files on it, or nil if nothing visible changes.
function Volumes.ModeWarning(Volume, Mode)
	if (Volume.Mode == Mode or Volume.Mode == "off") then return nil end
	local Files = Volumes.FileCount(Volume)
	if (Files == 0) then return nil end
	local Where = Volume.Mode == "pool" and "the pool" or ("the " .. Volume.Name .. " share")
	return Volume.Name .. " holds " .. Files .. " file" .. (Files == 1 and "" or "s") .. " in " .. Where
		.. ". They stay on the disk but BlockDrive users will " .. (Mode == "off" and "not see them" or "see them in a different place")
		.. " until the disk is set back."
end

local function Save(Key, Field, Value)
	local Settings = Server.Settings()
	Settings.Disks = Settings.Disks or {}
	Settings.Disks[Key] = Settings.Disks[Key] or {}
	Settings.Disks[Key][Field] = Value
	Server.Save()
	Volumes.Refresh()
	os.queueEvent("blockcloud_storage")
end

-- Renames a disk (its share name when shared on its own). Returns true or nil, message.
function Volumes.Rename(Key, Name)
	if (not Path.ValidName(Name)) then return nil, "That is not a valid name." end
	for _, Volume in ipairs(Current) do
		if (Volume.Key ~= Key and Volume.Name == Name) then return nil, "Another disk already uses that name." end
	end
	if (fs.isDir(fs.combine(Volumes.Primary(), Name))) then return nil, "A share in the pool already uses that name." end
	Save(Key, "Name", Name)
	return true
end

-- Mode is "pool", "share" or "off".
function Volumes.SetMode(Key, Mode)
	if (not Volumes.Modes[Mode]) then return nil, "Use pool, share or off." end
	Save(Key, "Mode", Mode)
	return true
end

return Volumes
]]
Files["blockos/sys/run.lua"] = [[
-- Runs a program inside a desktop window and optionally waits before the window closes.

local Args = { ... }
local Hold = table.remove(Args, 1) == "hold"
local Path = table.remove(Args, 1)

local Ok
if (shell.execute) then
	Ok = shell.execute(Path, table.unpack(Args))
else
	Ok = shell.run(Path, table.unpack(Args))
end

if (Hold or not Ok) then
	term.setTextColor(colors.lightGray)
	print()
	print(Ok and "Process finished." or "Process exited with an error.")
	write("Press any key to close this window.")
	os.pullEvent("key")
end
]]

local Loaded = {}
local Fresh = { ui = true }
-- Kept on every install and update: settings, users, paired clients, logs, and desktop apps.
local Protected = { ["blockos/data"] = true, ["blockos/userapps"] = true }

local Options = { Yes = false }
do
	local Args = { ... }
	local Index = 1
	while (Args[Index]) do
		local Arg = Args[Index]
		if (Arg == "--yes" or Arg == "-y") then
			Options.Yes = true
		elseif (Arg == "--private") then
			Options.Private = true
		elseif (Arg:sub(1, 2) == "--" and Args[Index + 1]) then
			Options[Arg:sub(3)] = Args[Index + 1]
			Index = Index + 1
		end
		Index = Index + 1
	end
end

local function Key(Path)
	return (Path:gsub("^/+", ""))
end

local function WriteFile(Path, Content)
	local Dir = fs.getDir(Path)
	if (Dir ~= "" and not fs.exists(Dir)) then fs.makeDir(Dir) end
	local Handle = fs.open(Path, "w")
	if (not Handle) then error("Cannot write " .. Path, 0) end
	Handle.write(Content)
	Handle.close()
end

local function ReadVersion()
	if (not fs.exists("/blockos/version.txt")) then return "unknown" end
	local Handle = fs.open("/blockos/version.txt", "r")
	local Text = (Handle.readAll() or ""):gsub("%s+", "")
	Handle.close()
	return Text
end

local function SortedPaths()
	local List = {}
	for Path in pairs(Files) do table.insert(List, Path) end
	table.sort(List)
	return List
end

-- Removes system files under /blockos that this release does not ship: the desktop when
-- replacing it, or files dropped from an older Server Edition. Protected folders are untouched.
local function Clean(Dir)
	for _, Name in ipairs(fs.list(Dir)) do
		local Path = fs.combine(Dir, Name)
		if (not Protected[Path] and Path ~= "blockos/version.txt") then
			if (fs.isDir(Path)) then
				Clean(Path)
				if (#fs.list(Path) == 0) then fs.delete(Path) end
			elseif (not Files[Path]) then
				fs.delete(Path)
			end
		end
	end
end

local function InstallFiles(Progress)
	if (fs.exists("startup.lua") and not fs.exists("blockos")) then
		if (fs.exists("startup.lua.bak")) then fs.delete("startup.lua.bak") end
		fs.move("startup.lua", "startup.lua.bak")
	end
	if (fs.isDir("blockos")) then Clean("blockos") end
	local List = SortedPaths()
	for Index, Path in ipairs(List) do
		if (Progress) then Progress(Index - 1, #List, Path) end
		WriteFile(Path, Files[Path])
		if (Index % 6 == 0) then sleep(0) end
	end
	WriteFile("blockos/version.txt", Version)
	-- Boot Server Edition even when a disk with its own startup file is inserted.
	settings.set("shell.allow_disk_startup", false)
	settings.save()
	if (Progress) then Progress(#List, #List, "Done") end
end

local function Ask(Question)
	if (Options.Yes) then return true end
	while (true) do
		write(Question .. " (y/n) ")
		local Answer = (read() or ""):lower():sub(1, 1)
		if (Answer == "y") then return true end
		if (Answer == "n") then return false end
	end
end

_G.BlockOS = { Root = "/blockos", Installer = true, Version = Version, Edition = "server" }

function BlockOS.Load(Path, ...)
	local Source = Files[Key(Path)]
	local Fn, Err
	if (Source) then
		Fn, Err = load(Source, "@/" .. Key(Path), "t", _G)
	else
		Fn, Err = loadfile(Path, nil, _G)
	end
	if (not Fn) then error(Err, 2) end
	return Fn(...)
end

function BlockOS.Require(Name)
	if (Loaded[Name]) then return Loaded[Name] end
	local Path = (Name:sub(1, 7) == "server/") and ("/blockos/" .. Name .. ".lua") or ("/blockos/lib/" .. Name .. ".lua")
	local Module = BlockOS.Load(Path)
	if (not Fresh[Name]) then Loaded[Name] = Module end
	return Module
end

math.randomseed(os.epoch("utc") + os.getComputerID())

term.setBackgroundColor(colors.black)
term.clear()
term.setCursorPos(1, 1)
if (term.isColor()) then term.setTextColor(colors.lime) end
print("BlockOS Server Edition " .. Version .. " installer")
if (term.isColor()) then term.setTextColor(colors.white) end

if (turtle or pocket) then
	print("Server Edition is for computers in the Data Center, not turtles or pocket computers.")
	return
end

local Server = BlockOS.Require("server/config")
local ServerInstalled = fs.exists("/blockos/server/boot.lua")
local DesktopInstalled = not ServerInstalled and (fs.exists("/blockos/sys/desktop.lua") or fs.exists("/blockos/boot.lua"))

if (ServerInstalled) then
	print("BlockOS Server " .. ReadVersion() .. " is installed here.")
	print("Updating keeps stored files, paired clients and settings.")
	if (not Ask("Update to " .. Version .. "?")) then return end
elseif (DesktopInstalled) then
	print("This computer runs the BlockOS " .. ReadVersion() .. " desktop.")
	print()
	print("Server Edition REPLACES the desktop; a computer runs one edition. Desktop apps (Messages, bTunes, App Store...) are removed.")
	print("Kept: /home, users and settings in /blockos/data, and installed apps (unused by the server).")
	print("To switch back, run the desktop installer from the main branch; your data stays.")
	print()
	if (not Ask("Replace the desktop with Server Edition?")) then return end
elseif (fs.exists("startup.lua")) then
	print("Your startup.lua will be kept as startup.lua.bak.")
end

local Configured = Server.Settings().Configured
if (ServerInstalled and Configured) then
	InstallFiles(function(Done, Total, Path)
		local _, Y = term.getCursorPos()
		term.setCursorPos(1, Y)
		term.clearLine()
		write(string.format("[%3d%%] %s", math.floor(Done / math.max(Total, 1) * 100), Path:sub(1, 40)))
	end)
	print()
	print("Updated. Rebooting...")
	sleep(1)
	os.reboot()
	return
end

local Setup = BlockOS.Load("/blockos/server/setup.lua")
if (Options.Yes) then
	InstallFiles()
	local State = {
		Hostname = Options.hostname or os.getComputerLabel() or ("server" .. os.getComputerID()),
		DisplayName = Options.name or "Data Center",
		StorageRoot = Options.storage or "/blockcloud/storage",
		Password = Options.password or "",
		AutoUpdate = true,
		AutoInstall = true,
		Public = not Options.Private,
		Visitors = Options.visitors == "read" and "read" or "write"
	}
	if (not Server.ValidHostname(State.Hostname)) then State.Hostname = "server" .. os.getComputerID() end
	Setup.Finish(State)
	print("Installed " .. State.Hostname .. ". Rebooting...")
	sleep(1)
	os.reboot()
elseif (term.isColor()) then
	local State = Setup.Run({ Mode = "install", Version = Version, Install = InstallFiles })
	if (State and State.Finished) then os.reboot() end
else
	Setup.RunText({ Install = InstallFiles })
	print("Rebooting...")
	sleep(1)
	os.reboot()
end
